ity'', ''start_packet_render'', true);\n  update public.packet_render_jobs set status = ''rendering'' where id = p_job_id;\n  perform set_config(''rcap.packet_mutation_authority'', '''', true);\n  return true;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"policies:packet_credit_ledger":[],"column:packet_credit_ledger.id":{"type":"uuid","default":"gen_random_uuid()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"table:consumer_briefcase_items":{"rls":true,"owner":"postgres","forceRls":false,"publicAcl":[],"privileges":{"anon":{"DELETE":true,"INSERT":false,"SELECT":true,"UPDATE":false,"TRIGGER":true,"TRUNCATE":true,"REFERENCES":true},"service_role":{"DELETE":true,"INSERT":true,"SELECT":true,"UPDATE":true,"TRIGGER":true,"TRUNCATE":true,"REFERENCES":true},"authenticated":{"DELETE":true,"INSERT":false,"SELECT":true,"UPDATE":false,"TRIGGER":true,"TRUNCATE":true,"REFERENCES":true},"rcap_render_worker":{"DELETE":false,"INSERT":false,"SELECT":false,"UPDATE":false,"TRIGGER":false,"TRUNCATE":false,"REFERENCES":false},"rcap_packet_delivery":{"DELETE":false,"INSERT":false,"SELECT":false,"UPDATE":false,"TRIGGER":false,"TRUNCATE":false,"REFERENCES":false}}},"policies:packet_delivery_events":[],"column:packet_delivery_events.id":{"type":"uuid","default":"gen_random_uuid()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role"