true,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.claim_packet_render_job(p_worker_id text, p_renderer_kinds text[], p_claim_seconds integer DEFAULT 600)\n RETURNS TABLE(id uuid, packet_id uuid, route_id text, renderer_kind text, renderer_version text, source_sha256 text, profile_id text, profile_version text, input_hash text, attempt_count integer, max_attempts integer, partner_id uuid, person_id uuid, matter_id uuid, fencing_token uuid, claim_expires_at timestamp with time zone)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_worker_id text;\n  v_job_id uuid;\n  v_token uuid;\nbegin\n  v_worker_id := nullif(trim(p_worker_id), '''');\n  if v_worker_id is null then\n    raise exception ''a worker id is required to claim a job'';\n  end if;\n  if p_claim_seconds is null or p_claim_seconds < 30 or p_claim_seconds > 3600 then\n    raise exception ''claim seconds must be between 30 and 3600'';\n  end if;\n\n  select j.id into v_job_id\n  from public.packet_render_jobs j\n  where j.status = ''queued''\n    and (j.next_attempt_at is null or j.next_attempt_at <= now())\n    and (p_renderer_kinds is null or j.renderer_kind = any (p_renderer_kinds))\n  order by j.created_at\n  for update skip locked\n  limit 1;\n\n  if v_job_id is null then\n    return;\n  end if;\n\n  v_token := gen_random_uuid();\n  perform set_config(''rcap.packet_mutation_authority'', ''claim_packet_render_job'', true);\n  return query\n  update public.packet_render_jobs j\n  set status = ''claimed'',\n      claimed_by = v_worker_id,\n      claim_expires_at = now() + make_interval(secs => p_claim_seconds),\n      fencing_token = v_token,\n      attempt_count = j.attempt_count + 1\n  where j.id = v_job_id\n  returning j.id, j.packet_id, j.route_id, j.renderer_kind, j.renderer_version,\n            j.source_sha256, j.profile_id, j.profile_version, j.input_hash,\n            j.attempt_count, j.max_attempts, j.partner_id, j.person_id, j.matter_id,\n            j.fencing_token, j.claim_expires_at;\n  perform set_config(''rcap.packet_mutation_authority'', '''', true);\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:start_packet_validation":{"start_packet_validation(uuid,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":true,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.start_packet_validation(p_job_id uuid, p_fencing_token uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_job public.packet_render_jobs%rowtype;\nbegin\n  select * into v_job from public.packet_render_jobs where id = p_job_id for update;\n  if not found then return false; end if;\n  perform public.assert_packet_render_job_fencing(v_job, p_fencing_token);\n  if v_job.status <> ''rendering'' then\n    raise exception ''packet_render_jobs: validation starts only from rendering, job is %'', v_job.status;\n  end if;\n  perform set_config(''rcap.packet_mutation_authority'', ''start_packet_validation'', true);\n  update public.packet_render_jobs set status = ''validating'' where id = p_job_id;\n  perform set_config(''rcap.packet_mutation_authority'', '''', true);\n  return true;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"policies:consumer_briefcase_items":[{"name":"consumer briefcase delete own items","check":null,"roles":["PUBLIC"],"using":"(auth.uid() = user_id)","command":"d","permissive":true},{"name":"consumer briefcase insert own items","check":"(auth.uid() = user_id)","roles":["PUBLIC"],"using":null,"command":"a","permissive":true},{"name":"consumer briefcase select own items","check":null,"roles":["PUBLIC"],"using":"(auth.uid() = user_id)","command":"r","permissive":true},{"name":"consumer briefcase update own items","check":"(auth.uid() = user_id)","roles":["PUBLIC"],"using":"(auth.uid() = user_id)","command":"w","permissive":true}],"column:consumer_briefcase_items.id":{"type":"uuid","default":"gen_random_uuid()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.route_id":{"type":"text","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.matter_id":{"type":"uuid","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.packet_id":{"type":"uuid","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.person_id":{"type":"uuid","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:enqueue_packet_render_job":{"enqueue_packet_render_job(uuid,text,text,text,text,text,text,text,uuid,uuid,uuid,uuid,integer,uuid,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.enqueue_packet_render_job(p_packet_id uuid, p_route_id text, p_renderer_kind text, p_renderer_version text, p_source_sha256 text, p_profile_id text, p_profile_version text, p_input_hash text, p_briefcase_item_id uuid, p_partner_id uuid, p_person_id uuid, p_matter_id uuid, p_max_attempts integer, p_consumer_briefcase_item_id uuid, p_expected_consumer_auth_user_id uuid)\n RETURNS SETOF packet_render_jobs\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_existing public.packet_render_jobs%rowtype;\n  v_canonical_user uuid;\n  v_item_found boolean;\n  v_consumer_item uuid;\nbegin\n  if p_packet_id is null then\n    raise exception ''packet id is required'';\n  end if;\n  if nullif(trim(p_input_hash), '''') is null or p_input_hash !~ ''^[0-9a-f]{64}$'' then\n    raise exception ''input hash must be a sha256 hex digest'';\n  end if;\n\n  -----------------------------------------------------------------------------\n  -- Mode validation. Neither mode may borrow the other''s fields.\n  -----------------------------------------------------------------------------\n  if p_partner_id is not null then\n    if p_consumer_briefcase_item_id is not null or p_expected_consumer_auth_user_id is not null then\n      raise exception ''packet_render_jobs: a sponsored job must not carry consumer binding fields'';\n    end if;\n  else\n    if p_consumer_briefcase_item_id is null then\n      raise exception ''packet_render_jobs: an unsponsored consumer job requires a consumer briefcase item'';\n    end if;\n    if p_expected_consumer_auth_user_id is null then\n      raise exception ''packet_render_jobs: an unsponsored consumer job requires the expected consumer user id'';\n    end if;\n    if p_person_id is null then\n      raise exception ''packet_render_jobs: an unsponsored consumer job requires a person id'';\n    end if;\n    if p_matter_id is null then\n      raise exception ''packet_render_jobs: an unsponsored consumer job requires a matter id'';\n    end if;\n\n    ---------------------------------------------------------------------------\n    -- Ownership. Resolved dynamically for the same reason Phase 51''s probe is:\n    -- consumer_briefcase_items references auth.users and is absent from\n    -- partner-only schemas. Absent, a consumer job cannot be created at all,\n    -- which is the fail-closed answer rather than a crash.\n    ---------------------------------------------------------------------------\n    if to_regclass(''public.consumer_briefcase_items'') is null then\n      raise exception ''packet_render_jobs: consumer payment storage is absent; a consumer job cannot be bound'';\n    end if;\n\n    execute\n      ''select true, b.user_id from public.consumer_briefcase_items b where b.id = $1''\n    into v_item_found, v_canonical_user\n    using p_consumer_briefcase_item_id;\n\n    if not coalesce(v_item_found, false) then\n      raise exception ''packet_render_jobs: consumer briefcase item % does not exist'', p_consumer_briefcase_item_id;\n    end if;\n\n    if v_canonical_user is null then\n      raise exception ''packet_render_jobs: consumer briefcase item % has no owner'', p_consumer_briefcase_item_id;\n    end if;\n\n    -- The comparison is the whole point: a server that derives the user from a\n    -- verified session and a database that independently confirms the item\n    -- belongs to that user must agree, or nothing is created.\n    if v_canonical_user is distinct from p_expected_consumer_auth_user_id then\n      raise exception ''packet_render_jobs: consumer briefcase item % is not owned by the expected user'', p_consumer_briefcase_item_id;\n    end if;\n  end if;\n\n  -----------------------------------------------------------------------------\n  -- Idempotency is unchanged: an identical request returns the live or\n  -- completed job rather than queueing a second one that could deliver twice.\n  -----------------------------------------------------------------------------\n  select * into v_existing\n  from public.packet_render_jobs j\n  where j.packet_id = p_packet_id\n    and j.input_hash = p_input_hash\n    and j.status <> ''failed''\n  order by j.created_at\n  limit 1;\n\n  if found then\n    return next v_existing;\n    return;\n  end if;\n\n  -- Phase 52 falls back to briefcase_item_id when the phase-53 column is\n  -- absent on an older row; keeping both in step means a consumer job created\n  -- here satisfies either read.\n  v_consumer_item := coalesce(p_briefcase_item_id, p_consumer_briefcase_item_id);\n\n  perform set_config(''rcap.packet_mutation_authority'', ''enqueue_packet_render_job'', true);\n  return query\n  insert into public.packet_render_jobs (\n    packet_id, route_id, renderer_kind, renderer_version, source_sha256,\n    profile_id, profile_version, input_hash, briefcase_item_id,\n    partner_id, person_id, matter_id, max_attempts,\n    -- Bound in the same statement that creates the row. There is no window in\n    -- which the job exists unbound, so Phase 52''s immutability trigger has\n    -- nothing to guard against and no null-to-value transition to permit.\n    consumer_briefcase_item_id, consumer_auth_user_id\n  ) values (\n    p_packet_id, trim(p_route_id), p_renderer_kind, p_renderer_version, p_source_sha256,\n    p_profile_id, p_profile_version, p_input_hash, v_consumer_item,\n    p_partner_id, p_person_id, p_matter_id, coalesce(p_max_attempts, 5),\n    p_consumer_briefcase_item_id, v_canonical_user\n  )\n  returning *;\n  perform set_config(''rcap.packet_mutation_authority'', '''', true);\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"policies:partner_packet_entitlement":[],"table:consumer_packet_verifications":{"rls":true,"owner":"postgres","forceRls":false,"publicAcl":[],"privileges":{"anon":{"DELETE":false,"INSERT":false,"SELECT":false,"UPDATE":false,"TRIGGER":false,"TRUNCATE":false,"REFERENCES":false},"service_role":{"DELETE":true,"INSERT":true,"SELECT":true,"UPDATE":true,"TRIGGER":true,"TRUNCATE":true,"REFERENCES":true},"authenticated":{"DELETE":false,"INSERT":false,"SELECT":false,"UPDATE":false,"TRIGGER":false,"TRUNCATE":false,"REFERENCES":false},"rcap_render_worker":{"DELETE":false,"INSERT":false,"SELECT":false,"UPDATE":false,"TRIGGER":false,"TRUNCATE":false,"REFERENCES":false},"rcap_packet_delivery":{"DELETE":false,"INSERT":false,"SELECT":false,"UPDATE":false,"TRIGGER":false,"TRUNCATE":false,"REFERENCES":false}}},"bucket:rcap-packet-artifacts-private":{"public