e,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:assert_packet_render_job_fencing":{"assert_packet_render_job_fencing(packet_render_jobs,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":true,"service_role":true,"authenticated":true,"rcap_render_worker":true,"rcap_packet_delivery":true},"definition":"CREATE OR REPLACE FUNCTION public.assert_packet_render_job_fencing(p_job packet_render_jobs, p_fencing_token uuid)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\nbegin\n  if p_job.fencing_token is null or p_fencing_token is null\n     or p_job.fencing_token <> p_fencing_token then\n    raise exception ''packet_render_jobs: fencing token is not the active claim'';\n  end if;\n  if p_job.claim_expires_at is null or p_job.claim_expires_at < now() then\n    raise exception ''packet_render_jobs: claim lease has expired'';\n  end if;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":true,"securityDefiner":false}},"functions:requeue_packet_render_job_manual":{"requeue_packet_render_job_manual(uuid,text)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.requeue_packet_render_job_manual(p_job_id uuid, p_authorized_by text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_job public.packet_render_jobs%rowtype;\nbegin\n  if nullif(trim(p_authorized_by), '''') is null then\n    raise exception ''a manual requeue requires a named authorizer'';\n  end if;\n  select * into v_job from public.packet_render_jobs where id = p_job_id for update;\n  if not found then return false; end if;\n  if v_job.status <> ''failed'' then\n    raise exception ''packet_render_jobs: only a failed job can be requeued manually'';\n  end if;\n\n  perform set_config(''rcap.packet_mutation_authority'', ''requeue_packet_render_job_manual'', true);\n  update public.packet_render_jobs\n  set status = ''queued'',\n      failure_disposition = null,\n      next_attempt_at = null,\n      manual_requeue_authorized_by = trim(p_authorized_by),\n      max_attempts = greatest(max_attempts, attempt_count + 1)\n  where id = p_job_id;\n  perform set_config(''rcap.packet_mutation_authority'', '''', true);\n  return true;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"policies:consumer_artifact_download_grants":[],"column:consumer_artifact_download_grants.id":{"type":"uuid","default":"gen_random_uuid()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.packet_type":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES