:false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:consumer_packet_payment_authority":{"consumer_packet_payment_authority(uuid,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.consumer_packet_payment_authority(p_briefcase_item_id uuid, p_consumer_auth_user_id uuid)\n RETURNS TABLE(valid boolean, reason text, provider_event_id text)\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_product text;\n  v_person uuid;\n  v_matter uuid;\nbegin\n  if to_regclass(''public.consumer_briefcase_items'') is null then\n    return query select false, ''no_payment_storage''::text, null::text;\n    return;\n  end if;\n  execute\n    ''select b.payment_product_id, b.payment_person_id, b.payment_matter_id\n       from public.consumer_briefcase_items b where b.id = $1''\n  into v_product, v_person, v_matter\n  using p_briefcase_item_id;\n  return query select * from public.consumer_packet_payment_authority(\n    p_briefcase_item_id, p_consumer_auth_user_id, v_product, v_person, v_matter\n  );\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true},"consumer_packet_payment_authority(uuid,uuid,text,uuid,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.consumer_packet_payment_authority(p_briefcase_item_id uuid, p_consumer_auth_user_id uuid, p_product_id text, p_person_id uuid, p_matter_id uuid)\n RETURNS TABLE(valid boolean, reason text, provider_event_id text)\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_status text;\n  v_amount integer;\n  v_regular integer;\n  v_discount integer;\n  v_currency text;\n  v_owner uuid;\n  v_event text;\n  v_authority text;\n  v_session text;\n  v_product text;\n  v_person uuid;\n  v_matter uuid;\nbegin\n  if p_briefcase_item_id is null then return query select false, ''no_briefcase_item''::text, null::text; return; end if;\n  if p_consumer_auth_user_id is null then return query select false, ''no_consumer_binding''::text, null::text; return; end if;\n  if to_regclass(''public.consumer_briefcase_items'') is null then return query select false, ''no_payment_storage''::text, null::text; return; end if;\n\n  execute\n    ''select b.payment_status, b.amount_cents, b.regular_price_cents, b.discount_cents,\n            b.currency, b.user_id, b.provider_event_id, b.payment_authority,\n            b.checkout_session_id, b.payment_product_id, b.payment_person_id, b.payment_matter_id\n       from public.consumer_briefcase_items b where b.id = $1''\n  into v_status, v_amount, v_regular, v_discount, v_currency, v_owner, v_event,\n       v_authority, v_session, v_product, v_person, v_matter\n  using p_briefcase_item_id;\n\n  if v_status is null and v_owner is null then return query select false, ''item_not_found''::text, null::text; return; end if;\n  if v_owner is distinct from p_consumer_auth_user_id then return query select false, ''owner_mismatch''::text, null::text; return; end if;\n  if v_status is distinct from ''paid'' then return query select false, (''payment_status_'' || coalesce(v_status, ''null''))::text, null::text; return; end if;\n  if v_regular is distinct from 5000\n     or v_discount is null or v_discount < 0 or v_discount > v_regular\n     or v_amount is distinct from (v_regular - v_discount) then\n    return query select false, ''amount_not_product_price''::text, null::text; return;\n  end if;\n  if lower(coalesce(v_currency, '''')) <> ''usd'' then return query select false, ''currency_not_usd''::text, null::text; return; end if;\n  if v_authority is null or nullif(trim(coalesce(v_event, '''')), '''') is null then return query select false, ''no_server_payment_evidence''::text, null::text; return; end if;\n  if nullif(trim(coalesce(v_session, '''')), '''') is null then return query select false, ''no_checkout_session''::text, null::text; return; end if;\n  if v_product is distinct from p_product_id or p_product_id is distinct from ''expungement_packet'' then return query select false, ''product_mismatch''::text, null::text; return; end if;\n  if v_person is distinct from p_person_id then return query select false, ''person_mismatch''::text, null::text; return; end if;\n  if v_matter is distinct from p_matter_id or p_matter_id is distinct from public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id) then return query select false, ''matter_mismatch''::text, null::text; return; end if;\n\n  return query select true, ''authorized''::text, v_event;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:replace_consumer_checkout_session":{"replace_consumer_checkout_session(uuid,uuid,text,text,text,text,uuid,uuid,text)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.replace_consumer_checkout_session(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid, p_expected_checkout_session_id text, p_checkout_session_id text, p_payment_provider text, p_product_id text, p_person_id uuid, p_matter_id uuid, p_expected_verification_hash text)\n RETURNS TABLE(ok boolean, reason text, briefcase_item_id uuid, checkout_session_id text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_item public.consumer_briefcase_items%rowtype;\n  v_hash text;\n  v_other uuid;\nbegin\n  -- Both ids are mandatory and must differ. A replacement that names no\n  -- predecessor is an initial binding and belongs to the other function; a\n  -- replacement of an id by itself is a no-op dressed as a swap.\n  if nullif(trim(coalesce(p_expected_checkout_session_id, '''')), '''') is null\n     or nullif(trim(coalesce(p_checkout_session_id, '''')), '''') is null\n     or p_expected_checkout_session_id = p_checkout_session_id then\n    return query select false, ''checkout_replacement_invalid''::text, p_briefcase_item_id, null::text; return;\n  end if;\n\n  select * into v_item from public.consumer_briefcase_items i\n   where i.id = p_briefcase_item_id for update;\n  if not found or v_item.user_id is distinct from p_consumer_auth_user_id then\n    return query select false, ''item_not_found''::text, null::uuid, null::text; return;\n  end if;\n\n  -- Money already collected is never re-bound to a different Session. This is\n  -- the guard the initial binding does not need and this one does: it is the\n  -- only path that can point a paid row at another order.\n  if v_item.payment_status = ''paid'' then\n    return query select false, ''already_paid''::text, p_briefcase_item_id, v_item.checkout_session_id; return;\n  end if;\n\n  select v.verification_hash into v_hash from public.consumer_packet_verifications v\n   where v.briefcase_item_id = p_briefcase_item_id and v.status = ''verified'' for update;\n  if v_hash is distinct from p_expected_verification_hash then\n    return query select false, ''verification_changed''::text, p_briefcase_item_id, null::text; return;\n  end if;\n\n  -- The same eligibility the initial binding demands, re-checked rather than\n  -- inherited: a replacement is a fresh write and is held to the fresh rules.\n  if v_item.payment_allowed is not true or v_item.payment_status = ''not_applicable''\n     or p_product_id is distinct from public.expungement_packet_product_id()\n     or p_matter_id is distinct from public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id)\n     or p_person_id is null or p_payment_provider not in (''stripe'', ''dry_run'') then\n    return query select false, ''checkout_binding_invalid''::text, p_briefcase_item_id, null::text; return;\n  end if;\n\n  -- The new Session must not already belong to another matter.\n  select i.id into v_other from public.consumer_briefcase_items i\n    where i.checkout_session_id = p_checkout_session_id and i.id <> p_briefcase_item_id limit 1;\n  if v_other is not null then\n    return query select false, ''checkout_session_in_use''::text, p_briefcase_item_id, null::text; return;\n  end if;\n\n  -- The compare half of the compare-and-swap. The stored Session must be\n  -- exactly the one the caller expired. Anything else means another request\n  -- replaced it first, and the caller is told which id won so it can expire its\n  -- own and reconcile against that one instead of overwriting it.\n  if v_item.checkout_session_id is distinct from p_expected_checkout_session_id then\n    return query select false, ''checkout_replacement_conflict''::text, p_briefcase_item_id, v_item.checkout_session_id; return;\n  end if;\n\n  update public.consumer_briefcase_items i set\n    checkout_session_id = p_checkout_session_id,\n    payment_provider = p_payment_provider,\n    payment_product_id = p_product_id,\n    payment_person_id = p_person_id,\n    payment_matter_id = p_matter_id,\n    payment_status = ''unpaid'',\n    amount_cents = null,\n    updated_at = now()\n  where i.id = p_briefcase_item_id\n    and i.checkout_session_id = p_expected_checkout_session_id\n    and i.payment_status <> ''paid'';\n  if not found then\n    return query select false, ''checkout_replacement_conflict''::text, p_briefcase_item_id, v_item.checkout_session_id; return;\n  end if;\n\n  return query select true, ''replaced''::text, p_briefcase_item_id, p_checkout_session_id;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:sponsored_packet_render_authority":{"sponsored_packet_render_authority(text,uuid,uuid,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.sponsored_packet_render_authority(p_route_key text, p_session_id uuid, p_briefcase_item_id uuid, p_consumer_auth_user_id uuid)\n RETURNS TABLE(valid boolean, reason text, partner_slug text, partner_id uuid, clinic_event_id uuid, clinic_case_id uuid)\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_route public.sponsored_packet_render_routes%rowtype;\n  v_item public.consumer_briefcase_items%rowtype;\n  v_source public.consumer_pending_screening_results%rowtype;\n  v_session public.screening_sessions%rowtype;\n  v_case public.clinic_cases%rowtype;\n  v_event public.clinic_events%rowtype;\n  v_partner_id uuid;\nbegin\n  if p_route_key is null or p_session_id is null\n     or p_briefcase_item_id is null or p_consumer_auth_user_id is null then\n    return query select false, ''invalid_input''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  select * into v_route from public.sponsored_packet_render_routes r\n   where r.route_key = p_route_key and r.active;\n  if not found then\n    return query select false, ''route_not_registered''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  select * into v_item from public.consumer_briefcase_items i\n   where i.id = p_briefcase_item_id and i.user_id = p_consumer_auth_user_id;\n  if not found then\n    return query select false, ''wrong_owner''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_item.jurisdiction is distinct from v_route.jurisdiction then\n    return query select false, ''wrong_jurisdiction_or_route''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  select * into v_source from public.consumer_pending_screening_results p\n   where p.pending_id = v_item.source_pending_result_id;\n  if not found or v_source.status <> ''CLAIMED''\n     or v_source.claimed_matter_id is distinct from v_item.id\n     or v_source.claimed_user_id is distinct from v_item.user_id then\n    return query select false, ''wrong_item''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_source.anonymous_session_id is distinct from p_session_id then\n    return query select false, ''wrong_session''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_source.product <> ''rcap_partner''\n     or v_source.partner_slug is distinct from v_route.partner_slug then\n    return query select false, ''wrong_partner''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_source.jurisdiction is distinct from v_route.jurisdiction then\n    return query select false, ''wrong_jurisdiction_or_route''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  select * into v_session from public.screening_sessions s where s.session_id = p_session_id;\n  if not found or v_session.flow_mode <> ''rcap'' or v_session.partner_benefit_active is not true then\n    return query select false, ''sponsorship_inactive''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_session.partner_slug is distinct from v_route.partner_slug then\n    return query select false, ''wrong_partner''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_session.jurisdiction is distinct from v_route.jurisdiction then\n    return query select false, ''wrong_jurisdiction_or_route''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  select c.* into v_case from public.clinic_cases c\n   where c.event_id = v_source.event_id\n     and c.participant_user_id = v_item.user_id\n     and c.screening_session_id = p_session_id\n     and c.matter_id = v_item.id;\n  if not found then\n    return query select false, ''clinic_scope_mismatch''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_case.jurisdiction is distinct from v_route.jurisdiction or v_case.route_disposition <> ''packet'' then\n    return query select false, ''wrong_jurisdiction_or_route''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  select * into v_event from public.clinic_events e where e.id = v_case.event_id;\n  if not found\n     or v_event.partner_slug is distinct from v_route.partner_slug\n     or v_event.program_key is distinct from v_route.program_key\n     or (v_route.clinic_event_name is not null and v_event.name is distinct from v_route.clinic_event_name) then\n    return query select false, ''clinic_scope_mismatch''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_event.jurisdiction is distinct from v_route.jurisdiction then\n    return query select false, ''wrong_jurisdiction_or_route''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_event.status <> ''published''\n     or v_event.sponsorship_allocation is null or v_event.sponsorship_allocation <= 0 then\n    return query select false, ''sponsorship_inactive''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  select pr.id into v_partner_id from public.partner_records pr\n   where pr.partner_slug = v_route.partner_slug;\n  if v_partner_id is null then\n    return query select false, ''no_entitlement''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  return query select true, null::text, v_route.partner_slug, v_partner_id, v_event.id, v_case.id;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"column:consumer_briefcase_items.amount_cents":{"type":"integer","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.jurisdiction":{"type":"text","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.summary_json":{"type":"jsonb","default":"''{}''::jsonb","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,