ticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:partner_packet_entitlement.updated_at":{"type":"timestamp with time zone","default":"now()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:sponsored_packet_render_routes.active":{"type":"boolean","default":"true","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:guard_packet_render_job_transition":{"guard_packet_render_job_transition()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":true,"service_role":true,"authenticated":true,"rcap_render_worker":true,"rcap_packet_delivery":true},"definition":"CREATE OR REPLACE FUNCTION public.guard_packet_render_job_transition()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_authority text := public.rcap_packet_mutation_authority();\nbegin\n  if new.status <> old.status then\n    if not (\n      (old.status = ''queued'' and new.status in (''claimed'', ''failed''))\n      or (old.status = ''claimed'' and new.status in (''rendering'', ''failed'', ''queued''))\n      or (old.status = ''rendering'' and new.status in (''validating'', ''failed''))\n      or (old.status = ''validating'' and new.status in (''artifact_validated'', ''failed''))\n      or (old.status = ''artifact_validated'' and new.status = ''delivered'')\n      or (old.status = ''failed'' and new.status = ''queued'')\n    ) then\n      raise exception ''packet_render_jobs: illegal transition % -> %'', old.status, new.status;\n    end if;\n\n    if old.status = ''queued'' and new.status = ''claimed''\n       and v_authority <> ''claim_packet_render_job'' then\n      raise exception ''packet_render_jobs: claiming requires claim_packet_render_job'';\n    end if;\n\n    if new.status = ''artifact_validated''\n       and v_authority <> ''finalize_packet_render_job'' then\n      raise exception ''packet_render_jobs: artifact_validated is written only by finalize_packet_render_job'';\n    end if;\n\n    if new.status = ''delivered''\n       and v_authority <> ''record_packet_delivery_event'' then\n      raise exception ''packet_render_jobs: delivered is written only by record_packet_delivery_event'';\n    end if;\n\n    if old.status = ''failed'' and new.status = ''queued'' then\n      if v_authority not in (''requeue_retryable_packet_render_jobs'', ''requeue_packet_render_job_manual'') then\n        raise exception ''packet_render_jobs: failed jobs return to queued only through a requeue function'';\n      end if;\n      if old.failure_disposition = ''terminal''\n         and v_authority <> ''requeue_packet_render_job_manual'' then\n        raise exception ''packet_render_jobs: a terminal failure is requeued only manually with recorded authorization'';\n      end if;\n    end if;\n\n    if new.status in (''rendering'', ''validating'')\n       and v_authority not in (''start_packet_render'', ''start_packet_validation'') then\n      raise exception ''packet_render_jobs: worker transitions require their canonical functions'';\n    end if;\n\n    if new.status = ''failed''\n       and v_authority not in (\n         ''fail_packet_render_job'',\n         ''release_expired_packet_render_claims'',\n         ''finalize_packet_render_job'',\n         ''cancel_participant_render_jobs''\n       ) then\n      raise exception ''packet_render_jobs: failure is recorded only through its canonical functions'';\n    end if;\n\n    -- Only an unstarted job may be cancelled this way. Anything a worker has\n    -- already touched still belongs to the worker''s own failure path.\n    if v_authority = ''cancel_participant_render_jobs'' and old.status <> ''queued'' then\n      raise exception ''packet_render_jobs: participant cancellation applies only to a queued job'';\n    end if;\n\n    -- Per-state timestamps, carried over from the phase-49 guard.\n    new.claimed_at            := case when new.status = ''claimed''            then now() else new.claimed_at end;\n    new.rendering_at          := case when new.status = ''rendering''          then now() else new.rendering_at end;\n    new.validating_at         := case when new.status = ''validating''         then now() else new.validating_at end;\n    new.artifact_validated_at := case when new.status = ''artifact_validated'' then now() else new.artifact_validated_at end;\n    new.delivered_at          := case when new.status = ''delivered''          then now() else new.delivered_at end;\n\n    if new.status = ''queued'' then\n      new.claimed_by := null;\n      new.claimed_at := null;\n    end if;\n  end if;\n\n  if (new.delivery_eligibility is distinct from old.delivery_eligibility\n      or new.accounting_result is distinct from old.accounting_result\n      or new.credit_ledger_id is distinct from old.credit_ledger_id)\n     and v_authority <> ''finalize_packet_render_job'' then\n    raise exception ''packet_render_jobs: accounting fields are written only by finalize_packet_render_job'';\n  end if;\n\n  if (new.output_storage_path is distinct from old.output_storage_path\n      or new.output_sha256 is distinct from old.output_sha256\n      or new.normalized_output_sha256 is distinct from old.normalized_output_sha256\n      or new.container_digest is distinct from old.container_digest)\n     and v_authority <> ''finalize_packet_render_job'' then\n    raise exception ''packet_render_jobs: artifact evidence is written only by finalize_packet_render_job'';\n  end if;\n\n  if old.partner_id is not null and new.partner_id is distinct from old.partner_id then\n    raise exception ''packet_render_jobs: partner_id is immutable'';\n  end if;\n  if old.person_id is not null and new.person_id is distinct from old.person_id then\n    raise exception ''packet_render_jobs: person_id is immutable'';\n  end if;\n  if old.matter_id is not null and new.matter_id is distinct from old.matter_id then\n    raise exception ''packet_render_jobs: matter_id is immutable'';\n  end if;\n\n  new.updated_at := now();\n  return new;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":true,"securityDefiner":false}},"functions:rcap_participant_erasure_authority":{"rcap_participant_erasure_authority()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.rcap_participant_erasure_authority()\n RETURNS text\n LANGUAGE sql\n STABLE\n SET search_path TO ''''\nAS $function$\n  select coalesce(current_setting(''rcap.participant_erasure_authority'', true), '''');\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":false}},"policies:consumer_packet_artifact_provenance":[],"policies:consumer_packet_payment_consumption":[],"column:consumer_briefcase_items.packet_status":{"type":"text","default":"''not_started''::text","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.pathway_label":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_payment_consumption.id":{"type":"uuid","default":"gen_random_uuid()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_verifications.revision":{"type":"integer","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_delivery_events.request_context":{"type":"jsonb","default":"''{}''::jsonb","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.failure_disposition":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.output_storage_path":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.sponsored_route_key":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:partner_packet_entitlement.overage_cap":{"type":"integer","default":"0","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:bind_consumer_checkout_verification":{"bind_consumer_checkout_verification(uuid,uuid,text,text,text,uuid,uuid,text)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.bind_consumer_checkout_verification(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid, p_checkout_session_id text, p_payment_provider text, p_product_id text, p_person_id uuid, p_matter_id uuid, p_expected_verification_hash text)\n RETURNS TABLE(ok boolean, reason text, briefcase_item_id uuid, checkout_session_id text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_item public.consumer_briefcase_items%rowtype;\n  v_hash text;\n  v_other uuid;\nbegin\n  select * into v_item from public.consumer_briefcase_items i\n   where i.id = p_briefcase_item_id for update;\n  if not found or v_item.user_id is distinct from p_consumer_auth_user_id then\n    return query select false, ''item_not_found''::text, null::uuid, null::text; return;\n  end if;\n  select v.verification_hash into v_hash from public.consumer_packet_verifications v\n   where v.briefcase_item_id = p_briefcase_item_id and v.status = ''verified'' for update;\n  if v_hash is distinct from p_expected_verification_hash then\n    return query select false, ''verification_changed''::text, p_briefcase_item_id, null::text; return;\n  end if;\n  if v_item.payment_allowed is not true or v_item.payment_status = ''not_applicable''\n     or p_product_id is distinct from public.expungement_packet_product_id()\n     or p_matter_id is distinct from public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id)\n     or p_person_id is null or p_payment_provider not in (''stripe'', ''dry_run'')\n     or nullif(trim(coalesce(p_checkout_session_id, '''')), '''') is null then\n    return query select false, ''checkout_binding_invalid''::text, p_briefcase_item_id, null::text; return;\n  end if;\n  select i.id into v_other from public.consumer_briefcase_items i\n    where i.checkout_session_id = p_checkout_session_id and i.id <> p_briefcase_item_id limit 1;\n  if v_other is not null then\n    return query select false, ''checkout_session_in_use''::text, p_briefcase_item_id, null::text; return;\n  end if;\n  if v_item.checkout_session_id is not null and v_item.checkout_session_id <> p_checkout_session_id then\n    return query select false, ''checkout_binding_conflict''::text, p_briefcase_item_id, v_item.checkout_session_id; return;\n  end if;\n  update public.consumer_briefcase_items i set\n    checkout_session_id = p_checkout_session_id,\n    payment_provider = p_payment_provider,\n    payment_product_id = p_product_id,\n    payment_person_id = p_person_id,\n    payment_matter_id = p_matter_id,\n    payment_status = case when i.payment_status = ''paid'' then ''paid'' else ''unpaid'' end,\n    amount_cents = case when i.payment_status = ''paid'' then i.amount_cents else null end,\n    updated_at = now()\n  where i.id = p_briefcase_item_id;\n  return query select true, ''bound''::text, p_briefcase_item_id, p_checkout_session_id;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:packet_render_jobs_guard_transition":{},"column:consumer_briefcase_items.discount_cents":{"type":"integer","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.payment_status":{"type":"text","default":"''not_applicable''::text","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_verifications.matter_id":{"type":"uuid","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.delivery_eligibility":{"type":"text","default":"''not_evaluated''::text","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.sponsored_session_id":{"type":"uuid","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:partner_packet_entitlement.effective_at":{"type":"timestamp with time zone","default":"now()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:partner_packet_entitlement.pause_at_cap":{"type":"boolean","default":"true","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:authorize_consumer_artifact_download":{"authorize_consumer_artifact_download(uuid,uuid,text)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.authorize_consumer_artifact_download(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid, p_token_hash text)\n RETURNS TABLE(grant_id uuid, artifact_storage_path text, artifact_sha256 text, file_name text, content_type text, render_job_id uuid)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_grant public.consumer_artifact_download_grants%rowtype;\n  v_job uuid;\nbegin\n  select g.* into v_grant from public.consumer_artifact_download_grants g\n  join public.consumer_briefcase_items i\n    on i.id = g.briefcase_item_id and i.user_id = p_consumer_auth_user_id\n  join public.consumer_packet_artifact_provenance p\n    on p.briefcase_item_id = g.briefcase_item_id\n   and p.consumer_auth_user_id = g.consumer_auth_user_id\n   and p.matter_id = g.matter_id\n   and p.revision = g.artifact_revision\n   and p.verification_hash = g.verification_hash\n  join public.consumer_packet_verifications v\n    on v.briefcase_item_id = g.briefcase_item_id\n   and v.consumer_auth_user_id = g.consumer_auth_user_id\n   and v.status = ''verified''\n   and v.verification_hash = g.verification_hash\n  where g.token_hash = p_token_hash\n    and g.consumer_auth_user_id = p_consumer_auth_user_id\n    and g.briefcase_item_id = p_briefcase_item_id\n    and g.revoked_at is null\n    and g.expires_at > now()\n  for update of g;\n  if not found then return; end if;\n\n  -- Deterministic, grant-consistent provenance lookup. briefcase_item_id is\n  -- the primary key today, so at most one row can match — but future\n  -- per-revision provenance rows must not turn this into an arbitrary pick,\n  -- so the lookup is pinned to the grant''s owner, matter, revision and\n  -- verification hash, and ordered with an explicit LIMIT.\n  select p.render_job_id into v_job\n  from public.consumer_packet_artifact_provenance p\n  where p.briefcase_item_id = v_grant.briefcase_item_id\n    and p.consumer_auth_user_id = v_grant.consumer_auth_user_id\n    and p.matter_id = v_grant.matter_id\n    and p.revision = v_grant.artifact_revision\n    and p.verification_hash = v_grant.verification_hash\n  order by p.revision desc, p.render_job_id desc\n  limit 1;\n  update public.consumer_artifact_download_grants g set\n    download_count = g.download_count + 1,\n    last_downloaded_at = now()\n  where g.id = v_grant.id;\n  return query select v_grant.id, v_grant.artifact_storage_path,\n    v_grant.artifact_sha256, v_grant.file_name, v_grant.content_type, v_job;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:packet_render_jobs_paid_matter_guard":{"packet_render_jobs_paid_matter_guard()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":true,"service_role":true,"authenticated":true,"rcap_render_worker":true,"rcap_packet_delivery":true},"definition":"CREATE OR REPLACE FUNCTION public.packet_render_jobs_paid_matter_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_valid boolean;\n  v_reason text;\nbegin\n  if new.partner_id is not null then return new; end if;\n  select a.valid, a.reason into v_valid, v_reason\n    from public.consumer_packet_payment_authority(\n      new.consumer_briefcase_item_id,\n      new.consumer_auth_user_id,\n      public.expungement_packet_product_id(),\n      new.person_id,\n      new.matter_id\n    ) a;\n  if not coalesce(v_valid, false) then\n    raise exception ''packet_render_jobs: consumer payment binding refused (%)'', coalesce(v_reason, ''unknown'');\n  end if;\n  return new;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":true,"securityDefiner":true}},"functions:persist_consumer_packet_verification":{"persist_consumer_packet_verification(uuid,uuid,text,integer,jsonb,jsonb,text,jsonb,text,text,text,jsonb,timestamp with time zone)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.persist_consumer_packet_verification(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid, p_expected_prior_hash text, p_expected_prior_revision integer, p_answer_delta jsonb, p_packet_information_metadata jsonb, p_next_draft_hash text, p_next_draft_snapshot jsonb, p_next_verification_status text, p_next_verification_reason text, p_next_verification_hash text, p_next_verification_snapshot jsonb, p_next_verification_invalidated_at timestamp with time zone)\n RETURNS TABLE(status text, reason text, hash text, snapshot jsonb, draft_hash text, draft_snapshot jsonb, revision integer, invalidated_at text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_item public.consumer_briefcase_items%rowtype;\n  v_prior public.consumer_packet_verifications%rowtype;\n  v_next_revision integer;\n  v_verification_display jsonb;\nbegin\n  if p_consumer_auth_user_id is null or p_briefcase_item_id is null\n     or p_expected_prior_revision is null or p_expected_prior_revision < 0\n     or p_next_draft_hash !~ ''^[a-f0-9]{64}$''\n     or p_next_draft_snapshot ->> ''schemaVersion'' <> ''expungement-ai/protected-packet-draft/v1''\n     or p_next_verification_status not in (''unverified'', ''verified'', ''invalidated'')\n     or nullif(trim(coalesce(p_next_verification_reason, '''')), '''') is null\n     or coalesce(jsonb_typeof(p_answer_delta), '''') <> ''object''\n     or coalesce(jsonb_typeof(p_packet_information_metadata), '''') <> ''object'' then\n    return;\n  end if;\n  if (p_next_verification_status = ''verified'') is distinct from\n     coalesce((p_next_verification_hash ~ ''^[a-f0-9]{64}$''\n      and p_next_verification_snapshot ->> ''schemaVersion'' = ''expungement-ai/final-verification/v1''), false) then\n    return;\n  end if;\n  if p_next_verification_status <> ''verified''\n     and (p_next_verification_hash is not null or p_next_verification_snapshot is not null) then\n    return;\n  end if;\n\n  select * into v_item from public.consumer_briefcase_items i\n   where i.id = p_briefcase_item_id and i.user_id = p_consumer_auth_user_id for update;\n  if not found then return; end if;\n\n  select * into v_prior from public.consumer_packet_verifications v\n   where v.briefcase_item_id = p_briefcase_item_id for update;\n\n  if found then\n    if v_prior.consumer_auth_user_id is distinct from p_consumer_auth_user_id\n       or v_prior.revision is distinct from p_expected_prior_revision\n       or (case when v_prior.status = ''verified'' then v_prior.verification_hash else null end)\n          is distinct from p_expected_prior_hash then\n      return;\n    end if;\n    if p_next_draft_hash = v_prior.draft_hash\n       and p_next_verification_status = v_prior.status\n       and p_next_verification_hash is not distinct from v_prior.verification_hash\n       and p_next_draft_snapshot = v_prior.draft_snapshot\n       and p_next_verification_snapshot is not distinct from v_prior.verification_snapshot then\n      v_next_revision := v_prior.revision;\n    else\n      v_next_revision := v_prior.revision + 1;\n    end if;\n    update public.consumer_packet_verifications v set\n      status = p_next_verification_status,\n      reason = p_next_verification_reason,\n      verification_hash = p_next_verification_hash,\n      verification_snapshot = p_next_verification_snapshot,\n      draft_hash = p_next_draft_hash,\n      draft_snapshot = p_next_draft_snapshot,\n      revision = v_next_revision,\n      invalidated_at = p_next_verification_invalidated_at,\n      updated_at = now()\n    where v.briefcase_item_id = p_briefcase_item_id;\n  else\n    if p_expected_prior_revision <> 0 or p_expected_prior_hash is not null then return; end if;\n    v_next_revision := case when p_next_verification_status = ''unverified'' then 0 else 1 end;\n    insert into public.consumer_packet_verifications (\n      briefcase_item_id, consumer_auth_user_id, matter_id, status, reason,\n      verification_hash, verification_snapshot, draft_hash, draft_snapshot,\n      revision, invalidated_at\n    ) values (\n      p_briefcase_item_id, p_consumer_auth_user_id,\n      public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id),\n      p_next_verification_status, p_next_verification_reason,\n      p_next_verification_hash, p_next_verification_snapshot,\n      p_next_draft_hash, p_next_draft_snapshot, v_next_revision,\n      p_next_verification_invalidated_at\n    );\n  end if;\n\n  v_verification_display := jsonb_strip_nulls(jsonb_build_object(\n    ''status'', p_next_verification_status,\n    ''reason'', p_next_verification_reason,\n    ''hash'', p_next_verification_hash,\n    ''snapshot'', p_next_verification_snapshot,\n    ''draftHash'', p_next_draft_hash,\n    ''draftSnapshot'', p_next_draft_snapshot,\n    ''revision'', v_next_revision,\n    ''invalidatedAt'', p_next_verification_invalidated_at\n  ));\n  update public.consumer_briefcase_items i set\n    summary_json = jsonb_set(\n      coalesce(i.summary_json, ''{}''::jsonb),\n      ''{commercialFlow}'',\n      coalesce(i.summary_json -> ''commercialFlow'', ''{}''::jsonb)\n        || jsonb_build_object(\n          ''packetInformation'', p_packet_information_metadata,\n          ''verification'', v_verification_display\n        ),\n      true\n    ),\n    packet_status = case\n      when p_next_verification_status <> ''verified'' and i.packet_status in (''ready'', ''downloaded'') then ''pending''\n      else i.packet_status\n    end,\n    updated_at = now()\n  where i.id = p_briefcase_item_id;\n\n  return query select v.status, v.reason, v.verification_hash, v.verification_snapshot,\n      v.draft_hash, v.draft_snapshot, v.revision,\n      case when v.invalidated_at is null then null else v.invalidated_at::text end\n    from public.consumer_packet_verifications v\n    where v.briefcase_item_id = p_briefcase_item_id;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:release_expired_packet_render_claims":{"release_expired_packet_render_claims()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":true,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.release_expired_packet_render_claims()\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_released integer := 0;\n  v_count integer;\nbegin\n  perform set_config(''rcap.packet_mutation_authority'', ''release_expired_packet_render_claims'', true);\n\n  -- A job stuck in claimed goes straight back to the queue.\n  update public.packet_render_jobs j\n  set status = ''queued'',\n      claim_expires_at = null,\n      fencing_token = null\n  where j.status = ''claimed''\n    and j.claim_expires_at is not null\n    and j.claim_expires_at < now();\n  get diagnostics v_count = row_count;\n  v_released := v_released + v_count;\n\n  -- A job that died mid-render or mid-validation fails retryably (or\n  -- terminally once attempts are exhausted) so its history stays visible.\n  update public.packet_render_jobs j\n  set status = ''failed'',\n      failure_disposition = case when j.attempt_count < j.max_attempts then ''retryable'' else ''terminal'' end,\n      error_code = ''timeout'',\n      last_error_detail = ''claim lease expired before the worker finished'',\n      next_attempt_at = case\n        when j.attempt_count < j.max_attempts\n        then now() + make_interval(secs => least(3600, 30 * power(2, j.attempt_count))::integer)\n        else null\n      end,\n      claim_expires_at = null,\n      fencing_token = null\n  where j.status in (''rendering'', ''validating'')\n    and j.claim_expires_at is not null\n    and j.claim_expires_at < now();\n  get diagnostics v_count = row_count;\n  v_released := v_released + v_count;\n\n  perform set_config(''rcap.packet_mutation_authority'', '''', true);\n  return v_released;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:requeue_retryable_packet_render_jobs":{"requeue_retryable_packet_render_jobs()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":true,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.requeue_retryable_packet_render_jobs()\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_count integer;\nbegin\n  perform set_config(''rcap.packet_mutation_authority'', ''requeue_retryable_packet_render_jobs'', true);\n  update public.packet_render_jobs j\n  set status = ''queued'',\n      failure_disposition = null\n  where j.status = ''failed''\n    and j.failure_disposition = ''retryable''\n    and j.attempt_count < j.max_attempts\n    and (j.next_attempt_at is null or j.next_attempt_at <= now());\n  get diagnostics v_count = row_count;\n  perform set_config(''rcap.packet_mutation_authority'', '''', true);\n  return v_count;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"column:consumer_briefcase_items.next_steps_json":{"type":"jsonb","default":"''[]''::jsonb","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.payment_allowed":{"type":"boolean","default":"false","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_verifications.created_at":{"type":"timestamp with time zone","default":"now()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT"