ull then return null; end if;\n  v_hash := encode(\n    extensions.digest(convert_to(''rcap:consumer-matter:v1:'' || p_item_id::text, ''utf8''), ''sha256''),\n    ''hex''\n  );\n  v_variant := to_hex(((get_byte(decode(substr(v_hash, 17, 2), ''hex''), 0) >> 4) & 3) + 8);\n  return (\n    substr(v_hash, 1, 8) || ''-'' || substr(v_hash, 9, 4) || ''-4'' ||\n    substr(v_hash, 14, 3) || ''-'' || v_variant || substr(v_hash, 18, 3) || ''-'' ||\n    substr(v_hash, 21, 12)\n  )::uuid;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":true,"securityDefiner":false}},"functions:guard_packet_render_job_retry_history":{},"column:consumer_briefcase_items.payment_provider":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:sponsored_packet_render_routes.created_at":{"type":"timestamp with time zone","default":"now()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:sponsored_packet_render_routes.pathway_id":{"type":"text","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:sponsored_packet_render_routes.updated_at":{"type":"timestamp with time zone","default":"now()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:consumer_render_job_verification_guard":{"consumer_render_job_verification_guard()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.consumer_render_job_verification_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare v_hash text;\nbegin\n  if tg_op = ''UPDATE'' and (\n       (old.sponsored_route_key is not null and new.sponsored_route_key is distinct from old.sponsored_route_key)\n    or (old.sponsored_session_id is not null and new.sponsored_session_id is distinct from old.sponsored_session_id)\n    or (old.sponsored_clinic_event_id is not null and new.sponsored_clinic_event_id is distinct from old.sponsored_clinic_event_id)\n    or (old.sponsored_consumer_briefcase_item_id is not null\n        and new.sponsored_consumer_briefcase_item_id is distinct from old.sponsored_consumer_briefcase_item_id)\n    or (old.sponsored_consumer_auth_user_id is not null\n        and new.sponsored_consumer_auth_user_id is distinct from old.sponsored_consumer_auth_user_id)\n    or (old.sponsored_verification_hash is not null\n        and new.sponsored_verification_hash is distinct from old.sponsored_verification_hash)\n  ) then\n    raise exception ''sponsored render binding is immutable'';\n  end if;\n\n  if new.sponsored_route_key is not null then\n    if new.partner_id is null\n       or new.sponsored_session_id is null\n       or new.sponsored_clinic_event_id is null\n       or new.sponsored_consumer_briefcase_item_id is null\n       or new.sponsored_consumer_auth_user_id is null\n       or new.sponsored_verification_hash is null then\n      raise exception ''sponsored render job binding is incomplete'';\n    end if;\n    if not exists (\n      select 1 from public.sponsored_packet_render_routes r\n      where r.route_key = new.sponsored_route_key and r.active\n    ) then\n      raise exception ''sponsored render route is not registered'';\n    end if;\n    if new.status in (''artifact_validated'', ''delivered'') then\n      select v.verification_hash into v_hash from public.consumer_packet_verifications v\n        where v.briefcase_item_id = new.sponsored_consumer_briefcase_item_id\n          and v.consumer_auth_user_id = new.sponsored_consumer_auth_user_id\n          and v.status = ''verified'';\n      if v_hash is null or v_hash is distinct from new.sponsored_verification_hash then\n        raise exception ''sponsored render job has stale verification authority'';\n      end if;\n    end if;\n    return new;\n  end if;\n\n  if new.partner_id is not null then return new; end if;\n  if tg_op = ''UPDATE'' and old.consumer_verification_hash is not null\n     and new.consumer_verification_hash is distinct from old.consumer_verification_hash then\n    raise exception ''consumer render verification binding is immutable'';\n  end if;\n  if new.status in (''artifact_validated'', ''delivered'') then\n    select v.verification_hash into v_hash from public.consumer_packet_verifications v\n      where v.briefcase_item_id = new.consumer_briefcase_item_id\n        and v.consumer_auth_user_id = new.consumer_auth_user_id\n        and v.status = ''verified'';\n    if v_hash is null or v_hash is distinct from new.consumer_verification_hash then\n      raise exception ''consumer render job has stale verification authority'';\n    end if;\n  end if;\n  return new;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:get_consumer_packet_artifact_authority":{"get_consumer_packet_artifact_authority(uuid,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.get_consumer_packet_artifact_authority(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid)\n RETURNS TABLE(status text, revision integer, verification_hash text, entitlement_source text, artifact jsonb, consumer_auth_user_id uuid, briefcase_item_id uuid, matter_id uuid, legacy_evidence jsonb)\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\n  select case when p.briefcase_item_id is null then ''absent'' else ''ready'' end,\n    coalesce(p.revision, 1), p.verification_hash, p.entitlement_source,\n    p.artifact, p.consumer_auth_user_id, p.briefcase_item_id, p.matter_id,\n    p.legacy_evidence\n  from (select 1) one\n  left join public.consumer_packet_artifact_provenance p\n    on p.briefcase_item_id = p_briefcase_item_id\n   and p.consumer_auth_user_id = p_consumer_auth_user_id\n   and exists (select 1 from public.consumer_briefcase_items i\n     where i.id = p.briefcase_item_id and i.user_id = p_consumer_auth_user_id)\n   and (\n     (p.entitlement_source = ''legacy_backfill''\n       and not exists (select 1 from public.consumer_packet_verifications v where v.briefcase_item_id = p.briefcase_item_id))\n     or exists (select 1 from public.consumer_packet_verifications v\n       where v.briefcase_item_id = p.briefcase_item_id\n         and v.consumer_auth_user_id = p_consumer_auth_user_id\n         and v.status = ''verified''\n         and v.verification_hash = p.verification_hash)\n   )\n   and (p.render_job_id is null or exists (select 1 from public.packet_render_jobs j\n     where j.id = p.render_job_id\n       and (\n         (j.consumer_briefcase_item_id = p.briefcase_item_id\n           and j.consumer_auth_user_id = p.consumer_auth_user_id)\n         or (j.sponsored_route_key is not null\n           and j.sponsored_consumer_briefcase_item_id = p.briefcase_item_id\n           and j.sponsored_consumer_auth_user_id = p.consumer_auth_user_id)\n       )));\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:issue_consumer_artifact_download_grant":{"issue_consumer_artifact_download_grant(uuid,uuid,text,timestamp with time zone)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.issue_consumer_artifact_download_grant(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid, p_token_hash text, p_expires_at timestamp with time zone)\n RETURNS TABLE(grant_id uuid, expires_at text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_artifact public.consumer_packet_artifact_provenance%rowtype;\n  v_job public.packet_render_jobs%rowtype;\n  v_path text;\n  v_sha text;\n  v_name text;\n  v_type text;\n  v_grant uuid;\nbegin\n  if p_token_hash !~ ''^[a-f0-9]{64}$''\n     or p_expires_at <= now()\n     or p_expires_at > now() + interval ''15 minutes'' then return; end if;\n\n  select p.* into v_artifact\n  from public.consumer_packet_artifact_provenance p\n  join public.consumer_briefcase_items i\n    on i.id = p.briefcase_item_id and i.user_id = p_consumer_auth_user_id\n  join public.consumer_packet_verifications v\n    on v.briefcase_item_id = p.briefcase_item_id\n   and v.consumer_auth_user_id = p_consumer_auth_user_id\n   and v.status = ''verified''\n   and v.verification_hash = p.verification_hash\n  where p.briefcase_item_id = p_briefcase_item_id\n    and p.consumer_auth_user_id = p_consumer_auth_user_id\n  for update of p;\n  if not found then return; end if;\n\n  select j.* into v_job from public.packet_render_jobs j\n  where j.id = v_artifact.render_job_id\n    and j.consumer_briefcase_item_id = p_briefcase_item_id\n    and j.consumer_auth_user_id = p_consumer_auth_user_id\n    and j.matter_id = v_artifact.matter_id\n    and j.consumer_verification_hash = v_artifact.verification_hash\n    and j.status in (''artifact_validated'', ''delivered'')\n    and j.delivery_eligibility = ''eligible''\n    and j.accounting_result in (''zero_charge'', ''consumed'', ''already_consumed'', ''overage_consumed'');\n  if not found then return; end if;\n\n  v_path := nullif(v_job.output_storage_path, '''');\n  v_sha := v_job.output_sha256;\n  v_name := coalesce(nullif(v_artifact.artifact ->> ''fileName'', ''''), ''record-clearing-packet.pdf'');\n  v_type := coalesce(nullif(v_artifact.artifact ->> ''contentType'', ''''), ''application/pdf'');\n  if v_path is null or v_sha !~ ''^[a-f0-9]{64}$'' then return; end if;\n  if v_path <> v_artifact.artifact ->> ''storagePath''\n     or v_sha <> v_artifact.artifact ->> ''artifactSha256''\n     or v_path like ''/%''\n     or v_path like ''%..%''\n     or v_path <> (''packet-artifacts/consumer/'' || v_artifact.matter_id::text || ''/'' || v_job.id::text || ''/'' || v_sha || ''.pdf'')\n  then return; end if;\n\n  insert into public.consumer_artifact_download_grants(\n    token_hash, consumer_auth_user_id, briefcase_item_id, matter_id,\n    artifact_revision, verification_hash, artifact_storage_path,\n    artifact_sha256, file_name, content_type, expires_at\n  ) values (\n    p_token_hash, p_consumer_auth_user_id, p_briefcase_item_id,\n    v_artifact.matter_id, v_artifact.revision, v_artifact.verification_hash,\n    v_path, v_sha, v_name, v_type, p_expires_at\n  ) returning id into v_grant;\n  return query select v_grant, p_expires_at::text;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"index:packet_render_jobs.packet_render_jobs_pkey":{"ready":true,"valid":true,"definition":"CREATE UNIQUE INDEX packet_render_jobs_pkey ON public.packet_render_jobs USING btree (id)"},"column:consumer_briefcase_items.payment_authority":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.payment_intent_id":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.payment_matter_id":{"type":"uuid","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.payment_person_id":{"type":"uuid","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.provider_event_id":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.source_session_id":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_credit_ledger.consumption_unit_hash":{"type":"text","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:partner_packet_entitlement.overage_enabled":{"type":"boolean","default":"false","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:sponsored_packet_render_routes.program_key":{"type":"text","default":"''record-clearing''::text","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:enqueue_verified_consumer_packet_render":{"enqueue_verified_consumer_packet_render(uuid,text,text,text,text,text,text,text,uuid,uuid,uuid,integer,uuid,uuid,text,jsonb,jsonb)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.enqueue_verified_consumer_packet_render(p_packet_id uuid, p_route_id text, p_renderer_kind text, p_renderer_version text, p_source_sha256 text, p_profile_id text, p_profile_version text, p_input_hash text, p_briefcase_item_id uuid, p_person_id uuid, p_matter_id uuid, p_max_attempts integer, p_consumer_briefcase_item_id uuid, p_expected_consumer_auth_user_id uuid, p_expected_verification_hash text, p_render_packet jsonb, p_render_input_payload jsonb)\n RETURNS SETOF packet_render_jobs\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_hash text;\n  v_authorized boolean;\n  v_job public.packet_render_jobs%rowtype;\n  v_existing_payload jsonb;\nbegin\n  if p_briefcase_item_id is distinct from p_consumer_briefcase_item_id\n     or p_render_packet ->> ''id'' is distinct from p_packet_id::text\n     or p_render_packet ->> ''user_id'' is distinct from p_expected_consumer_auth_user_id::text\n     or p_render_packet ->> ''briefcase_id'' is distinct from p_consumer_briefcase_item_id::text\n     or p_render_packet ->> ''person_id'' is distinct from p_person_id::text\n     or p_render_input_payload ->> ''authUserId'' is distinct from p_expected_consumer_auth_user_id::text\n     or p_render_input_payload ->> ''briefcaseItemId'' is distinct from p_consumer_briefcase_item_id::text\n     or p_render_input_payload ->> ''matterId'' is distinct from p_matter_id::text\n     or p_render_input_payload ->> ''verificationHash'' is distinct from p_expected_verification_hash\n     or p_render_input_payload ->> ''inputHash'' is distinct from p_input_hash then\n    raise exception ''consumer render payload binding mismatch'';\n  end if;\n  select v.verification_hash into v_hash from public.consumer_packet_verifications v\n    where v.briefcase_item_id = p_consumer_briefcase_item_id\n      and v.consumer_auth_user_id = p_expected_consumer_auth_user_id\n      and v.status = ''verified'' for update;\n  if v_hash is null or v_hash is distinct from p_expected_verification_hash then\n    raise exception ''consumer render verification changed'';\n  end if;\n  select a.valid into v_authorized from public.consumer_packet_payment_authority(\n    p_consumer_briefcase_item_id, p_expected_consumer_auth_user_id,\n    public.expungement_packet_product_id(), p_person_id, p_matter_id\n  ) a;\n  if not coalesce(v_authorized, false) then raise exception ''consumer render entitlement missing''; end if;\n\n  insert into public.rcap_document_packets (\n    id, partner_slug, user_id, briefcase_id, person_id, state, jurisdiction,\n    document_type, pathway, status, petitioner_first_name, petitioner_last_name,\n    petitioner_city, petitioner_county, court_county, court_name, cause_number,\n    charge, offense_date, arrest_date, arresting_agency, agency_case_number,\n    disposition_date, conviction_date, sentence_completion_date,\n    needs_record_review, generated_plain_text, filing_instructions,\n    county_court_instructions, missing_fields, safety_disclaimer\n  ) values (\n    p_packet_id, ''expungement-ai-consumer'', p_expected_consumer_auth_user_id,\n    p_consumer_briefcase_item_id, p_person_id,\n    p_render_packet ->> ''state'', p_render_packet ->> ''jurisdiction'',\n    p_render_packet ->> ''document_type'', p_render_packet ->> ''pathway'',\n    coalesce(p_render_packet ->> ''status'', ''ready_for_review''),\n    p_render_packet ->> ''petitioner_first_name'', p_render_packet ->> ''petitioner_last_name'',\n    p_render_packet ->> ''petitioner_city'', p_render_packet ->> ''petitioner_county'',\n    p_render_packet ->> ''court_county'', p_render_packet ->> ''court_name'',\n    p_render_packet ->> ''cause_number'', p_render_packet ->> ''charge'',\n    p_render_packet ->> ''offense_date'', p_render_packet ->> ''arrest_date'',\n    p_render_packet ->> ''arresting_agency'', p_render_packet ->> ''agency_case_number'',\n    p_render_packet ->> ''disposition_date'', p_render_packet ->> ''conviction_date'',\n    p_render_packet ->> ''sentence_completion_date'',\n    coalesce((p_render_packet ->> ''needs_record_review'')::boolean, true),\n    p_render_packet ->> ''generated_plain_text'',\n    array(select jsonb_array_elements_text(coalesce(p_render_packet -> ''filing_instructions'', ''[]''::jsonb))),\n    array(select jsonb_array_elements_text(coalesce(p_render_packet -> ''county_court_instructions'', ''[]''::jsonb))),\n    array(select jsonb_array_elements_text(coalesce(p_render_packet -> ''missing_fields'', ''[]''::jsonb))),\n    p_render_packet ->> ''safety_disclaimer''\n  ) on conflict (id) do nothing;\n\n  select i.input_payload into v_existing_payload from public.rcap_document_packet_inputs i\n    where i.document_packet_id = p_packet_id and i.partner_slug = ''expungement-ai-consumer'' for update;\n  if found and v_existing_payload is distinct from p_render_input_payload then\n    raise exception ''consumer render input payload is immutable'';\n  end if;\n  if not found then\n    insert into public.rcap_document_packet_inputs(document_packet_id, partner_slug, input_payload)\n      values (p_packet_id, ''expungement-ai-consumer'', p_render_input_payload);\n  end if;\n\n  select * into v_job from public.enqueue_packet_render_job(\n    p_packet_id, p_route_id, p_renderer_kind, p_renderer_version,\n    p_source_sha256, p_profile_id, p_profile_version, p_input_hash,\n    p_briefcase_item_id, null, p_person_id, p_matter_id,\n    p_max_attempts, p_consumer_briefcase_item_id, p_expected_consumer_auth_user_id\n  );\n  if v_job.id is null then raise exception ''consumer render enqueue failed''; end if;\n  update public.packet_render_jobs j set consumer_verification_hash = p_expected_verification_hash\n    where j.id = v_job.id and j.consumer_verification_hash is null;\n  select * into v_job from public.packet_render_jobs j where j.id = v_job.id;\n  return next v_job;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:revoke_consumer_artifact_download_grant":{"revoke_consumer_artifact_download_grant(uuid,uuid,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.revoke_consumer_artifact_download_grant(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid, p_grant_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare v_count integer;\nbegin\n  update public.consumer_artifact_download_grants g set revoked_at = coalesce(g.revoked_at, now())\n   where g.id = p_grant_id\n     and g.consumer_auth_user_id = p_consumer_auth_user_id\n     and g.briefcase_item_id = p_briefcase_item_id\n     and exists (select 1 from public.consumer_briefcase_items i\n       where i.id = g.briefcase_item_id and i.user_id = p_consumer_auth_user_id);\n  get diagnostics v_count = row_count;\n  return v_count = 1;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"column:consumer_artifact_download_grants.file_name":{"type":"text","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_artifact_download_grants.matter_id":{"type":"uuid","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.artifact_refs_json":{"type":"jsonb","default":"''{}''::jsonb","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.payment_product_id":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.normalized_output_sha256":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:sponsored_packet_render_routes.jurisdiction":{"type":"text","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:sponsored_packet_render_routes.partner_slug":{"type":"text","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:enqueue_verified_sponsored_packet_render":{"enqueue_verified_sponsored_packet_render(text,uuid,uuid,text,text,text,text,text,text,text,uuid,uuid,uuid,integer,uuid,text,jsonb,jsonb)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.enqueue_verified_sponsored_packet_render(p_route_key text, p_session_id uuid, p_packet_id uuid, p_route_id text, p_renderer_kind text, p_renderer_version text, p_source_sha256 text, p_profile_id text, p_profile_version text, p_input_hash text, p_briefcase_item_id uuid, p_person_id uuid, p_matter_id uuid, p_max_attempts integer, p_expected_consumer_auth_user_id uuid, p_expected_verification_hash text, p_render_packet jsonb, p_render_input_payload jsonb)\n RETURNS SETOF packet_render_jobs\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_route public.sponsored_packet_render_routes%rowtype;\n  v_authority record;\n  v_hash text;\n  v_job public.packet_render_jobs%rowtype;\n  v_existing_payload jsonb;\nbegin\n  select * into v_route from public.sponsored_packet_render_routes r\n   where r.route_key = p_route_key and r.active;\n  if not found then\n    raise exception ''sponsored render route is not registered'';\n  end if;\n\n  -- The render input is the participant''s document. Every identity inside it\n  -- must equal the registration and the caller''s claimed binding, or nothing\n  -- is created.\n  if p_render_packet ->> ''id'' is distinct from p_packet_id::text\n     or p_render_packet ->> ''user_id'' is distinct from p_expected_consumer_auth_user_id::text\n     or p_render_packet ->> ''briefcase_id'' is distinct from p_briefcase_item_id::text\n     or p_render_packet ->> ''person_id'' is distinct from p_person_id::text\n     or p_render_input_payload ->> ''authUserId'' is distinct from p_expected_consumer_auth_user_id::text\n     or p_render_input_payload ->> ''briefcaseItemId'' is distinct from p_briefcase_item_id::text\n     or p_render_input_payload ->> ''matterId'' is distinct from p_matter_id::text\n     or p_render_input_payload ->> ''verificationHash'' is distinct from p_expected_verification_hash\n     or p_render_input_payload ->> ''inputHash'' is distinct from p_input_hash then\n    raise exception ''sponsored render payload binding mismatch'';\n  end if;\n  if trim(coalesce(p_route_id, '''')) is distinct from v_route.route_key\n     or p_render_input_payload ->> ''routeId'' is distinct from v_route.route_key\n     or p_render_input_payload ->> ''packetFamilyId'' is distinct from v_route.packet_family_id\n     or p_render_input_payload ->> ''specificationId'' is distinct from v_route.packet_specification_id\n     or p_render_input_payload ->> ''specificationVersion'' is distinct from v_route.packet_specification_version\n     or p_render_input_payload ->> ''specificationSha256'' is distinct from v_route.packet_specification_sha256\n     or (v_route.registry_track_id is not null\n         and p_render_input_payload ->> ''trackId'' is distinct from v_route.registry_track_id)\n     or p_render_input_payload -> ''snapshot'' ->> ''jurisdiction'' is distinct from v_route.jurisdiction\n     or p_render_input_payload -> ''snapshot'' ->> ''pathwayId'' is distinct from v_route.pathway_id\n     or (v_route.registry_track_id is not null\n         and p_render_input_payload -> ''snapshot'' ->> ''selectedTrackId'' is distinct from v_route.registry_track_id) then\n    raise exception ''sponsored render route binding mismatch'';\n  end if;\n\n  select v.verification_hash into v_hash from public.consumer_packet_verifications v\n    where v.briefcase_item_id = p_briefcase_item_id\n      and v.consumer_auth_user_id = p_expected_consumer_auth_user_id\n      and v.status = ''verified'' for update;\n  if v_hash is null or v_hash is distinct from p_expected_verification_hash then\n    raise exception ''sponsored render verification changed'';\n  end if;\n\n  select * into v_authority from public.sponsored_packet_render_authority(\n    p_route_key, p_session_id, p_briefcase_item_id, p_expected_consumer_auth_user_id\n  );\n  if not coalesce(v_authority.valid, false) then\n    raise exception ''sponsored render authority missing: %'', coalesce(v_authority.reason, ''unknown'');\n  end if;\n  if p_matter_id is distinct from public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id) then\n    raise exception ''sponsored render matter binding mismatch'';\n  end if;\n\n  insert into public.rcap_document_packets (\n    id, partner_slug, user_id, briefcase_id, person_id, state, jurisdiction,\n    document_type, pathway, status, petitioner_first_name, petitioner_last_name,\n    petitioner_city, petitioner_county, court_county, court_name, cause_number,\n    charge, offense_date, arrest_date, arresting_agency, agency_case_number,\n    disposition_date, conviction_date, sentence_completion_date,\n    needs_record_review, generated_plain_text, filing_instructions,\n    county_court_instructions, missing_fields, safety_disclaimer\n  ) values (\n    p_packet_id, ''expungement-ai-consumer'', p_expected_consumer_auth_user_id,\n    p_briefcase_item_id, p_person_id,\n    p_render_packet ->> ''state'', p_render_packet ->> ''jurisdiction'',\n    p_render_packet ->> ''document_type'', p_render_packet ->> ''pathway'',\n    coalesce(p_render_packet ->> ''status'', ''ready_for_review''),\n    p_render_packet ->> ''petitioner_first_name'', p_render_packet ->> ''petitioner_last_name'',\n    p_render_packet ->> ''petitioner_city'', p_render_packet ->> ''petitioner_county'',\n    p_render_packet ->> ''court_county'', p_render_packet ->> ''court_name'',\n    p_render_packet ->> ''cause_number'', p_render_packet ->> ''charge'',\n    p_render_packet ->> ''offense_date'', p_render_packet ->> ''arrest_date'',\n    p_render_packet ->> ''arresting_agency'', p_render_packet ->> ''agency_case_number'',\n    p_render_packet ->> ''disposition_date'', p_render_packet ->> ''conviction_date'',\n    p_render_packet ->> ''sentence_completion_date'',\n    coalesce((p_render_packet ->> ''needs_record_review'')::boolean, true),\n    p_render_packet ->> ''generated_plain_text'',\n    array(select jsonb_array_elements_text(coalesce(p_render_packet -> ''filing_instructions'', ''[]''::jsonb))),\n    array(select jsonb_array_elements_text(coalesce(p_render_packet -> ''county_court_instructions'', ''[]''::jsonb))),\n    array(select jsonb_array_elements_text(coalesce(p_render_packet -> ''missing_fields'', ''[]''::jsonb))),\n    p_render_packet ->> ''safety_disclaimer''\n  ) on conflict (id) do nothing;\n\n  select i.input_payload into v_existing_payload from public.rcap_document_packet_inputs i\n    where i.document_packet_id = p_packet_id and i.partner_slug = ''expungement-ai-consumer'' for update;\n  if found and v_existing_payload is distinct from p_render_input_payload then\n    raise exception ''sponsored render input payload is immutable'';\n  end if;\n  if not found then\n    insert into public.rcap_document_packet_inputs(document_packet_id, partner_slug, input_payload)\n      values (p_packet_id, ''expungement-ai-consumer'', p_render_input_payload);\n  end if;\n\n  select * into v_job from public.enqueue_packet_render_job(\n    p_packet_id, p_route_id, p_renderer_kind, p_renderer_version,\n    p_source_sha256, p_profile_id, p_profile_version, p_input_hash,\n    p_briefcase_item_id, v_authority.partner_id, p_person_id, p_matter_id,\n    p_max_attempts, null, null\n  );\n  if v_job.id is null then raise exception ''sponsored render enqueue failed''; end if;\n\n  update public.packet_render_jobs j set\n    sponsored_route_key = v_route.route_key,\n    sponsored_session_id = p_session_id,\n    sponsored_clinic_event_id = v_authority.clinic_event_id,\n    sponsored_consumer_briefcase_item_id = p_briefcase_item_id,\n    sponsored_consumer_auth_user_id = p_expected_consumer_auth_user_id,\n    sponsored_verification_hash = p_expected_verification_hash\n  where j.id = v_job.id and j.sponsored_route_key is null;\n\n  select * into v_job from public.packet_render_jobs j where j.id = v_job.id;\n  if v_job.sponsored_route_key is distinct from v_route.route_key\n     or v_job.sponsored_consumer_briefcase_item_id is distinct from p_briefcase_item_id\n     or v_job.sponsored_consumer_auth_user_id is distinct from p_expected_consumer_auth_user_id\n     or v_job.sponsored_verification_hash is distinct from p_expected_verification_hash\n     or v_job.sponsored_session_id is distinct from p_session_id then\n    raise exception ''sponsored render job is bound to a different participant or route'';\n  end if;\n  return next v_job;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"column:consumer_artifact_download_grants.created_at":{"type":"timestamp with time zone","default":"now()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_artifact_download_grants.expires_at":{"type":"timestamp with time zone","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_artifact_download_grants.revoked_at":{"type":"timestamp with time zone","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_