"type":"uuid","notNull":false},{"name":"payment_person_id","type":"uuid","notNull":false},{"name":"payment_product_id","type":"text","notNull":false},{"name":"payment_provider","type":"text","notNull":false},{"name":"payment_recorded_at","type":"timestamp with time zone","notNull":false},{"name":"payment_recorded_by","type":"text","notNull":false},{"name":"payment_status","type":"text","notNull":true},{"name":"provider_event_id","type":"text","notNull":false},{"name":"receipt_url","type":"text","notNull":false},{"name":"regular_price_cents","type":"integer","notNull":false},{"name":"reminder_at","type":"timestamp with time zone","notNull":false},{"name":"result_code","type":"text","notNull":false},{"name":"source_pending_result_id","type":"uuid","notNull":false},{"name":"source_session_id","type":"text","notNull":false},{"name":"status","type":"text","notNull":true},{"name":"summary_json","type":"jsonb","notNull":true},{"name":"updated_at","type":"timestamp with time zone","notNull":true},{"name":"user_id","type":"uuid","notNull":true}],"present":true},"partner_packet_entitlement":{"rls":true,"kind":"r","owner":"postgres","columns":[{"name":"contract_note","type":"text","notNull":false},{"name":"created_at","type":"timestamp with time zone","notNull":true},{"name":"effective_at","type":"timestamp with time zone","notNull":true},{"name":"entitlement_scope","type":"text","notNull":true},{"name":"expires_at","type":"timestamp with time zone","notNull":false},{"name":"id","type":"uuid","notNull":true},{"name":"overage_cap","type":"integer","notNull":true},{"name":"overage_enabled","type":"boolean","notNull":true},{"name":"packet_cap","type":"integer","notNull":true},{"name":"partner_id","type":"uuid","notNull":true},{"name":"pause_at_cap","type":"boolean","notNull":true},{"name":"updated_at","type":"timestamp with time zone","notNull":true}],"present":true},"consumer_packet_verifications":{"rls":true,"kind":"r","owner":"postgres","columns":[{"name":"briefcase_item_id","type":"uuid","notNull":true},{"name":"consumer_auth_user_id","type":"uuid","notNull":true},{"name":"created_at","type":"timestamp with time zone","notNull":true},{"name":"draft_hash","type":"text","notNull":true},{"name":"draft_snapshot","type":"jsonb","notNull":true},{"name":"invalidated_at","type":"timestamp with time zone","notNull":false},{"name":"matter_id","type":"uuid","notNull":true},{"name":"reason","type":"text","notNull":true},{"name":"revision","type":"integer","notNull":true},{"name":"status","type":"text","notNull":true},{"name":"updated_at","type":"timestamp with time zone","notNull":true},{"name":"verification_hash","type":"text","notNull":false},{"name":"verification_snapshot","type":"jsonb","notNull":false}],"present":true},"sponsored_packet_render_routes":{"rls":true,"kind":"r","owner":"postgres","columns":[{"name":"active","type":"boolean","notNull":true},{"name":"artifact_content_type","type":"text","notNull":true},{"name":"artifact_provider","type":"text","notNull":true},{"name":"artifact_source","type":"text","notNull":true},{"name":"clinic_event_name","type":"text","notNull":false},{"name":"created_at","type":"timestamp with time zone","notNull":true},{"name":"jurisdiction","type":"text","notNull":true},{"name":"packet_family_id","type":"text","notNull":true},{"name":"packet_specification_id","type":"text","notNull":true},{"name":"packet_specification_sha256","type":"text","notNull":true},{"name":"packet_specification_version","type":"text","notNull":true},{"name":"partner_slug","type":"text","notNull":true},{"name":"pathway_id","type":"text","notNull":true},{"name":"program_key","type":"text","notNull":true},{"name":"registry_track_id","type":"text","notNull":false},{"name":"route_key","type":"text","notNull":true},{"name":"updated_at","type":"timestamp with time zone","notNull":true}],"present":true},"consumer_pending_screening_results":{"rls":true,"kind":"r","owner":"postgres","columns":[{"name":"access_code_id","type":"uuid","notNull":fal