ue},{"name":"consumer_auth_user_id","type":"uuid","notNull":true},{"name":"created_at","type":"timestamp with time zone","notNull":true},{"name":"entitlement_source","type":"text","notNull":true},{"name":"legacy_evidence","type":"jsonb","notNull":false},{"name":"matter_id","type":"uuid","notNull":true},{"name":"render_job_id","type":"uuid","notNull":false},{"name":"revision","type":"integer","notNull":true},{"name":"superseded_artifacts","type":"jsonb","notNull":true},{"name":"updated_at","type":"timestamp with time zone","notNull":true},{"name":"verification_hash","type":"text","notNull":false}],"present":true}},"function_signatures":["consumer_matter_id_for_briefcase_item(uuid)","sponsored_packet_render_authority(text,uuid,uuid,uuid)"]}'::jsonb then raise exception 'prerequisite_forward_precondition_changed'; end if; end $prerequisite_gate$;

do $funding_gate$ declare funding_actual jsonb; begin select catalog into funding_actual from (with objects as (
 select 'table:'||c.relname as key, jsonb_build_object(
 'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,
 'columns',coalesce((select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'acl',a.attacl::text) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'[]'::jsonb),
 'constraints',coalesce((select jsonb_object_agg(conname,jsonb_build_object('type',contype,'definition',pg_get_constraintdef(oid,true),'validated',convalidated)) from pg_constraint where conrelid=c.oid and contype<>'n'),'{}'::jsonb),
 'indexes',coalesce((select jsonb_object_agg(i.relname,jsonb_build_object('definition',pg_get_indexdef(i.oid),'valid',x.indisvalid,'ready',x.indisready)) from pg_index x join pg_class i on i.oid=x.indexrelid where x.indrelid=c.oid),'{}'::jsonb),
 'policies',coalesce((select jsonb_object_agg(polname,jsonb_build_object('permissive',polpermissive,'roles',(select jsonb_agg(case when r=0 then 'public' else pg_get_userbyid(r) end order by case when r=0 then 'public' else pg_get_userbyid(r) end) from unnest(polroles) r),'command',polcmd,'using',pg_get_expr(polqual,polrelid),'check',pg_get_expr(polwithcheck,polrelid))) from pg_policy where polrelid=c.oid),'{}'::jsonb),
 'triggers',coalesce((select jsonb_object_agg(tgname,jsonb_build_object('definition',pg_get_triggerdef(oid,true),'enabled',tgenabled)) from pg_trigger where tgrelid=c.oid and not tgisinternal),'{}'::jsonb),
 'effectivePrivileges',(select jsonb_object_agg(r,(select jsonb_object_agg(priv,jsonb_build_object('allowed',has_table_privilege(r,c.oid,priv),'grantable',has_table_privilege(r,c.oid,priv||' WITH GRANT OPTION'))) from unnest(array['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) priv)) from unnest(array['anon','authenticated','service_role','rcap_render_worker','rcap_packet_delivery']) r),
 'acl',coalesce((select jsonb_agg(jsonb_build_object('role',case when x.grantee=0 then 'public' else pg_get_userbyid(x.grantee) end,'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) order by case when x.grantee=0 then 'public' else pg_get_userbyid(x.grantee) end,x.privilege_type,pg_get_userbyid(x.grantor)) from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x),'[]'::jsonb)
 ) value from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='clinic_packet_funding'
 union all
 select 'function:'||p.proname||'('||replace(oidvectortypes(p.proargtypes),', ', ',')||')',jsonb_build_object(
 'kind',p.prokind,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'securityDefiner',p.prosecdef,'config',p.proconfig,'volatility',p.provolatile,'language',l.lanname,
 'acl',coalesce((select jsonb_agg(jsonb_build_object('role',case when x.grantee=0 then 'public' else pg_get_userbyid(x.grantee) end,'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) order by case when x.grantee=0 then 'public' else pg_get_userbyid(x.grantee) end,x.privilege_type,pg_get_userbyid(x.grantor)) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x),'[]'::jsonb),
 'execute',(select jsonb_object_agg(r,jsonb_build_object('allowed',has_function_privilege(r,p.oid,'EXECUTE'),'grantable',has_function_privilege(r,p.oid,'EXECUTE WITH GRANT OPTION'))) from unnest(array['anon','authenticated','service_role','rcap_render_worker','rcap_packet_delivery']) r)
 ) from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname='public' and p.proname in ('allocate_clinic_packet_funding','clinic_packet_dtc_authorized','clinic_entry_sponsor_capacity')
) select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) as catalog from objects) source; if funding_actual is distinct from '{}'::jsonb then raise exception 'funding_forward_precondition_changed'; end if; end $funding_gate$;

create table public.clinic_packet_funding (
  briefcase_item_id uuid primary key references public.consumer_briefcase_items(id) on delete cascade,
  consumer_auth_user_id uuid not null,
  source_session_id uuid not null,
  event_id uuid not null references public.clinic_events(id),
  partner_slug text not null,
  packet_entitlement_id uuid not null references public.partner_packet_entitlement(id),
  route_key text not null,
  packet_family_id text not null,
  initial_verification_hash text not null check (initial_verification_hash ~ '^[a-f0-9]{64}$'),
  funding_mode text not null check (funding_mode in ('sponsored','dtc')),
  reason text not null check (reason in ('slot_reserved','event_cap_exhausted','partner_cap_exhausted')),
  created_at timestamptz not null default now()
);
alter table public.clinic_packet_funding enable row level security;
revoke all on public.clinic_packet_funding from public, anon, authenticated, service_role;
grant select on public.clinic_packet_funding to service_role;
comment on table public.clinic_packet_funding is
  'One immutable financial choice per owner-bound matter. A sponsored row reserves capacity, not delivered credit. DTC is a cap decision, never payment evidence. Source attribution stays unchanged.';

create function public.allocate_clinic_packet_funding(
  p_briefcase_item_id uuid, p_consumer_auth_user_id uuid, p_expected_verification_hash text
) returns table(funding_mode text, reason text)
language plpgsql security definer set search_path = '' as $funding$
declare
  v_item public.consumer_briefcase_items%rowtype;
  v_verification public.consumer_packet_verifications%rowtype;
  v_source public.consumer_pending_screening_results%rowtype;
  v_session public.screening_sessions%rowtype;
  v_case public.clinic_cases%rowtype;
  v_event public.clinic_events%rowtype;
  v_entitlement public.partner_entitlement%rowtype;
  v_choice public.clinic_packet_funding%rowtype;
  v_packet_entitlement public.partner_packet_entitlement%rowtype;
  v_packet_used bigint;
  v_route public.sponsored_packet_render_routes%rowtype;
  v_scope record;
  v_event_used bigint;
  v_partner_reserved bigint;
  v_mode text := 'sponsored';
  v_reason text := 'slot_reserved';
begin
  -- Match the canonical finalizer lock order. No client-selected sponsor/event.
  select * into v_item from public.consumer_briefcase_items
    where id=p_briefcase_item_id and user_id=p_consumer_auth_user_id for update;
  if not found then return query select 'denied'::text,'wrong_owner'::text; return; end if;
  select * into v_verification from public.consumer_packet_verifications
    where briefcase_item_id=v_item.id for update;
  if not found or v_verification.consumer_auth_user_id is distinct from v_item.user_id
     or v_verification.matter_id is distinct from public.consumer_matter_id_for_briefcase_item(v_item.id)
     or v_verification.status is distinct from 'verified'
     or v_verification.verification_hash is distinct from p_expected_verification_hash
     or p_expected_verification_hash is null then
    return query select 'denied'::text,'verification_mismatch'::text; return;
  end if;
  select * into v_source from public.consumer_pending_screening_results
    where pending_id=v_item.source_pending_result_id for update;
  if not found or v_source.product is distinct from 'rcap_partner'
     or v_source.claimed_user_id is distinct from v_item.user_id
     or v_source.claimed_matter_id is distinct from v_item.id or v_source.status is distinct from 'CLAIMED' then
    return query select 'denied'::text,'source_mismatch'::text; return;
  end if;
  select * into v_session from public.screening_sessions
    where session_id=v_source.anonymous_session_id for update;
  select * into v_case from public.clinic_cases
    where matter_id=v_item.id and participant_user_id=v_item.user_id
      and screening_session_id=v_source.anonymous_session_id and event_id=v_source.event_id for update;
  if not found then return query select 'denied'::text,'clinic_scope_mismatch'::text; return; end if;
  select * into v_event from public.clinic_events where id=v_case.event_id for update;
  select * into v_route from public.sponsored_packet_render_routes
    where route_key=(v_verification.verification_snapshot->>'jurisdiction')||':'||
      (v_verification.verification_snapshot->>'pathwayId') and active;
  if not found or (v_route.registry_track_id is not null and v_route.registry_track_id is distinct from
       v_verification.verification_snapshot->>'selectedTrackId') then
    return query select 'denied'::text,'route_mismatch'::text; return;
  end if;
  select * into v_scope from public.sponsored_packet_render_authority(
    v_route.route_key, v_source.anonymous_session_id, v_item.id, v_item.user_id);
  if not coalesce(v_scope.valid,false) then return query select 'denied'::text,v_scope.reason; return; end if;
  select * into v_choice from public.clinic_packet_funding where briefcase_item_id=v_item.id;
  if found then
    if v_choice.consumer_auth_user_id is distinct from v_item.user_id
       or v_choice.source_session_id is distinct from v_source.anonymous_session_id
       or v_choice.event_id is distinct from v_event.id or v_choice.partner_slug is distinct from v_event.partner_slug
       or v_choice.route_key is distinct from v_route.route_key or v_choice.packet_family_id is distinct from v_route.packet_family_id then
      return query select 'denied'::text,'funding_binding_mismatch'::text; return;
    end if;
    return query select v_choice.funding_mode,v_choice.reason; return;
  end if;
  -- Reuse delivered Applicant A and other already-consumed packets read-only.
  if exists(select 1 from public.consumer_packet_artifact_provenance p where p.briefcase_item_id=v_item.id
      and p.consumer_auth_user_id=v_item.user_id and p.entitlement_source='partner_sponsorship') then
    return query select 'sponsored'::text,'already_consumed'::text; return;
  end if;
  if v_session.claimed_slot_state is distinct from 'claimed' then
    return query select 'denied'::text,'sponsorship_inactive'::text; return;
  end if;
  -- Event and partner locks serialize all contenders, including different
  -- events sharing the final partner slot. Count reserved OR consumed once.
  select * into v_entitlement from public.partner_entitlement where partner_slug=v_event.partner_slug for update;
  if not found then return query select 'denied'::text,'no_entitlement'::text; return; end if;
  select count(*) into v_event_used from (
    select p.briefcase_item_id from public.consumer_packet_artifact_provenance p
      join public.clinic_cases c on c.matter_id=p.briefcase_item_id
      where c.event_id=v_event.id and p.entitlement_source='partner_sponsorship'
    union
    select f.briefcase_item_id from public.clinic_packet_funding f
      where f.event_id=v_event.id and f.funding_mode='sponsored'
  ) used;
  select count(*) into v_partner_reserved from public.clinic_packet_funding f
    where f.partner_slug=v_event.partner_slug and f.funding_mode='sponsored'
      and not exists(select 1 from public.consumer_packet_artifact_provenance p
        where p.briefcase_item_id=f.briefcase_item_id and p.entitlement_source='partner_sponsorship');
  select * into v_packet_entitlement from public.partner_packet_entitlement e
    where e.partner_id=v_scope.partner_id and e.effective_at<=now()
      and (e.expires_at is null or e.expires_at>now()) order by e.effective_at desc limit 1 for update;
  if not found then return query select 'denied'::text,'no_entitlement'::text; return; end if;
  select count(*) into v_packet_used from (
    select l.matter_id from public.packet_credit_ledger l where l.entitlement_id=v_packet_entitlement.id
      and l.event_type in ('consumed','overage_consumed')
    union
    select public.consumer_matter_id_for_briefcase_item(f.briefcase_item_id) from public.clinic_packet_funding f
      where f.packet_entitlement_id=v_packet_entitlement.id and f.funding_mode='sponsored'
  ) used;
  if v_event_used >= v_event.sponsorship_allocation then v_mode:='dtc'; v_reason:='event_cap_exhausted';
  elsif v_entitlement.screenings_used+v_partner_reserved >= v_entitlement.screenings_allowed
     or v_packet_used >= v_packet_entitlement.packet_cap then
    v_mode:='dtc'; v_reason:='partner_cap_exhausted';
  end if;
  insert into public.clinic_packet_funding(briefcase_item_id,consumer_auth_user_id,source_session_id,event_id,
    partner_slug,packet_entitlement_id,route_key,packet_family_id,initial_verification_hash,funding_mode,reason)
    values(v_item.id,v_item.user_id,v_source.anonymous_session_id,v_event.id,v_event.partner_slug,
      v_packet_entitlement.id,v_route.route_key,v_route.packet_family_id,p_expected_verification_hash,v_mode,v_reason);
  return query select v_mode,v_reason;
end;
$funding$;
revoke all on function public.allocate_clinic_packet_funding(uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.allocate_clinic_packet_funding(uuid,uuid,text) to service_role;

-- A read cannot allocate a slot, turn a refusal into DTC, or change source.
create function public.clinic_packet_dtc_authorized(p_item uuid,p_owner uuid)
returns boolean language sql stable security definer set search_path='' as $dtc$
  select exists(select 1 from public.clinic_packet_funding f
    join public.consumer_briefcase_items i on i.id=f.briefcase_item_id and i.user_id=f.consumer_auth_user_id
    join public.consumer_pending_screening_results s on s.pending_id=i.source_pending_result_id
      and s.claimed_matter_id=i.id and s.claimed_user_id=i.user_id and s.status='CLAIMED'
      and s.anonymous_session_id=f.source_session_id and s.event_id=f.event_id and s.partner_slug=f.partner_slug
      and s.product='rcap_partner'
    join public.clinic_events e on e.id=f.event_id and e.partner_slug=f.partner_slug
    join public.clinic_cases c on c.event_id=f.event_id and c.matter_id=i.id
      and c.participant_user_id=i.user_id and c.screening_session_id=f.source_session_id
    join public.consumer_packet_verifications v on v.briefcase_item_id=i.id and v.consumer_auth_user_id=i.user_id
      and (v.verification_snapshot->>'jurisdiction')||':'||(v.verification_snapshot->>'pathwayId')=f.route_key
    join public.sponsored_packet_render_routes r on r.route_key=f.route_key and r.packet_family_id=f.packet_family_id
      and (r.registry_track_id is null or r.registry_track_id=v.verification_snapshot->>'selectedTrackId')
    where f.briefcase_item_id=p_item and f.consumer_auth_user_id=p_owner and f.funding_mode='dtc');
$dtc$;
revoke all on function public.clinic_packet_dtc_authorized(uuid,uuid) from public,anon,authenticated;
grant execute on function public.clinic_packet_dtc_authorized(uuid,uuid) to service_role;

-- Entry has no persistent matter yet. This is a read-only availability hint;
-- the allocation transaction remains the final authority under concurrency.
create function public.clinic_entry_sponsor_capacity(p_event uuid,p_partner text)
returns boolean language plpgsql stable security definer set search_path='' as $entry$
declare e public.clinic_events%rowtype; allowance public.partner_entitlement%rowtype;
  event_used bigint; reserved bigint; packet_allowance public.partner_packet_entitlement%rowtype; packet_used bigint;
begin
  select * into e from public.clinic_events where id=p_event and partner_slug=p_partner and status='published';
  if not found then raise exception 'invalid_event_scope'; end if;
  select * into allowance from public.partner_entitlement where partner_slug=e.partner_slug;
  if not found then raise exception 'missing_sponsor_authority'; end if;
  select count(*) into event_used from (
    select f.briefcase_item_id from public.clinic_packet_funding f where f.event_id=e.id and f.funding_mode='sponsored'
    union select p.briefcase_item_id from public.consumer_packet_artifact_provenance p
      join public.clinic_cases c on c.matter_id=p.briefcase_item_id where c.event_id=e.id and p.entitlement_source='partner_sponsorship'
  ) used;
  select count(*) into reserved from public.clinic_packet_funding f where f.partner_slug=e.partner_slug and f.funding_mode='sponsored'
    and not exists(select 1 from public.consumer_packet_artifact_provenance p where p.briefcase_item_id=f.briefcase_item_id and p.entitlement_source='partner_sponsorship');
  select ent.* into packet_allowance from public.partner_packet_entitlement ent join public.partner_records p on p.id=ent.partner_id
    where p.partner_slug=e.partner_slug and ent.effective_at<=now() and (ent.expires_at is null or ent.expires_at>now())
    order by ent.effective_at desc limit 1;
  if not found then raise exception 'missing_sponsor_authority'; end if;
  select count(*) into packet_used from (
    select l.matter_id from public.packet_credit_ledger l where l.entitlement_id=packet_allowance.id and l.event_type in ('consumed','overage_consumed')
    union select public.consumer_matter_id_for_briefcase_item(f.briefcase_item_id) from public.clinic_packet_funding f where f.packet_entitlement_id=packet_allowance.id and f.funding_mode='sponsored'
  ) used;
  return event_used<e.sponsorship_allocation and allowance.screenings_used+reserved<allowance.screenings_allowed and packet_used<packet_allowance.packet_cap;
end;
$entry$;
revoke all on function public.clinic_entry_sponsor_capacity(uuid,text) from public,anon,authenticated;
grant execute on function public.clinic_entry_sponsor_capacity(uuid,text) to service_role;

alter table public.packet_render_jobs add column retry_reconciliation_history jsonb not null default '[]'::jsonb;

CREATE OR REPLACE FUNCTION public.claim_packet_render_job(p_worker_id text, p_renderer_kinds text[], p_claim_seconds integer DEFAULT 600)
 RETURNS TABLE(id uuid, packet_id uuid, route_id text, renderer_kind text, renderer_version text, source_sha256 text, profile_id text, profile_version text, input_hash text, attempt_count integer, max_attempts integer, partner_id uuid, person_id uuid, matter_id uuid, fencing_token uuid, claim_expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_worker_id text;
  v_job_id uuid;
  v_token uuid;
begin
  v_worker_id := nullif(trim(p_worker_id), '');
  if v_worker_id is null then
    raise exception 'a worker id is required to claim a job';
  end if;
  if p_claim_seconds is null or p_claim_seconds < 30 or p_claim_seconds > 3600 then
    raise exception 'claim seconds must be between 30 and 3600';
  end if;

  select j.id into v_job_id
  from public.packet_render_jobs j
  where j.status = 'queued'
    and j.attempt_count < j.max_attempts
    and (j.next_attempt_at is null or j.next_attempt_at <= now())
    and (p_renderer_kinds is null or j.renderer_kind = any (p_renderer_kinds))
  order by j.created_at, j.id
  for update skip locked
  limit 1;

  if v_job_id is null then
    return;
  end if;

  v_token := gen_random_uuid();
  perform set_config('rcap.packet_mutation_authority', 'claim_packet_render_job', true);
  return query
  update public.packet_render_jobs j
  set status = 'claimed',
      claimed_by = v_worker_id,
      claim_expires_at = now() + make_interval(secs => p_claim_seconds),
      fencing_token = v_token,
      attempt_count = j.attempt_count + 1
  where j.id = v_job_id
  returning j.id, j.packet_id, j.route_id, j.renderer_kind, j.renderer_version,
            j.source_sha256, j.profile_id, j.profile_version, j.input_hash,
            j.attempt_count, j.max_attempts, j.partner_id, j.person_id, j.matter_id,
            j.fencing_token, j.claim_expires_at;
  perform set_config('rcap.packet_mutation_authority', '', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.finalize_packet_render_job(p_job_id uuid, p_fencing_token uuid, p_output_storage_path text, p_local_sha256 text, p_local_normalized_sha256 text, p_stored_sha256 text, p_stored_normalized_sha256 text, p_output_byte_count integer, p_output_page_count integer, p_container_digest text)
 RETURNS TABLE(accounting_result text, delivery_eligibility text, consumption_unit_hash text, credit_ledger_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_job public.packet_render_jobs%rowtype;
  v_entitlement public.partner_packet_entitlement%rowtype;
  v_unit_hash text;
  v_used integer;
  v_overage_used integer;
  v_event_type text;
  v_result text;
  v_eligibility text;
  v_ledger_id uuid;
  v_auth record;
  v_existing public.consumer_packet_payment_consumption%rowtype;
begin
  select * into v_job from public.packet_render_jobs where id = p_job_id for update;
  if not found then
    return query select 'not_found'::text, 'not_evaluated'::text, null::text, null::uuid;
    return;
  end if;

  if v_job.status in ('artifact_validated', 'delivered') and v_job.accounting_result is not null then
    return query select v_job.accounting_result, v_job.delivery_eligibility,
      (select l.consumption_unit_hash from public.packet_credit_ledger l where l.id = v_job.credit_ledger_id),
      v_job.credit_ledger_id;
    return;
  end if;

  perform public.assert_packet_render_job_fencing(v_job, p_fencing_token);

  if v_job.status <> 'validating' then
    return query select 'not_validated'::text, v_job.delivery_eligibility, null::text, null::uuid;
    return;
  end if;

  if p_output_storage_path is null
     or position(v_job.id::text in p_output_storage_path) = 0
     or position(coalesce(p_local_sha256, '') in p_output_storage_path) = 0 then
    raise exception 'packet_render_jobs: storage path must bind the job id and output hash';
  end if;

  if p_local_sha256 is null or p_local_sha256 !~ '^[0-9a-f]{64}$'
     or p_stored_sha256 is distinct from p_local_sha256
     or p_local_normalized_sha256 is null or p_local_normalized_sha256 !~ '^[0-9a-f]{64}$'
     or p_stored_normalized_sha256 is distinct from p_local_normalized_sha256 then
    perform set_config('rcap.packet_mutation_authority', 'finalize_packet_render_job', true);
    update public.packet_render_jobs
    set status = 'failed',
        failure_disposition = case when attempt_count < max_attempts then 'retryable' else 'terminal' end,
        error_code = 'checksum_mismatch',
        last_error_detail = 'stored bytes did not match rendered bytes on re-read',
        next_attempt_at = case
          when attempt_count < max_attempts
          then now() + make_interval(secs => least(3600, 30 * power(2, attempt_count))::integer)
          else null
        end,
        fencing_token = null,
        claim_expires_at = null
    where id = p_job_id;
    perform set_config('rcap.packet_mutation_authority', '', true);
    return query select 'not_validated'::text, 'not_evaluated'::text, null::text, null::uuid;
    return;
  end if;

  if nullif(trim(coalesce(p_container_digest, '')), '') is null then
    raise exception 'packet_render_jobs: a container digest is required to finalize';
  end if;

  perform set_config('rcap.packet_mutation_authority', 'finalize_packet_render_job', true);

  update public.packet_render_jobs
  set status = 'artifact_validated',
      output_storage_path = p_output_storage_path,
      output_sha256 = p_local_sha256,
      normalized_output_sha256 = p_local_normalized_sha256,
      output_byte_count = p_output_byte_count,
      page_count = p_output_page_count,
      container_digest = p_container_digest
  where id = p_job_id;

  if v_job.partner_id is null then
    ---------------------------------------------------------------------------
    -- Unsponsored: the consumer payment is the whole authority.
    --
    -- The item checked is the job's own immutable binding, falling back to the
    -- phase-50 briefcase_item_id only when the phase-52 column was never
    -- populated — an older job, which then has no consumer_auth_user_id and so
    -- fails closed at the owner clause rather than silently reverting to the
    -- phase-51 behaviour.
    ---------------------------------------------------------------------------
    select * into v_auth
    from public.consumer_packet_payment_authority(
      coalesce(v_job.consumer_briefcase_item_id, v_job.briefcase_item_id),
      v_job.consumer_auth_user_id
    );

    -- Requirement 4 is a four-tuple, and a consumer job missing any part of it
    -- is not a consumer job this gate can reason about. A null matter in
    -- particular would make the consumption unit meaningless — every matterless
    -- job would collide on one row — so it is refused in the typed vocabulary
    -- rather than allowed to raise a not-null violation out of the insert.
    if v_auth.valid and v_job.matter_id is null then
      v_result := 'consumer_payment_required';
      v_eligibility := 'accounting_blocked';
    elsif not v_auth.valid then
      v_result := case
        when v_auth.reason = 'owner_mismatch' then 'consumer_payment_owner_mismatch'
        else 'consumer_payment_required'
      end;
      v_eligibility := 'accounting_blocked';

      -- Requirement 12: a refund after delivery must not revoke what was already
      -- delivered. If this exact item and matter already consumed, the delivery
      -- stands and re-finalization converges on it instead of blocking.
      select * into v_existing
      from public.consumer_packet_payment_consumption
      where consumer_briefcase_item_id = coalesce(v_job.consumer_briefcase_item_id, v_job.briefcase_item_id)
        and matter_id = v_job.matter_id;

      if found and v_job.consumer_auth_user_id is not null
         and v_existing.consumer_auth_user_id = v_job.consumer_auth_user_id then
        v_unit_hash := v_existing.consumption_unit_hash;
        v_result := 'zero_charge';
        v_eligibility := 'eligible';
        select l.id into v_ledger_id
        from public.packet_credit_ledger l
        where l.consumption_unit_hash = v_unit_hash
        order by l.created_at
        limit 1;
      end if;
    else
      -- Requirement 6: the unit is the item and the matter. Not the job.
      v_unit_hash := encode(extensions.digest(convert_to(
        'consumer_payment:'
          || coalesce(v_job.consumer_briefcase_item_id, v_job.briefcase_item_id)::text
          || ':' || coalesce(v_auth.provider_event_id, '')
          || ':' || v_job.matter_id::text,
        'utf8'), 'sha256'), 'hex');

      select * into v_existing
      from public.consumer_packet_payment_consumption
      where consumer_briefcase_item_id = coalesce(v_job.consumer_briefcase_item_id, v_job.briefcase_item_id);

      if found then
        if v_existing.matter_id = v_job.matter_id then
          -- Requirement 7: same item, same matter. Idempotent; the original
          -- consumption stands and no second ledger row is written.
          v_unit_hash := v_existing.consumption_unit_hash;
          v_result := 'zero_charge';
          v_eligibility := 'eligible';
          select l.id into v_ledger_id
          from public.packet_credit_ledger l
          where l.consumption_unit_hash = v_unit_hash
          order by l.created_at
          limit 1;
        else
          -- Requirement 8: same item, different matter. This is G11, and it is
          -- now a typed blocked result rather than a second free packet.
          v_result := 'consumer_payment_matter_conflict';
          v_eligibility := 'accounting_blocked';
        end if;
      else
        -- Requirement 9: the insert races. A lost race is a typed result, never
        -- a raw 23505 escaping to the worker and never a stranded job.
        begin
          insert into public.consumer_packet_payment_consumption (
            consumer_briefcase_item_id, consumer_auth_user_id, provider_event_id,
            person_id, matter_id, first_render_job_id, consumption_unit_hash
          ) values (
            coalesce(v_job.consumer_briefcase_item_id, v_job.briefcase_item_id),
            v_job.consumer_auth_user_id,
            v_auth.provider_event_id,
            v_job.person_id, v_job.matter_id, v_job.id, v_unit_hash
          );

          insert into public.packet_credit_ledger (
            entitlement_id, partner_id, person_id, matter_id, render_job_id,
            event_type, consumption_unit_hash, metadata
          ) values (
            null, null, v_job.person_id, v_job.matter_id, v_job.id,
            'zero_charge', v_unit_hash,
            jsonb_build_object('reason', 'consumer_payment_verified')
          ) returning id into v_ledger_id;

          v_result := 'zero_charge';
          v_eligibility := 'eligible';
        exception when unique_violation then
          select * into v_existing
          from public.consumer_packet_payment_consumption
          where consumer_briefcase_item_id = coalesce(v_job.consumer_briefcase_item_id, v_job.briefcase_item_id);

          if found and v_existing.matter_id = v_job.matter_id then
            v_unit_hash := v_existing.consumption_unit_hash;
            v_result := 'zero_charge';
            v_eligibility := 'eligible';
            select l.id into v_ledger_id
            from public.packet_credit_ledger l
            where l.consumption_unit_hash = v_unit_hash
            order by l.created_at
            limit 1;
          elsif found then
            v_result := 'consumer_payment_matter_conflict';
            v_eligibility := 'accounting_blocked';
          else
            v_result := 'consumer_payment_conflict';
            v_eligibility := 'accounting_blocked';
          end if;
        end;
      end if;
    end if;
  else
    select * into v_entitlement
    from public.partner_packet_entitlement e
    where e.partner_id = v_job.partner_id
      and e.effective_at <= now()
      and (e.expires_at is null or e.expires_at > now())
    order by e.effective_at desc
    limit 1
    for update;

    if not found then
      v_result := 'unauthorized';
      v_eligibility := 'accounting_blocked';
    else
      v_unit_hash := encode(extensions.digest(convert_to(
        v_entitlement.partner_id::text || ':' || v_entitlement.id::text || ':'
          || v_job.person_id::text || ':' || v_job.matter_id::text,
        'utf8'), 'sha256'), 'hex');

      if exists (
        select 1 from public.packet_credit_ledger l
        where l.consumption_unit_hash = v_unit_hash
          and l.event_type in ('consumed', 'overage_consumed')
      ) then
        v_result := 'already_consumed';
        v_eligibility := 'eligible';
      else
        select count(*) filter (where l.event_type = 'consumed'),
               count(*) filter (where l.event_type = 'overage_consumed')
        into v_used, v_overage_used
        from public.packet_credit_ledger l
        where l.entitlement_id = v_entitlement.id;

        -- Outstanding Clinic reservations cannot be consumed by another job.
        v_used := v_used + (select count(*) from public.clinic_packet_funding f
          where f.packet_entitlement_id=v_entitlement.id and f.funding_mode='sponsored'
            and public.consumer_matter_id_for_briefcase_item(f.briefcase_item_id) is distinct from v_job.matter_id
            and not exists(select 1 from public.packet_credit_ledger l
              where l.entitlement_id=v_entitlement.id
                and l.matter_id=public.consumer_matter_id_for_briefcase_item(f.briefcase_item_id)
                and l.event_type in ('consumed','overage_consumed')));
        if v_used < v_entitlement.packet_cap then
          v_event_type := 'consumed';
        elsif v_entitlement.overage_enabled and v_overage_used < v_entitlement.overage_cap then
          v_event_type := 'overage_consumed';
        else
          v_event_type := null;
        end if;

        if v_event_type is null then
          v_result := 'cap_reached';
          v_eligibility := 'accounting_blocked';
        else
          insert into public.packet_credit_ledger (
            entitlement_id, partner_id, person_id, matter_id, render_job_id,
            event_type, consumption_unit_hash, metadata
          ) values (
            v_entitlement.id, v_entitlement.partner_id, v_job.person_id, v_job.matter_id, v_job.id,
            v_event_type, v_unit_hash,
            jsonb_build_object('packet_id', v_job.packet_id, 'route_id', v_job.route_id, 'entitlement_scope', v_entitlement.entitlement_scope)
          ) returning id into v_ledger_id;
          v_result := case when v_event_type = 'consumed' then 'consumed' else 'overage_consumed' end;
          v_eligibility := 'eligible';
        end if;
      end if;
    end if;
  end if;

  update public.packet_render_jobs
  set accounting_result = v_result,
      delivery_eligibility = v_eligibility,
      credit_ledger_id = v_ledger_id,
      fencing_token = null,
      claim_expires_at = null
  where id = p_job_id;

  perform set_config('rcap.packet_mutation_authority', '', true);
  return query select v_result, v_eligibility, v_unit_hash, v_ledger_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.guard_packet_delivery_events()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    if public.rcap_packet_mutation_authority() <> 'record_packet_delivery_event' then
      raise exception 'packet_delivery_events: events are recorded only by record_packet_delivery_event';
    end if;
    return new;
  end if;
  raise exception 'packet_delivery_events: append-only; % is never permitted', tg_op;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_consumer_packet_payment(p_briefcase_item_id uuid, p_payment_status text, p_amount_cents integer, p_regular_price_cents integer, p_discount_cents integer, p_currency text, p_payment_provider text, p_provider_event_id text, p_checkout_session_id text, p_payment_intent_id text, p_receipt_url text, p_authority text, p_recorded_by text, p_product_id text, p_person_id uuid, p_matter_id uuid)
 RETURNS TABLE(outcome text, briefcase_item_id uuid, provider_event_id text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_found boolean;
  v_owner uuid;
  v_status text;
  v_existing_event text;
  v_existing_session text;
  v_existing_product text;
  v_existing_person uuid;
  v_existing_matter uuid;
  v_existing_amount integer;
  v_existing_currency text;
  v_payment_allowed boolean;
  v_source_session_id text;
  v_item_type text;
  v_jurisdiction text;
  v_pathway_label text;
  v_result_code text;
  v_packet_type text;
  v_item_status text;
  v_sponsored boolean := false;
  v_expected_match_key text;
  v_amount_due integer;
begin
  if to_regclass('public.consumer_briefcase_items') is null then
    return query select 'no_payment_storage'::text, p_briefcase_item_id, null::text;
    return;
  end if;
  if p_briefcase_item_id is null then
    return query select 'invalid_item'::text, null::uuid, null::text;
    return;
  end if;
  if coalesce(p_authority, '') not in ('server_webhook', 'server_admin') then
    return query select 'invalid_authority'::text, p_briefcase_item_id, null::text;
    return;
  end if;

  execute
    'select true, b.user_id, b.payment_status, b.provider_event_id,
            b.checkout_session_id, b.payment_product_id, b.payment_person_id,
            b.payment_matter_id, b.amount_cents, b.currency,
            b.payment_allowed, b.source_session_id, b.item_type,
            b.jurisdiction, b.pathway_label, b.result_code,
            b.packet_type, b.status
       from public.consumer_briefcase_items b
      where b.id = $1 for update'
  into v_found, v_owner, v_status, v_existing_event, v_existing_session,
       v_existing_product, v_existing_person, v_existing_matter,
       v_existing_amount, v_existing_currency, v_payment_allowed,
       v_source_session_id, v_item_type, v_jurisdiction,
       v_pathway_label, v_result_code, v_packet_type, v_item_status
  using p_briefcase_item_id;

  if not coalesce(v_found, false) then
    return query select 'item_not_found'::text, p_briefcase_item_id, null::text;
    return;
  end if;

  if p_payment_status = 'paid' then
    if v_payment_allowed is not true then
      return query select 'payment_not_allowed'::text, p_briefcase_item_id, null::text;
      return;
    end if;

    if v_item_type not in ('result', 'packet')
       or nullif(trim(coalesce(v_jurisdiction, '')), '') is null
       or nullif(trim(coalesce(v_pathway_label, '')), '') is null
       or v_result_code not in ('packet_ready', 'packet_ready_with_caution')
       or v_packet_type not in ('official_pdf_overlay', 'custom_pleading', 'legacy_packet')
       or v_item_status is distinct from 'packet_ready' then
      return query select 'invalid_item'::text, p_briefcase_item_id, null::text;
      return;
    end if;

    if to_regclass('public.screening_sessions') is not null
       and exists (
         select 1
           from information_schema.columns c
          where c.table_schema = 'public'
            and c.table_name = 'screening_sessions'
            and c.column_name in ('session_id', 'flow_mode', 'partner_slug', 'partner_benefit_active')
          group by c.table_schema, c.table_name
         having count(*) = 4
       ) then
      execute
        'select exists (
           select 1 from public.screening_sessions s
            where s.session_id::text = nullif(trim($1), '''')
              and s.flow_mode = ''rcap''
              and nullif(trim(coalesce(s.partner_slug, '''')), '''') is not null
              and s.partner_benefit_active is true
         )'
      into v_sponsored
      using v_source_session_id;
    end if;

    if (coalesce(v_sponsored, false) or exists (
      select 1 from public.consumer_briefcase_items i
      join public.consumer_pending_screening_results s on s.pending_id=i.source_pending_result_id
      where i.id=p_briefcase_item_id and s.product='rcap_partner'
    )) and not public.clinic_packet_dtc_authorized(p_briefcase_item_id,v_owner) then
      return query select 'sponsored_item'::text, p_briefcase_item_id, null::text;
      return;
    end if;

    -- The reconciliation, in the database, where it holds even if the
    -- application is wrong. This is what replaces `p_amount_cents <> 5000`.
    v_amount_due := coalesce(p_regular_price_cents, -1) - coalesce(p_discount_cents, -1);
    if p_regular_price_cents is distinct from 5000
       or p_discount_cents is null
       or p_discount_cents < 0
       or p_discount_cents > p_regular_price_cents
       or p_amount_cents is distinct from v_amount_due
       or lower(coalesce(p_currency, '')) <> 'usd'
       or nullif(trim(coalesce(p_provider_event_id, '')), '') is null
       or nullif(trim(coalesce(p_checkout_session_id, '')), '') is null
       or p_product_id is distinct from 'expungement_packet'
       or p_person_id is null
       or p_matter_id is distinct from public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id) then
      return query select 'invalid_payment_evidence'::text, p_briefcase_item_id, null::text;
      return;
    end if;

    -- Stripe creates no PaymentIntent for a zero-total order and always creates
    -- one when money is due. A row that disagrees with its own total is not a
    -- description of any order Stripe produced.
    if (v_amount_due > 0) <> (nullif(trim(coalesce(p_payment_intent_id, '')), '') is not null) then
      return query select 'invalid_payment_evidence'::text, p_briefcase_item_id, null::text;
      return;
    end if;

    v_expected_match_key := 'consumer:' || encode(
      extensions.digest(convert_to('rcap:consumer-person:v1:' || v_owner::text, 'utf8'), 'sha256'),
      'hex'
    );
    if not exists (
      select 1 from public.rcap_persons p
       where p.id = p_person_id
         and p.partner_slug = 'expungement-ai-consumer'
         and p.match_key = v_expected_match_key
    ) then
      return query select 'invalid_payment_identity'::text, p_briefcase_item_id, null::text;
      return;
    end if;

    if v_existing_session is distinct from p_checkout_session_id
       or v_existing_product is distinct from p_product_id
       or v_existing_person is distinct from p_person_id
       or v_existing_matter is distinct from p_matter_id then
      return query select 'checkout_binding_mismatch'::text, p_briefcase_item_id, null::text;
      return;
    end if;

    -- A second signed event for the same already-settled Session is an
    -- idempotent success. The stored amount is compared against what this event
    -- reconciles to rather than against 5000, so a replayed no-cost order
    -- converges instead of reading as a conflict.
    if v_status = 'paid' then
      if v_existing_amount is not distinct from p_amount_cents
         and lower(coalesce(v_existing_currency, '')) = 'usd'
         and nullif(trim(coalesce(v_existing_event, '')), '') is not null then
        return query select 'already_paid'::text, p_briefcase_item_id, v_existing_event;
        return;
      end if;
      return query select 'payment_conflict'::text, p_briefcase_item_id, v_existing_event;
      return;
    end if;

    begin
      execute
        'update public.consumer_briefcase_items
            set payment_status = ''paid'', amount_cents = $11,
                regular_price_cents = $12, discount_cents = $13, currency = ''usd'',
                payment_provider = coalesce($2, payment_provider),
                payment_intent_id = coalesce($3, payment_intent_id),
                receipt_url = coalesce($4, receipt_url), provider_event_id = $5,
                payment_authority = $6, payment_recorded_at = now(),
                payment_recorded_by = $7, payment_product_id = $8,
                payment_person_id = $9, payment_matter_id = $10
          where id = $1'
      using p_briefcase_item_id, p_payment_provider, p_payment_intent_id,
            p_receipt_url, trim(p_provider_event_id), p_authority, p_recorded_by,
            p_product_id, p_person_id, p_matter_id,
            p_amount_cents, p_regular_price_cents, p_discount_cents;
    exception when unique_violation then
      return query select 'duplicate_provider_event'::text, p_briefcase_item_id, trim(p_provider_event_id);
      return;
    end;

    return query select 'recorded_paid'::text, p_briefcase_item_id, trim(p_provider_event_id);
    return;
  end if;

  if p_payment_status not in ('not_applicable', 'unpaid', 'refunded') then
    return query select 'invalid_status'::text, p_briefcase_item_id, null::text;
    return;
  end if;

  execute
    'update public.consumer_briefcase_items
        set payment_status = $2, payment_authority = $3,
            payment_recorded_at = now(), payment_recorded_by = $4
      where id = $1'
  using p_briefcase_item_id, p_payment_status, p_authority, p_recorded_by;

  return query select ('recorded_' || p_payment_status)::text, p_briefcase_item_id, v_existing_event;
end;
$function$;

CREATE OR REPLACE FUNCTION public.replace_consumer_checkout_session(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid, p_expected_checkout_session_id text, p_checkout_session_id text, p_payment_provider text, p_product_id text, p_person_id uuid, p_matter_id uuid, p_expected_verification_hash text)
 RETURNS TABLE(ok boolean, reason text, briefcase_item_id uuid, checkout_session_id text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item public.consumer_briefcase_items%rowtype;
  v_hash text;
begin
  if nullif(trim(coalesce(p_expected_checkout_session_id, '')), '') is null
     or nullif(trim(coalesce(p_checkout_session_id, '')), '') is null
     or p_expected_checkout_session_id = p_checkout_session_id then
    return query select false, 'checkout_replacement_invalid'::text, p_briefcase_item_id, null::text; return;
  end if;

  -- Same lock order as the verification and payment authorities: item first.
  select * into v_item from public.consumer_briefcase_items i
    where i.id = p_briefcase_item_id for update;
  if not found or p_consumer_auth_user_id is null
     or v_item.user_id is distinct from p_consumer_auth_user_id then
    return query select false, 'item_not_found'::text, null::uuid, null::text; return;
  end if;

  if v_item.payment_status = 'paid' then
    return query select false, 'already_paid'::text, p_briefcase_item_id, v_item.checkout_session_id; return;
  end if;
  -- Refunded/unknown states are not unpaid. Zero-dollar completed orders and
  -- partial server evidence remain protected even before payment_status catches up.
  if v_item.payment_status is distinct from 'unpaid'
     or v_item.packet_status is distinct from 'not_started'
     or v_item.provider_event_id is not null
     or v_item.payment_intent_id is not null
     or v_item.payment_authority is not null
     or v_item.payment_recorded_at is not null
     or v_item.payment_recorded_by is not null
     or v_item.receipt_url is not null
     or v_item.amount_cents is not null
     or exists (select 1 from public.consumer_packet_payment_consumption c
       where c.consumer_briefcase_item_id = p_briefcase_item_id)
     or exists (select 1 from public.packet_render_jobs j
       where j.briefcase_item_id = p_briefcase_item_id)
     or exists (select 1 from public.processed_stripe_events e
       where e.related_object_id in (v_item.checkout_session_id, p_checkout_session_id)) then
    return query select false, 'checkout_payment_evidence_present'::text, p_briefcase_item_id, v_item.checkout_session_id; return;
  end if;

  select v.verification_hash into v_hash from public.consumer_packet_verifications v
    where v.briefcase_item_id = p_briefcase_item_id and v.status = 'verified' for update;
  if v_hash is null or p_expected_verification_hash is null
     or p_expected_verification_hash !~ '^[0-9a-f]{64}$'
     or v_hash is distinct from p_expected_verification_hash then
    return query select false, 'verification_changed'::text, p_briefcase_item_id, null::text; return;
  end if;

  -- A replacement changes only the Session, never who/what the order belongs to.
  if v_item.payment_allowed is not true
     or p_product_id is distinct from public.expungement_packet_product_id()
     or v_item.payment_product_id is distinct from p_product_id
     or p_person_id is null or v_item.payment_person_id is distinct from p_person_id
     or p_matter_id is distinct from public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id)
     or v_item.payment_matter_id is distinct from p_matter_id
     or p_payment_provider is distinct from 'stripe'
     or v_item.payment_provider is distinct from p_payment_provider then
    return query select false, 'checkout_binding_invalid'::text, p_briefcase_item_id, null::text; return;
  end if;

  if exists (select 1 from public.consumer_briefcase_items i
    where i.checkout_session_id = p_checkout_session_id and i.id <> p_briefcase_item_id) then
    return query select false, 'checkout_session_in_use'::text, p_briefcase_item_id, null::text; return;
  end if;
  if v_item.checkout_session_id is distinct from p_expected_checkout_session_id then
    return query select false, 'checkout_replacement_conflict'::text, p_briefcase_item_id, v_item.checkout_session_id; return;
  end if;

  -- Never clear or rewrite payment evidence, including when it is NULL today.
  update public.consumer_briefcase_items i set
    checkout_session_id = p_checkout_session_id, updated_at = now()
    where i.id = p_briefcase_item_id and i.checkout_session_id = p_expected_checkout_session_id;
  return query select true, 'replaced'::text, p_briefcase_item_id, p_checkout_session_id;
exception when unique_violation then
  -- Another item won the unique Session claim after the pre-check. PostgreSQL
  -- rolls this block back, preserving this item's predecessor and all evidence.
  return query select false, 'checkout_session_in_use'::text, p_briefcase_item_id, null::text;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sponsored_packet_render_authority(p_route_key text, p_session_id uuid, p_briefcase_item_id uuid, p_consumer_auth_user_id uuid)
 RETURNS TABLE(valid boolean, reason text, partner_slug text, partner_id uuid, clinic_event_id uuid, clinic_case_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_route public.sponsored_packet_render_routes%rowtype;
  v_item public.consumer_briefcase_items%rowtype;
  v_source public.consumer_pending_screening_results%rowtype;
  v_session public.screening_sessions%rowtype;
  v_case public.clinic_cases%rowtype;
  v_event public.clinic_events%rowtype;
  v_partner_id uuid;
begin
  if p_route_key is null or p_session_id is null
     or p_briefcase_item_id is null or p_consumer_auth_user_id is null then
    return query select false, 'invalid_input'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;

  select * into v_route from public.sponsored_packet_render_routes r
   where r.route_key = p_route_key and r.active;
  if not found then
    return query select false, 'route_not_registered'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;

  select * into v_item from public.consumer_briefcase_items i
   where i.id = p_briefcase_item_id and i.user_id = p_consumer_auth_user_id;
  if not found then
    return query select false, 'wrong_owner'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;
  if v_item.jurisdiction is distinct from v_route.jurisdiction then
    return query select false, 'wrong_jurisdiction_or_route'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;

  select * into v_source from public.consumer_pending_screening_results p
   where p.pending_id = v_item.source_pending_result_id;
  if not found or v_source.status <> 'CLAIMED'
     or v_source.claimed_matter_id is distinct from v_item.id
     or v_source.claimed_user_id is distinct from v_item.user_id then
    return query select false, 'wrong_item'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;
  if v_source.anonymous_session_id is distinct from p_session_id then
    return query select false, 'wrong_session'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;
  if v_source.product <> 'rcap_partner'
     or v_source.partner_slug is distinct from v_route.partner_slug then
    return query select false, 'wrong_partner'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;
  if v_source.jurisdiction is distinct from v_route.jurisdiction then
    return query select false, 'wrong_jurisdiction_or_route'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;

  select * into v_session from public.screening_sessions s where s.session_id = p_session_id;
  if not found or v_session.flow_mode <> 'rcap' or v_session.partner_benefit_active is not true then
    return query select false, 'sponsorship_inactive'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;
  if v_session.partner_slug is distinct from v_route.partner_slug then
    return query select false, 'wrong_partner'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;
  if v_session.jurisdiction is distinct from v_route.jurisdiction then
    return query select false, 'wrong_jurisdiction_or_route'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;

  select c.* into v_case from public.clinic_cases c
   where c.event_id = v_source.event_id
     and c.participant_user_id = v_item.user_id
     and c.screening_session_id = p_session_id
     and c.matter_id = v_item.id;
  if not found then
    return query select false, 'clinic_scope_mismatch'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;
  if v_case.jurisdiction is distinct from v_route.jurisdiction or v_case.route_disposition <> 'packet' then
    return query select false, 'wrong_jurisdiction_or_route'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;

  select * into v_event from public.clinic_events e where e.id = v_case.event_id;
  if not found
     or v_event.partner_slug is distinct from v_route.partner_slug
     or v_event.program_key is distinct from v_route.program_key
     or (v_route.clinic_event_name is not null and v_event.name is distinct from v_route.clinic_event_name) then
    return query select false, 'clinic_scope_mismatch'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;
  if v_event.jurisdiction is distinct from v_route.jurisdiction then
    return query select false, 'wrong_jurisdiction_or_route'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;
  if v_event.status <> 'published'
     or v_event.sponsorship_allocation is null or v_event.sponsorship_allocation < 0 then
    return query select false, 'sponsorship_inactive'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;

  select pr.id into v_partner_id from public.partner_records pr
   where pr.partner_slug = v_route.partner_slug;
  if v_partner_id is null then
    return query select false, 'no_entitlement'::text, null::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;

  return query select true, null::text, v_route.partner_slug, v_partner_id, v_event.id, v_case.id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.guard_packet_render_job_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_authority text := public.rcap_packet_mutation_authority();
begin
  if new.status <> old.status then
    if not (
      (old.status = 'queued' and new.status in ('claimed', 'failed'))
      or (old.status = 'claimed' and new.status in ('rendering', 'failed', 'queued'))
      or (old.status = 'rendering' and new.status in ('validating', 'failed'))
      or (old.status = 'validating' and new.status in ('artifact_validated', 'failed'))
      or (old.status = 'artifact_validated' and new.status = 'delivered')
      or (old.status = 'failed' and new.status = 'queued')
    ) then
      raise exception 'packet_render_jobs: illegal transition % -> %', old.status, new.status;
    end if;

    if old.status = 'queued' and new.status = 'claimed'
       and v_authority <> 'claim_packet_render_job' then
      raise exception 'packet_render_jobs: claiming requires claim_packet_render_job';
    end if;

    if new.status = 'artifact_validated'
       and v_authority <> 'finalize_packet_render_job' then
      raise exception 'packet_render_jobs: artifact_validated is written only by finalize_packet_render_job';
    end if;

    if new.status = 'delivered'
       and v_authority <> 'record_packet_delivery_event' then
      raise exception 'packet_render_jobs: delivered is written only by record_packet_delivery_event';
    end if;

    if old.status = 'failed' and new.status = 'queued' then
      if v_authority not in ('requeue_retryable_packet_render_jobs', 'requeue_packet_render_job_manual') then
        raise exception 'packet_render_jobs: failed jobs return to queued only through a requeue function';
      end if;
      if old.failure_disposition = 'terminal'
         and v_authority <> 'requeue_packet_render_job_manual' then
        raise exception 'packet_render_jobs: a terminal failure is requeued only manually with recorded authorization';
      end if;
    end if;

    if new.status in ('rendering', 'validating')
       and v_authority not in ('start_packet_render', 'start_packet_validation') then
      raise exception 'packet_render_jobs: worker transitions require their canonical functions';
    end if;

    if new.status = 'failed'
       and v_authority not in ('fail_packet_render_job', 'release_expired_packet_render_claims', 'finalize_packet_render_job') then
      raise exception 'packet_render_jobs: failure is recorded only through its canonical functions';
    end if;

    -- Per-state timestamps, carried over from the phase-49 guard.
    new.claimed_at            := case when new.status = 'claimed'            then now() else new.claimed_at end;
    new.rendering_at          := case when new.status = 'rendering'          then now() else new.rendering_at end;
    new.validating_at         := case when new.status = 'validating'         then now() else new.validating_at end;
    new.artifact_validated_at := case when new.status = 'artifact_validated' then now() else new.artifact_validated_at end;
    new.delivered_at          := case when new.status = 'delivered'          then now() else new.delivered_at end;

    if new.status = 'queued' then
      new.claimed_by := null;
      new.claimed_at := null;
    end if;
  end if;

  if (new.delivery_eligibility is distinct from old.delivery_eligibility
      or new.accounting_result is distinct from old.accounting_result
      or new.credit_ledger_id is distinct from old.credit_ledger_id)
     and v_authority <> 'finalize_packet_render_job' then
    raise exception 'packet_render_jobs: accounting fields are written only by finalize_packet_render_job';
  end if;

  if (new.output_storage_path is distinct from old.output_storage_path
      or new.output_sha256 is distinct from old.output_sha256
      or new.normalized_output_sha256 is distinct from old.normalized_output_sha256
      or new.container_digest is distinct from old.container_digest)
     and v_authority <> 'finalize_packet_render_job' then
    raise exception 'packet_render_jobs: artifact evidence is written only by finalize_packet_render_job';
  end if;

  if old.partner_id is not null and new.partner_id is distinct from old.partner_id then
    raise exception 'packet_render_jobs: partner_id is immutable';
  end if;
  if old.person_id is not null and new.person_id is distinct from old.person_id then
    raise exception 'packet_render_jobs: person_id is immutable';
  end if;
  if old.matter_id is not null and new.matter_id is distinct from old.matter_id then
    raise exception 'packet_render_jobs: matter_id is immutable';
  end if;

  new.updated_at := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.release_expired_packet_render_claims()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count integer;
begin
  perform set_config('rcap.packet_mutation_authority', 'release_expired_packet_render_claims', true);
  update public.packet_render_jobs j
  set retry_reconciliation_history = j.retry_reconciliation_history || jsonb_build_array(jsonb_build_object(
        'authority', 'release_expired_packet_render_claims', 'at', now(),
        'reason', case when j.attempt_count >= j.max_attempts then 'attempt_limit_reached' else 'lease_expired' end,
        'prior_status', j.status, 'prior_failure_disposition', j.failure_disposition,
        'prior_error_code', j.error_code, 'attempt_count', j.attempt_count,
        'max_attempts', j.max_attempts, 'next_attempt_at', j.next_attempt_at,
        'claim_expires_at', j.claim_expires_at, 'claimed_by', j.claimed_by, 'claimed_at', j.claimed_at)),
      status = case when j.status = 'claimed' and j.attempt_count < j.max_attempts then 'queued' else 'failed' end,
      failure_disposition = case
        when j.status = 'claimed' and j.attempt_count < j.max_attempts then null
        when j.attempt_count < j.max_attempts then 'retryable' else 'terminal' end,
      error_code = case when j.status = 'claimed' and j.attempt_count < j.max_attempts then j.error_code
                        else coalesce(j.error_code, 'timeout') end,
      last_error_detail = coalesce(j.last_error_detail,
        case when j.attempt_count >= j.max_attempts then 'attempt limit reached during lease housekeeping'
             else 'claim lease expired before the worker finished' end),
      next_attempt_at = case
        when j.attempt_count >= j.max_attempts then null
        when j.status = 'claimed' then j.next_attempt_at
        else now() + make_interval(secs => least(3600, 30 * power(2, j.attempt_count))::integer) end,
      claim_expires_at = null,
      fencing_token = null
  where (j.status in ('claimed', 'rendering', 'validating')
         and j.claim_expires_at is not null and j.claim_expires_at < now())
     or (j.status = 'queued' and j.attempt_count >= j.max_attempts);
  get diagnostics v_count = row_count;
  perform set_config('rcap.packet_mutation_authority', '', true);
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.requeue_retryable_packet_render_jobs()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_key record;
  v_job public.packet_render_jobs%rowtype;
  v_winner uuid;
  v_live uuid;
  v_reason text;
  v_constraint text;
  v_sqlstate text;
  v_schema text;
  v_table text;
  v_count integer := 0;
begin
  perform set_config('rcap.packet_mutation_authority', 'requeue_retryable_packet_render_jobs', true);
  for v_key in
    select distinct packet_id, input_hash from public.packet_render_jobs
    where status = 'failed' and failure_disposition = 'retryable'
    order by packet_id, input_hash
  loop
    -- Housekeepers serialize by logical input, not the whole queue. A busy input
    -- does not block unrelated inputs. The unique index also arbitrates enqueue.
    if not pg_try_advisory_xact_lock(hashtextextended(v_key.packet_id::text || ':' || v_key.input_hash, 0)) then
      continue;
    end if;
    select id into v_live from public.packet_render_jobs
    where packet_id = v_key.packet_id and input_hash = v_key.input_hash and status <> 'failed';
    select id into v_winner from public.packet_render_jobs
    where packet_id = v_key.packet_id and input_hash = v_key.input_hash
      and status = 'failed' and failure_disposition = 'retryable' and attempt_count < max_attempts
      and next_attempt_at is not null and isfinite(next_attempt_at)
    order by created_at, id limit 1;

    for v_job in
      select * from public.packet_render_jobs
      where packet_id = v_key.packet_id and input_hash = v_key.input_hash
        and status = 'failed' and failure_disposition = 'retryable'
      order by created_at, id for update
    loop
      v_sqlstate := null;
      v_constraint := null;
      v_reason := case
        when v_job.attempt_count >= v_job.max_attempts then 'attempt_limit_reached'
        when v_live is not null then 'live_sibling_exists'
        when v_job.next_attempt_at is null or not isfinite(v_job.next_attempt_at) then 'canonical_retry_time_missing'
        when v_job.id is distinct from v_winner then 'duplicate_retry_superseded'
        else null end;
      if v_reason is null and v_job.next_attempt_at <= now() then
        begin
          update public.packet_render_jobs j
          set status = 'queued', failure_disposition = null,
              retry_reconciliation_history = j.retry_reconciliation_history || jsonb_build_array(jsonb_build_object(
                'authority', 'requeue_retryable_packet_render_jobs', 'at', now(), 'reason', 'canonical_retry_due',
                'prior_status', j.status, 'prior_failure_disposition', j.failure_disposition,
                'prior_error_code', j.error_code, 'attempt_count', j.attempt_count,
                'max_attempts', j.max_attempts, 'next_attempt_at', j.next_attempt_at,
                'claimed_by', j.claimed_by, 'claimed_at', j.claimed_at))
          where j.id = v_job.id;
          v_count := v_count + 1;
          v_live := v_job.id;
        exception when unique_violation then
          get stacked diagnostics v_constraint = constraint_name, v_sqlstate = returned_sqlstate,
            v_schema = schema_name, v_table = table_name;
          if v_sqlstate = '23505' and v_constraint = 'packet_render_jobs_input_hash_live_unique'
             and v_schema = 'public' and v_table = 'packet_render_jobs' then
            -- A concurrent enqueue won. Only this row's attempted requeue is
            -- rolled back; other logical inputs still make progress.
            select id into v_live from public.packet_render_jobs
            where packet_id = v_key.packet_id and input_hash = v_key.input_hash and status <> 'failed';
            if v_live is null then raise; end if;
            v_reason := 'concurrent_live_sibling_won';
          else
            -- A trigger or another relation's constraint is not this race.
            raise;
          end if;
        end;
      end if;
      if v_reason is not null then
        update public.packet_render_jobs j
        set failure_disposition = 'terminal', next_attempt_at = null,
            retry_reconciliation_history = j.retry_reconciliation_history || jsonb_build_array(jsonb_build_object(
              'authority', 'requeue_retryable_packet_render_jobs', 'at', now(), 'reason', v_reason,
              'canonical_job_id', coalesce(v_live, v_winner),
              'requeue_sqlstate', v_sqlstate, 'requeue_constraint', v_constraint,
              'prior_status', j.status, 'prior_failure_disposition', j.failure_disposition,
              'prior_error_code', j.error_code, 'attempt_count', j.attempt_count,
              'max_attempts', j.max_attempts, 'next_attempt_at', j.next_attempt_at,
                'claimed_by', j.claimed_by, 'claimed_at', j.claimed_at))
        where j.id = v_job.id;
      end if;
    end loop;
  end loop;
  perform set_config('rcap.packet_mutation_authority', '', true);
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.guard_packet_render_job_retry_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.retry_reconciliation_history is distinct from old.retry_reconciliation_history then
    if public.rcap_packet_mutation_authority() not in (
      'release_expired_packet_render_claims', 'requeue_retryable_packet_render_jobs'
    ) or jsonb_array_length(new.retry_reconciliation_history) <> jsonb_array_length(old.retry_reconciliation_history) + 1
      or new.retry_reconciliation_history - (jsonb_array_length(new.retry_reconciliation_history) - 1) <> old.retry_reconciliation_history then
      raise exception 'packet_render_jobs: retry history is appended only by canonical housekeeping';
    end if;
  end if;
  return new;
end;
$function$;

revoke all on function public.guard_packet_render_job_retry_history() from public, anon, authenticated, service_role, rcap_render_worker, rcap_packet_delivery;

CREATE OR REPLACE FUNCTION public.enqueue_verified_sponsored_packet_render(p_route_key text, p_session_id uuid, p_packet_id uuid, p_route_id text, p_renderer_kind text, p_renderer_version text, p_source_sha256 text, p_profile_id text, p_profile_version text, p_input_hash text, p_briefcase_item_id uuid, p_person_id uuid, p_matter_id uuid, p_max_attempts integer, p_expected_consumer_auth_user_id uuid, p_expected_verification_hash text, p_render_packet jsonb, p_render_input_payload jsonb)
 RETURNS SETOF packet_render_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_route public.sponsored_packet_render_routes%rowtype;
  v_authority record;
  v_hash text;
  v_job public.packet_render_jobs%rowtype;
  v_existing_payload jsonb;
begin
  select * into v_route from public.sponsored_packet_render_routes r
   where r.route_key = p_route_key and r.active;
  if not found then
    raise exception 'sponsored render route is not registered';
  end if;

  -- The render input is the participant's document. Every identity inside it
  -- must equal the registration and the caller's claimed binding, or nothing
  -- is created.
  if p_render_packet ->> 'id' is distinct from p_packet_id::text
     or p_render_packet ->> 'user_id' is distinct from p_expected_consumer_auth_user_id::text
     or p_render_packet ->> 'briefcase_id' is distinct from p_briefcase_item_id::text
     or p_render_packet ->> 'person_id' is distinct from p_person_id::text
     or p_render_input_payload ->> 'authUserId' is distinct from p_expected_consumer_auth_user_id::text
     or p_render_input_payload ->> 'briefcaseItemId' is distinct from p_briefcase_item_id::text
     or p_render_input_payload ->> 'matterId' is distinct from p_matter_id::text
     or p_render_input_payload ->> 'verificationHash' is distinct from p_expected_verification_hash
     or p_render_input_payload ->> 'inputHash' is distinct from p_input_hash then
    raise exception 'sponsored render payload binding mismatch';
  end if;
  if trim(coalesce(p_route_id, '')) is distinct from v_route.route_key
     or p_render_input_payload ->> 'routeId' is distinct from v_route.route_key
     or p_render_input_payload ->> 'packetFamilyId' is distinct from v_route.packet_family_id
     or p_render_input_payload ->> 'specificationId' is distinct from v_route.packet_specification_id
     or p_render_input_payload ->> 'specificationVersion' is distinct from v_route.packet_specification_version
     or p_render_input_payload ->> 'specificationSha256' is distinct from v_route.packet_specification_sha256
     or (v_route.registry_track_id is not null
         and p_render_input_payload ->> 'trackId' is distinct from v_route.registry_track_id)
     or p_render_input_payload -> 'snapshot' ->> 'jurisdiction' is distinct from v_route.jurisdiction
     or p_render_input_payload -> 'snapshot' ->> 'pathwayId' is distinct from v_route.pathway_id
     or (v_route.registry_track_id is not null
         and p_render_input_payload -> 'snapshot' ->> 'selectedTrackId' is distinct from v_route.registry_track_id) then
    raise exception 'sponsored render route binding mismatch';
  end if;

  select v.verification_hash into v_hash from public.consumer_packet_verifications v
    where v.briefcase_item_id = p_briefcase_item_id
      and v.consumer_auth_user_id = p_expected_consumer_auth_user_id
      and v.status = 'verified' for update;
  if v_hash is null or v_hash is distinct from p_expected_verification_hash then
    raise exception 'sponsored render verification changed';
  end if;

  select * into v_authority from public.sponsored_packet_render_authority(
    p_route_key, p_session_id, p_briefcase_item_id, p_expected_consumer_auth_user_id
  );
  if not coalesce(v_authority.valid, false) then
    raise exception 'sponsored render authority missing: %', coalesce(v_authority.reason, 'unknown');
  end if;
  if p_matter_id is distinct from public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id) then
    raise exception 'sponsored render matter binding mismatch';
  end if;

  if not exists(select 1 from public.allocate_clinic_packet_funding(
    p_briefcase_item_id,p_expected_consumer_auth_user_id,p_expected_verification_hash) f where f.funding_mode='sponsored') then
    raise exception 'sponsor_capacity_requires_dtc';
  end if;

  insert into public.rcap_document_packets (
    id, partner_slug, user_id, briefcase_id, person_id, state, jurisdiction,
    document_type, pathway, status, petitioner_first_name, petitioner_last_name,
    petitioner_city, petitioner_county, court_county, court_name, cause_number,
    charge, offense_date, arrest_date, arresting_agency, agency_case_number,
    disposition_date, conviction_date, sentence_completion_date,
    needs_record_review, generated_plain_text, filing_instructions,
    county_court_instructions, missing_fields, safety_disclaimer
  ) values (
    p_packet_id, 'expungement-ai-consumer', p_expected_consumer_auth_user_id,
    p_briefcase_item_id, p_person_id,
    p_render_packet ->> 'state', p_render_packet ->> 'jurisdiction',
    p_render_packet ->> 'document_type', p_render_packet ->> 'pathway',
    coalesce(p_render_packet ->> 'status', 'ready_for_review'),
    p_render_packet ->> 'petitioner_first_name', p_render_packet ->> 'petitioner_last_name',
    p_render_packet ->> 'petitioner_city', p_render_packet ->> 'petitioner_county',
    p_render_packet ->> 'court_county', p_render_packet ->> 'court_name',
    p_render_packet ->> 'cause_number', p_render_packet ->> 'charge',
    p_render_packet ->> 'offense_date', p_render_packet ->> 'arrest_date',
    p_render_packet ->> 'arresting_agency', p_render_packet ->> 'agency_case_number',
    p_render_packet ->> 'disposition_date', p_render_packet ->> 'conviction_date',
    p_render_packet ->> 'sentence_completion_date',
    coalesce((p_render_packet ->> 'needs_record_review')::boolean, true),
    p_render_packet ->> 'generated_plain_text',
    array(select jsonb_array_elements_text(coalesce(p_render_packet -> 'filing_instructions', '[]'::jsonb))),
    array(select jsonb_array_elements_text(coalesce(p_render_packet -> 'county_court_instructions', '[]'::jsonb))),
    array(select jsonb_array_elements_text(coalesce(p_render_packet -> 'missing_fields', '[]'::jsonb))),
    p_render_packet ->> 'safety_disclaimer'
  ) on conflict (id) do nothing;

  select i.input_payload into v_existing_payload from public.rcap_document_packet_inputs i
    where i.document_packet_id = p_packet_id and i.partner_slug = 'expungement-ai-consumer' for update;
  if found and v_existing_payload is distinct from p_render_input_payload then
    raise exception 'sponsored render input payload is immutable';
  end if;
  if not found then
    insert into public.rcap_document_packet_inputs(document_packet_id, partner_slug, input_payload)
      values (p_packet_id, 'expungement-ai-consumer', p_render_input_payload);
  end if;

  select * into v_job from public.enqueue_packet_render_job(
    p_packet_id, p_route_id, p_renderer_kind, p_renderer_version,
    p_source_sha256, p_profile_id, p_profile_version, p_input_hash,
    p_briefcase_item_id, v_authority.partner_id, p_person_id, p_matter_id,
    p_max_attempts, null, null
  );
  if v_job.id is null then raise exception 'sponsored render enqueue failed'; end if;

  update public.packet_render_jobs j set
    sponsored_route_key = v_route.route_key,
    sponsored_session_id = p_session_id,
    sponsored_clinic_event_id = v_authority.clinic_event_id,
    sponsored_consumer_briefcase_item_id = p_briefcase_item_id,
    sponsored_consumer_auth_user_id = p_expected_consumer_auth_user_id,
    sponsored_verification_hash = p_expected_verification_hash
  where j.id = v_job.id and j.sponsored_route_key is null;

  select * into v_job from public.packet_render_jobs j where j.id = v_job.id;
  if v_job.sponsored_route_key is distinct from v_route.route_key
     or v_job.sponsored_consumer_briefcase_item_id is distinct from p_briefcase_item_id
     or v_job.sponsored_consumer_auth_user_id is distinct from p_expected_consumer_auth_user_id
     or v_job.sponsored_verification_hash is distinct from p_expected_verification_hash
     or v_job.sponsored_session_id is distinct from p_session_id then
    raise exception 'sponsored render job is bound to a different participant or route';
  end if;
  return next v_job;
end;
$function$;

CREATE OR REPLACE FUNCTION public.consumer_payment_consumption_binding_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_valid boolean;
  v_reason text;
  v_session text;
begin
  if tg_op = 'UPDATE' then
    if new.consumer_briefcase_item_id is distinct from old.consumer_briefcase_item_id
       or new.consumer_auth_user_id is distinct from old.consumer_auth_user_id
       or new.provider_event_id is distinct from old.provider_event_id
       or new.person_id is distinct from old.person_id
       or new.matter_id is distinct from old.matter_id
       or new.product_id is distinct from old.product_id
       or new.checkout_session_id is distinct from old.checkout_session_id
       or new.amount_cents is distinct from old.amount_cents
       or new.currency is distinct from old.currency then
      raise exception 'consumer payment consumption binding is immutable';
    end if;
    -- A refund removes authority for new work, but Phase 52 deliberately keeps
    -- an already-delivered artifact and its consumption evidence. A benign
    -- maintenance update therefore must not re-run current payment authority.
    return new;
  end if;

  select a.valid, a.reason, b.checkout_session_id
    into v_valid, v_reason, v_session
    from public.consumer_briefcase_items b
    cross join lateral public.consumer_packet_payment_authority(
      new.consumer_briefcase_item_id,
      new.consumer_auth_user_id,
      public.expungement_packet_product_id(),
      new.person_id,
      new.matter_id
    ) a
   where b.id = new.consumer_briefcase_item_id;
  if not coalesce(v_valid, false) then
    raise exception 'consumer payment consumption binding refused (%)', coalesce(v_reason, 'unknown');
  end if;
  new.product_id := public.expungement_packet_product_id();
  new.checkout_session_id := v_session;
  new.amount_cents := 5000;
  new.currency := 'usd';
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.publish_validated_consumer_render_artifact()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_verification text;
  v_valid_payment boolean;
  v_artifact jsonb;
begin
  if new.partner_id is not null
     or new.consumer_auth_user_id is null
     or new.consumer_briefcase_item_id is null
     or new.matter_id is null
     or new.consumer_verification_hash is null
     or new.status not in ('artifact_validated', 'delivered')
     or new.delivery_eligibility <> 'eligible'
     or new.accounting_result not in ('zero_charge', 'consumed', 'already_consumed', 'overage_consumed')
     or new.output_storage_path is null
     or new.output_sha256 !~ '^[a-f0-9]{64}$' then
    return new;
  end if;

  select v.verification_hash into v_verification
  from public.consumer_packet_verifications v
  where v.briefcase_item_id = new.consumer_briefcase_item_id
    and v.consumer_auth_user_id = new.consumer_auth_user_id
    and v.status = 'verified'
  for update;
  if v_verification is null or v_verification is distinct from new.consumer_verification_hash then
    return new;
  end if;

  select a.valid into v_valid_payment
  from public.consumer_packet_payment_authority(
    new.consumer_briefcase_item_id,
    new.consumer_auth_user_id,
    public.expungement_packet_product_id(),
    new.person_id,
    new.matter_id
  ) a;
  if not coalesce(v_valid_payment, false) then return new; end if;

  if new.output_storage_path not like
       'packet-artifacts/consumer/' || new.matter_id::text || '/' || new.id::text || '/' || new.output_sha256 || '.pdf'
     or position('..' in new.output_storage_path) > 0 then
    return new;
  end if;

  v_artifact := jsonb_build_object(
    'provider', 'rcap_durable_render_v1',
    'source', 'verified_render_job',
    'packetId', new.packet_id,
    'renderJobId', new.id,
    'artifactSha256', new.output_sha256,
    'storagePath', new.output_storage_path,
    'fileName', 'record-clearing-packet.pdf',
    'contentType', 'application/pdf',
    'generatedAt', new.artifact_validated_at,
    'downloadPath', '/api/expungement-ai/packet/download-link?briefcaseItemId=' || new.consumer_briefcase_item_id::text,
    'pageCount', new.page_count
  );

  insert into public.consumer_packet_artifact_provenance(
    briefcase_item_id, consumer_auth_user_id, matter_id, render_job_id,
    verification_hash, entitlement_source, artifact
  ) values (
    new.consumer_briefcase_item_id, new.consumer_auth_user_id, new.matter_id,
    new.id, new.consumer_verification_hash, 'consumer_payment', v_artifact
    ) on conflict on constraint consumer_packet_artifact_provenance_pkey do update
    set render_job_id = excluded.render_job_id,
        verification_hash = excluded.verification_hash,
        artifact = excluded.artifact
    where consumer_packet_artifact_provenance.consumer_auth_user_id = excluded.consumer_auth_user_id
      and consumer_packet_artifact_provenance.matter_id = excluded.matter_id
      and consumer_packet_artifact_provenance.entitlement_source = excluded.entitlement_source
      and consumer_packet_artifact_provenance.verification_hash is distinct from excluded.verification_hash;

  if exists (
    select 1 from public.consumer_packet_artifact_provenance p
    where p.briefcase_item_id = new.consumer_briefcase_item_id
      and p.consumer_auth_user_id = new.consumer_auth_user_id
      and p.matter_id = new.matter_id
      and p.render_job_id = new.id
      and p.verification_hash = new.consumer_verification_hash
      and p.artifact = v_artifact
  ) then
    update public.consumer_briefcase_items i
    set artifact_refs_json = v_artifact || case
          when i.artifact_refs_json ? 'attribution'
            then jsonb_build_object('attribution', i.artifact_refs_json -> 'attribution')
          else '{}'::jsonb
        end,
        packet_status = 'ready', updated_at = now()
    where i.id = new.consumer_briefcase_item_id
      and i.user_id = new.consumer_auth_user_id;
  end if;
  return new;
end;
$function$;

revoke all on function public.publish_validated_consumer_render_artifact() from public, anon, authenticated, service_role, rcap_render_worker, rcap_packet_delivery;

grant execute on function public.publish_validated_consumer_render_artifact() to service_role;

CREATE OR REPLACE FUNCTION public.packet_render_jobs_consumer_binding_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'UPDATE' then
    if old.consumer_briefcase_item_id is not null
       and new.consumer_briefcase_item_id is distinct from old.consumer_briefcase_item_id then
      raise exception 'packet_render_jobs: consumer_briefcase_item_id is immutable once set';
    end if;
    if old.consumer_auth_user_id is not null
       and new.consumer_auth_user_id is distinct from old.consumer_auth_user_id then
      raise exception 'packet_render_jobs: consumer_auth_user_id is immutable once set';
    end if;
    if old.person_id is not null and new.person_id is distinct from old.person_id then
      raise exception 'packet_render_jobs: person_id is immutable once set';
    end if;
    if old.matter_id is not null and new.matter_id is distinct from old.matter_id then
      raise exception 'packet_render_jobs: matter_id is immutable once set';
    end if;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.finalize_sponsored_packet_generation_for_route(p_route_key text, p_session_id uuid, p_briefcase_item_id uuid, p_expected_verification_hash text, p_packet_artifact jsonb, p_render_job_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(ok boolean, recorded boolean, counted_as text, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_route public.sponsored_packet_render_routes%rowtype;
  v_item public.consumer_briefcase_items%rowtype;
  v_verification public.consumer_packet_verifications%rowtype;
  v_source public.consumer_pending_screening_results%rowtype;
  v_session public.screening_sessions%rowtype;
  v_case public.clinic_cases%rowtype;
  v_event public.clinic_events%rowtype;
  v_entitlement public.partner_entitlement%rowtype;
  v_provenance public.consumer_packet_artifact_provenance%rowtype;
  v_job public.packet_render_jobs%rowtype;
  v_matter_id uuid;
  v_event_artifact_count integer;
  v_counted_as text;
begin
  -- Refuse malformed caller values before taking a lock or changing a row.
  if p_route_key is null
     or p_session_id is null
     or p_briefcase_item_id is null
     or p_expected_verification_hash !~ '^[a-f0-9]{64}$'
     or jsonb_typeof(p_packet_artifact) is distinct from 'object' then
    return query select false, false, 'not_counted'::text, 'invalid_input'::text;
    return;
  end if;

  select * into v_route from public.sponsored_packet_render_routes r
   where r.route_key = p_route_key and r.active;
  if not found then
    return query select false, false, 'not_counted'::text, 'route_not_registered'::text;
    return;
  end if;

  -- The canonical matter is the first lock. The function never accepts an
  -- owner, matter, route, partner, event, or entitlement from its caller.
  select * into v_item
  from public.consumer_briefcase_items i
  where i.id = p_briefcase_item_id
  for update;
  if not found then
    return query select false, false, 'not_counted'::text, 'wrong_item'::text;
    return;
  end if;
  v_matter_id := public.consumer_matter_id_for_briefcase_item(v_item.id);

  -- Lock the protected verification row immediately after the matter. Display
  -- JSON and packet_status are intentionally not verification authority.
  select * into v_verification
  from public.consumer_packet_verifications v
  where v.briefcase_item_id = v_item.id
  for update;
  if not found
     or v_verification.status <> 'verified'
     or v_verification.verification_hash is distinct from p_expected_verification_hash then
    return query select false, false, 'not_counted'::text, 'verification_mismatch'::text;
    return;
  end if;
  if v_verification.consumer_auth_user_id is distinct from v_item.user_id then
    return query select false, false, 'not_counted'::text, 'wrong_owner'::text;
    return;
  end if;
  if v_verification.matter_id is distinct from v_matter_id then
    return query select false, false, 'not_counted'::text, 'wrong_matter'::text;
    return;
  end if;
  if v_item.jurisdiction <> v_route.jurisdiction
     or v_verification.verification_snapshot ->> 'jurisdiction' <> v_route.jurisdiction
     or v_verification.verification_snapshot ->> 'pathwayId' <> v_route.pathway_id
     or (v_route.registry_track_id is not null
         and v_verification.verification_snapshot ->> 'selectedTrackId' is distinct from v_route.registry_track_id) then
    return query select false, false, 'not_counted'::text, 'wrong_jurisdiction_or_route'::text;
    return;
  end if;

  -- Reconstruct the same protected claimed source used by the server-side
  -- presentation authority. It binds owner, item, anonymous source session,
  -- partner product, and Clinic event without trusting request JSON.
  select * into v_source
  from public.consumer_pending_screening_results p
  where p.pending_id = v_item.source_pending_result_id
  for update;
  if not found or v_source.status <> 'CLAIMED'
     or v_source.claimed_matter_id is distinct from v_item.id then
    return query select false, false, 'not_counted'::text, 'wrong_item'::text;
    return;
  end if;
  if v_source.claimed_user_id is distinct from v_item.user_id then
    return query select false, false, 'not_counted'::text, 'wrong_owner'::text;
    return;
  end if;
  if v_source.anonymous_session_id is distinct from p_session_id then
    return query select false, false, 'not_counted'::text, 'wrong_session'::text;
    return;
  end if;
  if v_source.product <> 'rcap_partner'
     or v_source.partner_slug is distinct from v_route.partner_slug then
    return query select false, false, 'not_counted'::text, 'wrong_partner'::text;
    return;
  end if;
  if v_source.jurisdiction <> v_route.jurisdiction then
    return query select false, false, 'not_counted'::text, 'wrong_jurisdiction_or_route'::text;
    return;
  end if;

  select * into v_session
  from public.screening_sessions s
  where s.session_id = p_session_id
  for update;
  if not found
     or v_session.flow_mode <> 'rcap'
     or v_session.partner_benefit_active is not true then
    return query select false, false, 'not_counted'::text, 'sponsorship_inactive'::text;
    return;
  end if;
  if v_session.partner_slug is distinct from v_source.partner_slug then
    return query select false, false, 'not_counted'::text, 'wrong_partner'::text;
    return;
  end if;
  if v_session.jurisdiction <> v_route.jurisdiction then
    return query select false, false, 'not_counted'::text, 'wrong_jurisdiction_or_route'::text;
    return;
  end if;

  select c.* into v_case
  from public.clinic_cases c
  where c.event_id = v_source.event_id
    and c.participant_user_id = v_item.user_id
    and c.screening_session_id = p_session_id
    and c.matter_id = v_item.id
  for update;
  if not found then
    return query select false, false, 'not_counted'::text, 'clinic_scope_mismatch'::text;
    return;
  end if;
  if v_case.jurisdiction <> v_route.jurisdiction or v_case.route_disposition <> 'packet' then
    return query select false, false, 'not_counted'::text, 'wrong_jurisdiction_or_route'::text;
    return;
  end if;

  select * into v_event
  from public.clinic_events e
  where e.id = v_case.event_id
  for update;
  if not found
     or v_event.partner_slug is distinct from v_route.partner_slug
     or v_event.program_key is distinct from v_route.program_key
     or (v_route.clinic_event_name is not null and v_event.name is distinct from v_route.clinic_event_name) then
    return query select false, false, 'not_counted'::text, 'clinic_scope_mismatch'::text;
    return;
  end if;
  if v_event.jurisdiction is distinct from v_route.jurisdiction then
    return query select false, false, 'not_counted'::text, 'wrong_jurisdiction_or_route'::text;
    return;
  end if;
  if v_event.status <> 'published'
     or v_event.sponsorship_allocation is null
     or v_event.sponsorship_allocation <= 0 then
    return query select false, false, 'not_counted'::text, 'sponsorship_inactive'::text;
    return;
  end if;

  -- A participant-deliverable artifact is a Grade-A PDF bound to this exact
  -- item, verification, specification, family, and immutable byte hash.
  if p_packet_artifact ->> 'provider' <> v_route.artifact_provider
     or p_packet_artifact ->> 'source' <> v_route.artifact_source
     or p_packet_artifact ->> 'contentType' <> v_route.artifact_content_type
     or p_packet_artifact ->> 'packetId' <> v_item.id::text
     or p_packet_artifact ->> 'verificationHash' <> p_expected_verification_hash
     or p_packet_artifact ->> 'packetSpecificationId' <> v_route.packet_specification_id
     or p_packet_artifact ->> 'packetSpecificationVersion' <> v_route.packet_specification_version
     or p_packet_artifact ->> 'packetSpecificationSha256' <> v_route.packet_specification_sha256
     or p_packet_artifact ->> 'packetFamily' <> v_route.packet_family_id
     or p_packet_artifact ->> 'artifactSha256' !~ '^[a-f0-9]{64}$'
     or coalesce((p_packet_artifact ->> 'pageCount') ~ '^[1-9][0-9]*$', false) is not true
     or coalesce((p_packet_artifact ->> 'documentCount') ~ '^[1-9][0-9]*$', false) is not true then
    return query select false, false, 'not_counted'::text, 'malformed_artifact'::text;
    return;
  end if;

  -- An optional render job. When the caller names one it must be this
  -- participant's own sponsored job for this exact route, session and
  -- verification, and it must already hold validated, deliverable bytes.
  if p_render_job_id is not null then
    select * into v_job
    from public.packet_render_jobs j
    where j.id = p_render_job_id
    for update;
    if not found
       or v_job.sponsored_route_key is distinct from v_route.route_key
       or v_job.sponsored_session_id is distinct from p_session_id
       or v_job.sponsored_consumer_briefcase_item_id is distinct from v_item.id
       or v_job.sponsored_consumer_auth_user_id is distinct from v_item.user_id
       or v_job.sponsored_verification_hash is distinct from p_expected_verification_hash
       or v_job.matter_id is distinct from v_matter_id
       or v_job.status not in ('artifact_validated', 'delivered')
       or v_job.delivery_eligibility <> 'eligible'
       or coalesce(v_job.output_sha256, '') <> (p_packet_artifact ->> 'artifactSha256') then
      return query select false, false, 'not_counted'::text, 'render_job_mismatch'::text;
      return;
    end if;
  end if;

  -- Lock existing provenance before reading the allowance. An exact retry is
  -- successful and never approaches the credit counter. A changed verification
  -- may publish another validated job for the same matter without recounting.
  select * into v_provenance
  from public.consumer_packet_artifact_provenance p
  where p.briefcase_item_id = v_item.id
  for update;
  if found then
    if v_provenance.consumer_auth_user_id = v_item.user_id
       and v_provenance.matter_id = v_matter_id
       and v_provenance.verification_hash = p_expected_verification_hash
       and v_provenance.entitlement_source = 'partner_sponsorship'
       and v_provenance.render_job_id is not distinct from p_render_job_id
       and v_provenance.artifact = p_packet_artifact then
      select a.metadata ->> 'counted_as' into v_counted_as
      from public.rcap_screening_analytics_events a
      where a.session_id = p_session_id and a.partner_slug = v_route.partner_slug
        and a.event_type = 'packet_generated'
      order by a.occurred_at asc, a.id asc
      limit 1;
      return query select true, false, coalesce(v_counted_as, 'not_counted'), 'already_finalized'::text;
      return;
    end if;
    -- A new protected verification can replace the current artifact for the
    -- same sponsored matter. Every claim/event/route/job check above still ran.
    -- Existing allowance evidence is reused; no counter or analytics event is
    -- written on this path. Same-verification byte changes remain conflicts.
    if p_render_job_id is not null and v_provenance.render_job_id is not null
       and v_provenance.consumer_auth_user_id = v_item.user_id
       and v_provenance.matter_id = v_matter_id
       and v_provenance.entitlement_source = 'partner_sponsorship'
       and v_provenance.verification_hash is distinct from p_expected_verification_hash
       and exists (
         select 1 from public.packet_render_jobs previous
         where previous.id = v_provenance.render_job_id
           and previous.sponsored_route_key = p_route_key
           and previous.sponsored_session_id = p_session_id
           and previous.sponsored_clinic_event_id = v_event.id
           and previous.partner_id = v_job.partner_id
       ) then
      select a.metadata ->> 'counted_as' into v_counted_as
      from public.rcap_screening_analytics_events a
      where a.session_id = p_session_id and a.partner_slug = v_route.partner_slug
        and a.event_type = 'packet_generated'
        and a.metadata ->> 'clinic_event_id' = v_event.id::text
      order by a.occurred_at asc, a.id asc limit 1;
      if v_counted_as not in ('included', 'overage') or v_counted_as is null
         or v_session.claimed_slot_state is distinct from 'consumed' then
        return query select false, false, 'not_counted'::text, 'prior_consumption_missing'::text;
        return;
      end if;
      update public.consumer_packet_artifact_provenance
      set render_job_id = p_render_job_id,
          verification_hash = p_expected_verification_hash,
          artifact = p_packet_artifact
      where briefcase_item_id = v_item.id;
      update public.consumer_briefcase_items
      set artifact_refs_json = (p_packet_artifact - 'attribution') || case
            when v_item.artifact_refs_json ? 'attribution'
              then jsonb_build_object('attribution', v_item.artifact_refs_json -> 'attribution')
            else '{}'::jsonb
          end,
          packet_status = 'ready', updated_at = now()
      where id = v_item.id and user_id = v_item.user_id;
      update public.clinic_cases
      set queue_status = 'packet_ready', last_activity_at = now(), updated_at = now()
      where id = v_case.id;
      return query select true, false, v_counted_as, 'regenerated'::text;
      return;
    end if;
    return query select false, false, 'not_counted'::text, 'artifact_conflict'::text;
    return;
  end if;
  if v_session.claimed_slot_state is distinct from 'claimed' then
    return query select false, false, 'not_counted'::text, 'sponsorship_already_consumed'::text;
    return;
  end if;

  if not exists(select 1 from public.allocate_clinic_packet_funding(
    v_item.id,v_item.user_id,p_expected_verification_hash) f where f.funding_mode='sponsored') then
    return query select false,false,'capped'::text,'sponsor_capacity_requires_dtc'::text; return;
  end if;

  -- The event allocation is a second, narrower cap around the partner usage
  -- window. Count only protected sponsored provenance for matters in this
  -- exact event; a repeat was returned above and therefore cannot recount.
  select count(*)::integer into v_event_artifact_count
  from public.consumer_packet_artifact_provenance p
  join public.clinic_cases c on c.matter_id = p.briefcase_item_id
  where c.event_id = v_event.id
    and p.entitlement_source = 'partner_sponsorship';
  if v_event_artifact_count >= v_event.sponsorship_allocation then
    return query select false, false, 'capped'::text, 'event_sponsorship_exhausted'::text;
    return;
  end if;

  select * into v_entitlement
  from public.partner_entitlement pe
  where pe.partner_slug = v_event.partner_slug
  for update;
  if not found then
    return query select false, false, 'not_counted'::text, 'no_entitlement'::text;
    return;
  end if;
  if v_entitlement.screenings_used < v_entitlement.screenings_allowed then
    v_counted_as := 'included';
  elsif v_entitlement.pause_at_cap then
    return query select false, false, 'capped'::text, 'paused_at_cap'::text;
    return;
  elsif v_entitlement.overage_enabled then
    v_counted_as := 'overage';
  else
    return query select false, false, 'not_counted'::text, 'cap_reached_no_overage'::text;
    return;
  end if;

  -- All refusal branches are above this line. Any unexpected failure below is
  -- raised so PostgreSQL rolls back the complete transaction rather than
  -- returning a partially-mutated refusal.
  if v_counted_as = 'included' then
    update public.partner_entitlement pe
    set screenings_used = pe.screenings_used + 1, updated_at = now()
    where pe.partner_slug = v_entitlement.partner_slug;
  else
    update public.partner_entitlement pe
    set overage_packets = pe.overage_packets + 1,
        overage_amount_cents = pe.overage_amount_cents + pe.overage_packet_price_cents,
        updated_at = now()
    where pe.partner_slug = v_entitlement.partner_slug;
  end if;

  update public.screening_sessions s
  set claimed_slot_state = 'consumed', status = 'completed', updated_at = now()
  where s.session_id = p_session_id and s.claimed_slot_state = 'claimed';
  if not found then raise exception 'sponsored finalization lost its locked session'; end if;

  insert into public.rcap_record_events
    (record_type, record_id, partner_slug, event_type, occurred_at, actor, metadata)
  values
    ('partner_entitlement', v_event.partner_slug, v_event.partner_slug,
     case when v_counted_as = 'overage'
       then 'partner_packet_overage_recorded' else 'partner_packet_credit_consumed' end,
     now(), 'system', jsonb_build_object(
       'session_id', p_session_id,
       'briefcase_item_id', v_item.id,
       'counted_as', v_counted_as,
       'clinic_event_id', v_event.id
     ));

  insert into public.rcap_screening_analytics_events
    (session_id, partner_slug, partner_access_code_id, campaign_name,
     event_type, packet_route_available, occurred_at, metadata)
  values
    (v_session.session_id, v_session.partner_slug,
     v_session.partner_access_code_id, v_session.campaign_name,
     'packet_generated', true, now(),
     jsonb_build_object('counted_as', v_counted_as, 'clinic_event_id', v_event.id));
  if v_counted_as = 'overage' then
    insert into public.rcap_screening_analytics_events
      (session_id, partner_slug, partner_access_code_id, campaign_name,
       event_type, packet_route_available, occurred_at, metadata)
    values
      (v_session.session_id, v_session.partner_slug,
       v_session.partner_access_code_id, v_session.campaign_name,
       'packet_overage_recorded', true, now(),
       jsonb_build_object(
         'overage_packet_price_cents', v_entitlement.overage_packet_price_cents,
         'clinic_event_id', v_event.id
       ));
  end if;

  insert into public.consumer_packet_artifact_provenance(
    briefcase_item_id, consumer_auth_user_id, matter_id, render_job_id,
    verification_hash, entitlement_source, artifact
  ) values (
    v_item.id, v_item.user_id, v_matter_id, p_render_job_id,
    p_expected_verification_hash, 'partner_sponsorship', p_packet_artifact
  );

  update public.consumer_briefcase_items i
  set artifact_refs_json = coalesce(i.artifact_refs_json, '{}'::jsonb) || p_packet_artifact,
      packet_status = 'ready', updated_at = now()
  where i.id = v_item.id and i.user_id = v_item.user_id;
  if not found then raise exception 'sponsored finalization lost its locked matter'; end if;

  update public.clinic_cases c
  set queue_status = 'packet_ready', last_activity_at = now(), updated_at = now()
  where c.id = v_case.id;

  return query select true, true, v_counted_as, null::text;
end;
$function$;

alter table public.packet_render_jobs drop constraint packet_render_jobs_error_code_check;

alter table public.packet_render_jobs add constraint packet_render_jobs_error_code_check CHECK (((error_code IS NULL) OR (error_code = ANY (ARRAY['source_not_whitelisted'::text, 'profile_unknown'::text, 'render_failed'::text, 'invalid_pdf_output'::text, 'page_count_mismatch'::text, 'protected_field_populated'::text, 'storage_write_failed'::text, 'storage_readback_failed'::text, 'checksum_mismatch'::text, 'timeout'::text, 'worker_crashed'::text, 'participant_deletion_cancelled'::text, 'output_empty'::text, 'output_not_pdf'::text, 'output_unparseable'::text, 'output_no_pages'::text, 'output_geometry_unexpected'::text, 'unknown_job'::text, 'job_not_claimable'::text, 'renderer_kind_unknown'::text, 'source_sha_not_allowed'::text, 'profile_version_unknown'::text, 'container_digest_missing'::text]))));

alter table public.packet_render_jobs add constraint packet_render_jobs_retry_history_array CHECK ((jsonb_typeof(retry_reconciliation_history) = 'array'::text));

CREATE TRIGGER guard_packet_render_job_retry_history BEFORE UPDATE ON public.packet_render_jobs FOR EACH ROW EXECUTE FUNCTION guard_packet_render_job_retry_history();

create or replace function public.get_consumer_briefcase_presentation_source(
  p_consumer_auth_user_id uuid,
  p_briefcase_item_id uuid
)
returns table (
  consumer_auth_user_id uuid,
  briefcase_item_id uuid,
  claimed_user_id uuid,
  claimed_at text,
  source_identity text,
  product text,
  partner_benefit_active boolean,
  partner_slug text,
  jurisdiction text,
  profile_version text,
  matter_id text,
  screening_answers jsonb,
  screening_answers_sha256 text,
  source_linkage_sha256 text
)
language sql
stable
security definer
set search_path = ''
as $source$
  with trusted as (
    select
      i.user_id as consumer_auth_user_id,
      i.id as briefcase_item_id,
      p.claimed_user_id,
      p.claimed_at,
      coalesce(p.anonymous_session_id::text, p.pending_id::text) as source_identity,
      p.product,
      (p.product = 'rcap_partner' and p.partner_slug is not null) as partner_benefit_active,
      p.partner_slug,
      p.jurisdiction,
      p.profile_version,
      public.consumer_matter_id_for_briefcase_item(i.id)::text as matter_id,
      p.screening_answers,
      encode(extensions.digest(convert_to(public.consumer_canonical_json(p.screening_answers), 'utf8'), 'sha256'), 'hex') as answers_hash
    from public.consumer_briefcase_items i
    join public.consumer_pending_screening_results p
      on p.pending_id = i.source_pending_result_id
    where i.id = p_briefcase_item_id
      and i.user_id = p_consumer_auth_user_id
      and p.status = 'CLAIMED'
      and p.claimed_user_id = p_consumer_auth_user_id
      and p.claimed_matter_id = i.id
  )
  select t.consumer_auth_user_id, t.briefcase_item_id, t.claimed_user_id,
    t.claimed_at::text, t.source_identity, t.product, t.partner_benefit_active,
    t.partner_slug, t.jurisdiction, t.profile_version, t.matter_id,
    t.screening_answers, t.answers_hash,
    encode(extensions.digest(convert_to(public.consumer_canonical_json(jsonb_build_object(
      'consumerAuthUserId', t.consumer_auth_user_id::text,
      'briefcaseItemId', t.briefcase_item_id::text,
      'matterId', t.matter_id,
      'sourceIdentity', t.source_identity,
      'claimedAt', t.claimed_at::text,
      'screeningAnswersSha256', t.answers_hash,
      'product', t.product,
      'partnerBenefitActive', t.partner_benefit_active,
      'partnerSlug', t.partner_slug
    )), 'utf8'), 'sha256'), 'hex')
  from trusted t;
$source$;

do $canonical_gate$ declare actual jsonb; begin select to_jsonb(c) into actual from (select p.prosrc,p.prosecdef,p.proconfig,p.provolatile,l.lanname,has_function_privilege('service_role',p.oid,'EXECUTE')as service_execute,has_function_privilege('anon',p.oid,'EXECUTE')as anon_execute,has_function_privilege('authenticated',p.oid,'EXECUTE')as authenticated_execute from pg_proc p join pg_language l on l.oid=p.prolang where p.oid=to_regprocedure('public.get_consumer_briefcase_presentation_source(uuid,uuid)')) c; if actual is distinct from '{"prosrc":"\n  with trusted as (\n    select\n      i.user_id as consumer_auth_user_id,\n      i.id as briefcase_item_id,\n      p.claimed_user_id,\n      p.claimed_at,\n      coalesce(p.anonymous_session_id::text, p.pending_id::text) as source_identity,\n      p.product,\n      (p.product = ''rcap_partner'' and p.partner_slug is not null) as partner_benefit_active,\n      p.partner_slug,\n      p.jurisdiction,\n      p.profile_version,\n      public.consumer_matter_id_for_briefcase_item(i.id)::text as matter_id,\n      p.screening_answers,\n      encode(extensions.digest(convert_to(public.consumer_canonical_json(p.screening_answers), ''utf8''), ''sha256''), ''hex'') as answers_hash\n    from public.consumer_briefcase_items i\n    join public.consumer_pending_screening_results p\n      on p.pending_id = i.source_pending_result_id\n    where i.id = p_briefcase_item_id\n      and i.user_id = p_consumer_auth_user_id\n      and p.status = ''CLAIMED''\n      and p.claimed_user_id = p_consumer_auth_user_id\n      and p.claimed_matter_id = i.id\n  )\n  select t.consumer_auth_user_id, t.briefcase_item_id, t.claimed_user_id,\n    t.claimed_at::text, t.source_identity, t.product, t.partner_benefit_active,\n    t.partner_slug, t.jurisdiction, t.profile_version, t.matter_id,\n    t.screening_answers, t.answers_hash,\n    encode(extensions.digest(convert_to(public.consumer_canonical_json(jsonb_build_object(\n      ''consumerAuthUserId'', t.consumer