yable'';\n  else\n    v_disposition := ''terminal'';\n  end if;\n\n  perform set_config(''rcap.packet_mutation_authority'', ''fail_packet_render_job'', true);\n  update public.packet_render_jobs\n  set status = ''failed'',\n      failure_disposition = v_disposition,\n      error_code = left(coalesce(nullif(trim(p_error_code), ''''), ''render_failed''), 120),\n      last_error_detail = left(coalesce(p_error_detail, ''''), 2000),\n      next_attempt_at = case\n        when v_disposition = ''retryable''\n        then now() + make_interval(secs => least(3600, 30 * power(2, v_job.attempt_count))::integer)\n        else null\n      end,\n      fencing_token = null,\n      claim_expires_at = null\n  where id = p_job_id;\n  perform set_config(''rcap.packet_mutation_authority'', '''', true);\n  return v_disposition;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"table:partner_packet_entitlement":{"rls":true,"owner":"postgres","forceRls":false,"publicAcl":[],"privileges":{"anon":{"DELETE":false,"INSERT":false,"SELECT":false,"UPDATE":false,"TRIGGER":false,"TRUNCATE":false,"REFERENCES":false},"service_role":{"DELETE":false,"INSERT":true,"SELECT":true,"UPDATE":true,"TRIGGER":false,"TRUNCATE":false,"REFERENCES":false},"authenticated":{"DELETE":false,"INSERT":false,"SELECT":false,"UPDATE":false,"TRIGGER":false,"TRUNCATE":false,"REFERENCES":false},"rcap_render_worker":{"DELETE":false,"INSERT":false,"SELECT":false,"UPDATE":false,"TRIGGER":false,"TRUNCATE":false,"REFERENCES":false},"rcap_packet_delivery":{"DELETE":false,"INSERT":false,"SELECT":false,"UPDATE":false,"TRIGGER":false,"TRUNCATE":false,"REFERENCES":false}}},"functions:claim_packet_render_job":{"claim_packet_render_job(text,text[],integer)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":true,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.claim_packet_render_job(p_worker_id text, p_renderer_kinds text[], p_claim_seconds integer DEFAULT 600)\n RETURNS TABLE(id uuid, packet_id uuid, route_id text, renderer_kind text, renderer_version text, source_sha256 text, profile_id text, profile_version text, input_hash text, attempt_count integer, max_attempts integer, partner_id uuid, person_id uuid, matter_id uuid, fencing_token uuid, claim_expires_at timestamp with time zone)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_worker_id text;\n  v_job_id uuid;\n  v_token uuid;\nbegin\n  v_worker_id := nullif(trim(p_worker_id), '''');\n  if v_worker_id is null then\n    raise exception ''a worker id is required to claim a job'';\n  end if;\n  if p_claim_seconds is null or p_claim_seconds < 30 or p_claim_seconds > 3600 then\n    raise exception ''claim seconds must be between 30 and 3600'';\n  end if;\n\n  select j.id into v_job_id\n  from public.packet_render_jobs j\n  where j.status = ''queued''\n    and j.attempt_count < j.max_attempts\n    and (j.next_attempt_at is null or j.next_attempt_at <= now())\n    and (p_renderer_kinds is null or j.renderer_kind = any (p_renderer_kinds))\n  order by j.created_at, j.id\n  for update skip locked\n  limit 1;\n\n  if v_job_id is null then\n    return;\n  end if;\n\n  v_token := gen_random_uuid();\n  perform set_config(''rcap.packet_mutation_authority'', ''claim_packet_render_job'', true);\n  return query\n  update public.packet_render_jobs j\n  set status = ''claimed'',\n      claimed_by = v_worker_id,\n      claim_expires_at = now() + make_interval(secs => p_claim_seconds),\n      fencing_token = v_token,\n      attempt_count = j.attempt_count + 1\n  where j.id = v_job_id\n  returning j.id, j.packet_id, j.route_id, j.renderer_kind, j.renderer_version,\n            j.source_sha256, j.profile_id, j.profile_version, j.input_hash,\n            j.attempt_count, j.max_attempts, j.partner_id, j.person_id, j.matter_id,\n            j.fencing_token, j.claim_expires_at;\n  perform set_config(''rcap.packet_mutation_authority'', '''', true);\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:start_packet_validation":{"start_packet_validation(uuid,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":true,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.start_packet_validation(p_job_id uuid, p_fencing_token uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_job public.packet_render_jobs%rowtype;\nbegin\n  select * into v_job from public.packet_render_jobs where id = p_job_id for update;\n  if not found then return false; end if;\n  perform public.assert_packet_render_job_fencing(v_job, p_fencing_token);\n  if v_job.status <> ''rendering'' then\n    raise exception ''packet_render_jobs: validation starts only from rendering, job is %'', v_job.status;\n  end if;\n  perform set_config(''rcap.packet_mutation_authority'', ''start_packet_validation'', true);\n  update public.packet_render_jobs set status = ''validating'' where id = p_job_id;\n  perform set_config(''rcap.packet_mutation_authority'', '''', true);\n  return true;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"policies:consumer_briefcase_items":[{"name":"consumer briefcase delete own items","check":null,"roles":["PUBLIC"],"using":"(auth.uid() = user_id)","command":"d","permissive":true},{"name":"consumer briefcase insert own items","check":"(auth.uid() = user_id)","roles":["PUBLIC"],"using":null,"command":"a","permissive":true},{"name":"consumer briefcase select own items","check":null,"roles":["PUBLIC"],"using":"(auth.uid() = user_id)","command":"r","permissive":true},{"name":"consumer briefcase update own items","check":"(auth.uid() = user_id)","roles":["PUBLIC"],"using":"(auth.uid() = user_id)","command":"w","permissive":true}],"column:consumer_briefcase_items.id":{"type":"uuid","default":"gen_random_uuid()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.route_id":{"type":"text","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.matter_id":{"type":"uuid","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render