se},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:guard_packet_delivery_events":{"guard_packet_delivery_events()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":true,"service_role":true,"authenticated":true,"rcap_render_worker":true,"rcap_packet_delivery":true},"definition":"CREATE OR REPLACE FUNCTION public.guard_packet_delivery_events()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\nbegin\n  if tg_op = ''INSERT'' then\n    if public.rcap_packet_mutation_authority() <> ''record_packet_delivery_event'' then\n      raise exception ''packet_delivery_events: events are recorded only by record_packet_delivery_event'';\n    end if;\n    return new;\n  end if;\n  raise exception ''packet_delivery_events: append-only; % is never permitted'', tg_op;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":true,"securityDefiner":false}},"functions:record_packet_delivery_event":{"record_packet_delivery_event(uuid,text,uuid,jsonb)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":true},"definition":"CREATE OR REPLACE FUNCTION public.record_packet_delivery_event(p_job_id uuid, p_event_type text, p_actor_user_id uuid, p_request_context jsonb DEFAULT ''{}''::jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_job public.packet_render_jobs%rowtype;\n  v_event_id uuid;\nbegin\n  if p_event_type not in (''delivery_authorized'', ''transmission_started'', ''transmission_completed'', ''transmission_aborted'', ''transmission_failed'') then\n    raise exception ''packet_delivery_events: unknown event type %'', p_event_type;\n  end if;\n\n  select * into v_job from public.packet_render_jobs where id = p_job_id for update;\n  if not found then\n    raise exception ''packet_delivery_events: unknown render job'';\n  end if;\n\n  -- No event of any kind is recorded against a packet that accounting has not\n  -- authorized. artifact_validated by itself is never sufficient.\n  if v_job.delivery_eligibility <> ''eligible''\n     or v_job.status not in (''artifact_validated'', ''delivered'') then\n    raise exception ''packet_delivery_events: job is not delivery-eligible'';\n  end if;\n\n  perform set_config(''rcap.packet_mutation_authority'', ''record_packet_delivery_event'', true);\n  insert into public.packet_delivery_events (render_job_id, event_type, actor_user_id, request_context)\n  values (p_job_id, p_event_type, p_actor_user_id, coalesce(p_request_context, ''{}''::jsonb))\n  returning id into v_event_id;\n\n  if p_event_type = ''transmission_completed'' and v_job.status = ''artifact_validated'' then\n    update public.packet_render_jobs\n    set status = ''delivered''\n    where id = p_job_id;\n  end if;\n  perform set_config(''rcap.packet_mutation_authority'', '''', true);\n\n  return v_event_id;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"policies:consumer_packet_verifications":[],"column:consumer_briefcase_items.user_id":{"type":"uuid","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{