:"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:guard_packet_render_job_delete":{"guard_packet_render_job_delete()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":true,"service_role":true,"authenticated":true,"rcap_render_worker":true,"rcap_packet_delivery":true},"definition":"CREATE OR REPLACE FUNCTION public.guard_packet_render_job_delete()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\nbegin\n  raise exception ''packet_render_jobs: rows are never deleted'';\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":true,"securityDefiner":false}},"functions:guard_packet_render_job_insert":{"guard_packet_render_job_insert()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":true,"service_role":true,"authenticated":true,"rcap_render_worker":true,"rcap_packet_delivery":true},"definition":"CREATE OR REPLACE FUNCTION public.guard_packet_render_job_insert()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\nbegin\n  if public.rcap_packet_mutation_authority() <> ''enqueue_packet_render_job'' then\n    raise exception ''packet_render_jobs: rows are created only through enqueue_packet_render_job'';\n  end if;\n  return new;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":true,"securityDefiner":false}},"functions:rcap_packet_mutation_authority":{"rcap_packet_mutation_authority()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":true,"service_role":true,"authenticated":true,"rcap_render_worker":true,"rcap_packet_delivery":true},"definition":"CREATE OR REPLACE FUNCTION public.rcap_packet_mutation_authority()\n RETURNS text\n LANGUAGE sql\n STABLE\n SET search_path TO ''''\nAS $function$\n  select coalesce(current_setting(''rcap.packet_mutation_authority'', true), '''');\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":true,"securityDefiner":false}},"functions:record_consumer_packet_payment":{"record_consumer_packet_payment(uuid,text,integer,text,text,text,text,text,text,text,text,text,uuid,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.record_consumer_packet_payment(p_briefcase_item_id uuid, p_payment_status text, p_amount_cents integer, p_currency text, p_payment_provider text, p_provider_event_id text, p_checkout_session_id text, p_payment_intent_id text, p_receipt_url text, p_authority text, p_recorded_by text, p_product_id text, p_person_id uuid, p_matter_id uuid)\n RETURNS TABLE(outcome text, briefcase_item_id uuid, provider_event_id text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nbegin\n  -- No caller may record a payment without saying what the regular price and\n  -- the discount were. Silence here would mean a discounted order recorded at\n  -- full price.\n  return query select ''invalid_payment_evidence''::text, p_briefcase_item_id, null::text;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true},"record_consumer_packet_payment(uuid,text,integer,text,text,text,text,text,text,text,text,text,uuid,uuid,text)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.record_consumer_packet_payment(p_briefcase_item_id uuid, p_payment_status text, p_amount_cents integer, p_currency text, p_payment_provider text, p_provider_event_id text, p_checkout_session_id text, p_payment_intent_id text, p_receipt_url text, p_authority text, p_recorded_by text, p_product_id text, p_person_id uuid, p_matter_id uuid, p_expected_verification_hash text)\n RETURNS TABLE(outcome text, briefcase_item_id uuid, provider_event_id text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\nbegin\n  return query select ''invalid_payment_evidence''::text, p_briefcase_item_id, null::text;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true},"record_consumer_packet_payment(uuid,text,integer,integer,integer,text,text,text,text,text,text,text,text,text,uuid,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.record_consumer_packet_payment(p_briefcase_item_id uuid, p_payment_status text, p_amount_cents integer, p_regular_price_cents integer, p_discount_cents integer, p_currency text, p_payment_provider text, p_provider_event_id text, p_checkout_session_id text, p_payment_intent_id text, p_receipt_url text, p_authority text, p_recorded_by text, p_product_id text, p_person_id uuid, p_matter_id uuid)\n RETURNS TABLE(outcome text, briefcase_item_id uuid, provider_event_id text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_found boolean;\n  v_owner uuid;\n  v_status text;\n  v_existing_event text;\n  v_existing_session text;\n  v_existing_product text;\n  v_existing_person uuid;\n  v_existing_matter uuid;\n  v_existing_amount integer;\n  v_existing_currency text;\n  v_payment_allowed boolean;\n  v_source_session_id text;\n  v_item_type text;\n  v_jurisdiction text;\n  v_pathway_label text;\n  v_result_code text;\n  v_packet_type text;\n  v_item_status text;\n  v_sponsored boolean := false;\n  v_expected_match_key text;\n  v_amount_due integer;\nbegin\n  if to_regclass(''public.consumer_briefcase_items'') is null then\n    return query select ''no_payment_storage''::text, p_briefcase_item_id, null::text;\n    return;\n  end if;\n  if p_briefcase_item_id is null then\n    return query select ''invalid_item''::text, null::uuid, null::text;\n    return;\n  end if;\n  if coalesce(p_authority, '''') not in (''server_webhook'', ''server_admin'') then\n    return query select ''invalid_authority''::text, p_briefcase_item_id, null::text;\n    return;\n  end if;\n\n  execute\n    ''select true, b.user_id, b.payment_status, b.provider_event_id,\n            b.checkout_session_id, b.payment_product_id, b.payment_person_id,\n            b.payment_matter_id, b.amount_cents, b.currency,\n            b.payment_allowed, b.source_session_id, b.item_type,\n            b.jurisdiction, b.pathway_label, b.result_code,\n            b.packet_type, b.status\n       from public.consumer_briefcase_items b\n      where b.id = $1 for update''\n  into v_found, v_owner, v_status, v_existing_event, v_existing_session,\n       v_existing_product, v_existing_person, v_existing_matter,\n       v_existing_amount, v_existing_currency, v_payment_allowed,\n       v_source_session_id, v_item_type, v_jurisdiction,\n       v_pathway_label, v_result_code, v_packet_type, v_item_status\n  using p_briefcase_item_id;\n\n  if not coalesce(v_found, false) then\n    return query select ''item_not_found''::text, p_briefcase_item_id, null::text;\n    return;\n  end if;\n\n  if p_payment_status = ''paid'' then\n    if v_payment_allowed is not true then\n      return query select ''payment_not_allowed''::text, p_briefcase_item_id, null::text;\n      return;\n    end if;\n\n    if v_item_type not in (''result'', ''packet'')\n       or nullif(trim(coalesce(v_jurisdiction, '''')), '''') is null\n       or nullif(trim(coalesce(v_pathway_label, '''')), '''') is null\n       or v_result_code not in (''packet_ready'', ''packet_ready_with_caution'')\n       or v_packet_type not in (''official_pdf_overlay'', ''custom_pleading'', ''legacy_packet'')\n       or v_item_status is distinct from ''packet_ready'' then\n      return query select ''invalid_item''::text, p_briefcase_item_id, null::text;\n      return;\n    end if;\n\n    if to_regclass(''public.screening_sessions'') is not null\n       and exists (\n         select 1\n           from information_schema.columns c\n          where c.table_schema = ''public''\n            and c.table_name = ''screening_sessions''\n            and c.column_name in (''session_id'', ''flow_mode'', ''partner_slug'', ''partner_benefit_active'')\n          group by c.table_schema, c.table_name\n         having count(*) = 4\n       ) then\n      execute\n        ''select exists (\n           select 1 from public.screening_sessions s\n            where s.session_id::text = nullif(trim($1), '''''''')\n              and s.flow_mode = ''''rcap''''\n              and nullif(trim(coalesce(s.partner_slug, '''''''')), '''''''') is not null\n              and s.partner_benefit_active is true\n         )''\n      into v_sponsored\n      using v_source_session_id;\n    end if;\n\n    if (coalesce(v_sponsored, false) or exists (\n      select 1 from public.consumer_briefcase_items i\n      join public.consumer_pending_screening_results s on s.pending_id=i.source_pending_result_id\n      where i.id=p_briefcase_item_id and s.product=''rcap_partner''\n    )) and not public.clinic_packet_dtc_authorized(p_briefcase_item_id,v_owner) then\n      return query select ''sponsored_item''::text, p_briefcase_item_id, null::text;\n      return;\n    end if;\n\n    -- The reconciliation, in the database, where it holds even if the\n    -- application is wrong. This is what replaces `p_amount_cents <> 5000`.\n    v_amount_due := coalesce(p_regular_price_cents, -1) - coalesce(p_discount_cents, -1);\n    if p_regular_price_cents is distinct from 5000\n       or p_discount_cents is null\n       or p_discount_cents < 0\n       or p_discount_cents > p_regular_price_cents\n       or p_amount_cents is distinct from v_amount_due\n       or lower(coalesce(p_currency, '''')) <> ''usd''\n       or nullif(trim(coalesce(p_provider_event_id, '''')), '''') is null\n       or nullif(trim(coalesce(p_checkout_session_id, '''')), '''') is null\n       or p_product_id is distinct from ''expungement_packet''\n       or p_person_id is null\n       or p_matter_id is distinct from public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id) then\n      return query select ''invalid_payment_evidence''::text, p_briefcase_item_id, null::text;\n      return;\n    end if;\n\n    -- Stripe creates no PaymentIntent for a zero-total order and always creates\n    -- one when money is due. A row that disagrees with its own total is not a\n    -- description of any order Stripe produced.\n    if (v_amount_due > 0) <> (nullif(trim(coalesce(p_payment_intent_id, '''')), '''') is not null) then\n      return query select ''invalid_payment_evidence''::text, p_briefcase_item_id, null::text;\n      return;\n    end if;\n\n    v_expected_match_key := ''consumer:'' || encode(\n      extensions.digest(convert_to(''rcap:consumer-person:v1:'' || v_owner::text, ''utf8''), ''sha256''),\n      ''hex''\n    );\n    if not exists (\n      select 1 from public.rcap_persons p\n       where p.id = p_person_id\n         and p.partner_slug = ''expungement-ai-consumer''\n         and p.match_key = v_expected_match_key\n    ) then\n      return query select ''invalid_payment_identity''::text, p_briefcase_item_id, null::text;\n      return;\n    end if;\n\n    if v_existing_session is distinct from p_checkout_session_id\n       or v_existing_product is distinct from p_product_id\n       or v_existing_person is distinct from p_person_id\n       or v_existing_matter is distinct from p_matter_id then\n      return query select ''checkout_binding_mismatch''::text, p_briefcase_item_id, null::text;\n      return;\n    end if;\n\n    -- A second signed event for the same already-settled Session is an\n    -- idempotent success. The stored amount is compared against what this event\n    -- reconciles to rather than against 5000, so a replayed no-cost order\n    -- converges instead of reading as a conflict.\n    if v_status = ''paid'' then\n      if v_existing_amount is not distinct from p_amount_cents\n         and lower(coalesce(v_existing_currency, '''')) = ''usd''\n         and nullif(trim(coalesce(v_existing_event, '''')), '''') is not null then\n        return query select ''already_paid''::text, p_briefcase_item_id, v_existing_event;\n        return;\n      end if;\n      return query select ''payment_conflict''::text, p_briefcase_item_id, v_existing_event;\n      return;\n    end if;\n\n    begin\n      execute\n        ''update public.consumer_briefcase_items\n            set payment_status = ''''paid'''', amount_cents = $11,\n                regular_price_cents = $12, discount_cents = $13, currency = ''''usd'''',\n                payment_provider = coalesce($2, payment_provider),\n                payment_intent_id = coalesce($3, payment_intent_id),\n                receipt_url = coalesce($4, receipt_url), provider_event_id = $5,\n                payment_authority = $6, payment_recorded_at = now(),\n                payment_recorded_by = $7, payment_product_id = $8,\n                payment_person_id = $9, payment_matter_id = $10\n          where id = $1''\n      using p_briefcase_item_id, p_payment_provider, p_payment_intent_id,\n            p_receipt_url, trim(p_provider_event_id), p_authority, p_recorded_by,\n            p_product_id, p_person_id, p_matter_id,\n            p_amount_cents, p_regular_price_cents, p_discount_cents;\n    exception when unique_violation then\n      return query select ''duplicate_provider_event''::text, p_briefcase_item_id, trim(p_provider_event_id);\n      return;\n    end;\n\n    return query select ''recorded_paid''::text, p_briefcase_item_id, trim(p_provider_event_id);\n    return;\n  end if;\n\n  if p_payment_status not in (''not_applicable'', ''unpaid'', ''refunded'') then\n    return query select ''invalid_status''::text, p_briefcase_item_id, null::text;\n    return;\n  end if;\n\n  execute\n    ''update public.consumer_briefcase_items\n        set payment_status = $2, payment_authority = $3,\n            payment_recorded_at = now(), payment_recorded_by = $4\n      where id = $1''\n  using p_briefcase_item_id, p_payment_status, p_authority, p_recorded_by;\n\n  return query select (''recorded_'' || p_payment_status)::text, p_briefcase_item_id, v_existing_event;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true},"record_consumer_packet_payment(uuid,text,integer,integer,integer,text,text,text,text,text,text,text,text,text,uuid,uuid,text)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.record_consumer_packet_payment(p_briefcase_item_id uuid, p_payment_status text, p_amount_cents integer, p_regular_price_cents integer, p_discount_cents integer, p_currency text, p_payment_provider text, p_provider_event_id text, p_checkout_session_id text, p_payment_intent_id text, p_receipt_url text, p_authority text, p_recorded_by text, p_product_id text, p_person_id uuid, p_matter_id uuid, p_expected_verification_hash text)\n RETURNS TABLE(outcome text, briefcase_item_id uuid, provider_event_id text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_hash text;\n  v_result record;\nbegin\n  select v.verification_hash into v_hash from public.consumer_packet_verifications v\n   where v.briefcase_item_id = p_briefcase_item_id and v.status = ''verified'' for update;\n  if v_hash is null or v_hash is distinct from p_expected_verification_hash then\n    return query select ''invalid_payment_evidence''::text, p_briefcase_item_id, null::text; return;\n  end if;\n  select * into v_result from public.record_consumer_packet_payment(\n    p_briefcase_item_id, p_payment_status, p_amount_cents,\n    p_regular_price_cents, p_discount_cents, p_currency,\n    p_payment_provider, p_provider_event_id, p_checkout_session_id,\n    p_payment_intent_id, p_receipt_url, p_authority, p_recorded_by,\n    p_product_id, p_person_id, p_matter_id\n  );\n  return query select v_result.outcome::text, v_result.briefcase_item_id::uuid,\n    v_result.provider_event_id::text;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"column:consumer_briefcase_items.item_type":{"type":"text","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_credit_ledger