p_render_worker":false,"rcap_packet_delivery":false},"publicExecute":true,"securityDefiner":false}},"functions:requeue_packet_render_job_manual":{"requeue_packet_render_job_manual(uuid,text)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.requeue_packet_render_job_manual(p_job_id uuid, p_authorized_by text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_job public.packet_render_jobs%rowtype;\nbegin\n  if nullif(trim(p_authorized_by), '''') is null then\n    raise exception ''a manual requeue requires a named authorizer'';\n  end if;\n  select * into v_job from public.packet_render_jobs where id = p_job_id for update;\n  if not found then return false; end if;\n  if v_job.status <> ''failed'' then\n    raise exception ''packet_render_jobs: only a failed job can be requeued manually'';\n  end if;\n\n  perform set_config(''rcap.packet_mutation_authority'', ''requeue_packet_render_job_manual'', true);\n  update public.packet_render_jobs\n  set status = ''queued'',\n      failure_disposition = null,\n      next_attempt_at = null,\n      manual_requeue_authorized_by = trim(p_authorized_by),\n      max_attempts = greatest(max_attempts, attempt_count + 1)\n  where id = p_job_id;\n  perform set_config(''rcap.packet_mutation_authority'', '''', true);\n  return true;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"policies:consumer_artifact_download_grants":[],"column:consumer_artifact_download_grants.id":{"type":"uuid","default":"gen_random_uuid()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"I