ECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_delivery_events.render_job_id":{"type":"uuid","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.accounting_result":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.briefcase_item_id":{"type":"uuid","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.last_error_detail":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.output_byte_count":{"type":"integer","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:consumer_packet_payment_authority":{"consumer_packet_payment_authority(uuid,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.consumer_packet_payment_authority(p_briefcase_item_id uuid, p_consumer_auth_user_id uuid)\n RETURNS TABLE(valid boolean, reason text, provider_event_id text)\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_product text;\n  v_person uuid;\n  v_matter uuid;\nbegin\n  if to_regclass(''public.consumer_briefcase_items'') is null then\n    return query select false, ''no_payment_storage''::text, null::text;\n    return;\n  end if;\n  execute\n    ''select b.payment_product_id, b.payment_person_id, b.payment_matter_id\n       from public.consumer_briefcase_items b where b.id = $1''\n  into v_product, v_person, v_matter\n  using p_briefcase_item_id;\n  return query select * from public.consumer_packet_payment_authority(\n    p_briefcase_item_id, p_consumer_auth_user_id, v_product, v_person, v_matter\n  );\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true},"consumer_packet_payment_authority(uuid,uuid,text,uuid,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.consumer_packet_payment_authority(p_briefcase_item_id uuid, p_consumer_auth_user_id uuid, p_product_id text, p_person_id uuid, p_matter_id uuid)\n RETURNS TABLE(valid boolean, reason text, provider_event_id text)\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_status text;\n  v_amount integer;\n  v_regular integer;\n  v_discount integer;\n  v_currency text;\n  v_owner uuid;\n  v_event text;\n  v_authority text;\n  v_session text;\n  v_product text;\n  v_person uuid;\n  v_matter uuid;\nbegin\n  if p_briefcase_item_id is null then return query select false, ''no_briefcase_item''::text, null::text; return; end if;\n  if p_consumer_auth_user_id is null then return query select false, ''no_consumer_binding''::text, null::text; return; end if;\n  if to_regclass(''public.consumer_briefcase_items'') is null then return query select false, ''no_payment_storage''::text, null::text; return; end if;\n\n  execute\n    ''select b.payment_status, b.amount_cents, b.regular_price_cents, b.discount_cents,\n            b.currency, b.user_id, b.provider_event_id, b.payment_authority,\n            b.checkout_session_id, b.payment_product_id, b.payment_person_id, b.payment_matter_id\n       from public.consumer_briefcase_items b where b.id = $1''\n  into v_status, v_amount, v_regular, v_discount, v_currency, v_owner, v_event,\n       v_authority, v_session, v_product, v_person, v_matter\n  using p_briefcase_item_id;\n\n  if v_status is null and v_owner is null then return query select false, ''item_not_found''::text, null::text; return; end if;\n  if v_owner is distinct from p_consumer_auth_user_id then return query select false, ''owner_mismatch''::text, null::text; return; end if;\n  if v_status is distinct from ''paid'' then return query select false, (''payment_status_'' || coalesce(v_status, ''null''))::text, null::text; return; end if;\n  if v_regular is distinct from 5000\n     or v_discount is null or v_discount < 0 or v_discount > v_regular\n     or v_amount is distinct from (v_regular - v_discount) then\n    return query select false, ''amount_not_product_price''::text, null::text; return;\n  end if;\n  if lower(coalesce(v_currency, '''')) <> ''usd'' then return query select false, ''currency_not_usd''::text, null::text; return; end if;\n  if v_authority is null or nullif(trim(coalesce(v_event, '''')), '''') is null then return query select false, ''no_server_payment_evidence''::text, null::text; return; end if;\n  if nullif(trim(coalesce(v_session, '''')), '''') is null then return query select false, ''no_checkout_session''::text, null::text; return; end if;\n  if v_product is distinct from p_product_id or p_product_id is distinct from ''expungement_packet'' then return query select false, ''product_mismatch''::text, null::text; return; end if;\n  if v_person is distinct from p_person_id then return query select false, ''person_mismatch''::text, null::text; return; end if;\n  if v_matter is distinct from p_matter_id or p_matter_id is distinct from public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id) then return query select false, ''matter_mismatch''::text, null::text; return; end if;\n\n  return query select true, ''authorized''::text, v_event;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:replace_consumer_checkout_session":{"replace_consumer_checkout_session(uuid,uuid,text,text,text,text,uuid,uuid,text)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.replace_consumer_checkout_session(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid, p_expected_checkout_session_id text, p_checkout_session_id text, p_payment_provider text, p_product_id text, p_person_id uuid, p_matter_id uuid, p_expected_verification_hash text)\n RETURNS TABLE(ok boolean, reason text, briefcase_item_id uuid, checkout_session_id text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_item public.consumer_briefcase_items%rowtype;\n  v_hash text;\nbegin\n  if nullif(trim(coalesce(p_expected_checkout_session_id, '''')), '''') is null\n     or nullif(trim(coalesce(p_checkout_session_id, '''')), '''') is null\n     or p_expected_checkout_session_id = p_checkout_session_id then\n    return query select false, ''checkout_replacement_invalid''::text, p_briefcase_item_id, null::text; return;\n  end if;\n\n  -- Same lock order as the verification and payment authorities: item first.\n  select * into v_item from public.consumer_briefcase_items i\n    where i.id = p_briefcase_item_id for update;\n  if not found or p_consumer_auth_user_id is null\n     or v_item.user_id is distinct from p_consumer_auth_user_id then\n    return query select false, ''item_not_found''::text, null::uuid, null::text; return;\n  end if;\n\n  if v_item.payment_status = ''paid'' then\n    return query select false, ''already_paid''::text, p_briefcase_item_id, v_item.checkout_session_id; return;\n  end if;\n  -- Refunded/unknown states are not unpaid. Zero-dollar completed orders and\n  -- partial server evidence remain protected even before payment_status catches up.\n  if v_item.payment_status is distinct from ''unpaid''\n     or v_item.packet_status is distinct from ''not_started''\n     or v_item.provider_event_id is not null\n     or v_item.payment_intent_id is not null\n     or v_item.payment_authority is not null\n     or v_item.payment_recorded_at is not null\n     or v_item.payment_recorded_by is not null\n     or v_item.receipt_url is not null\n     or v_item.amount_cents is not null\n     or exists (select 1 from public.consumer_packet_payment_consumption c\n       where c.consumer_briefcase_item_id = p_briefcase_item_id)\n     or exists (select 1 from public.packet_render_jobs j\n       where j.briefcase_item_id = p_briefcase_item_id)\n     or exists (select 1 from public.processed_stripe_events e\n       where e.related_object_id in (v_item.checkout_session_id, p_checkout_session_id)) then\n    return query select false, ''checkout_payment_evidence_present''::text, p_briefcase_item_id, v_item.checkout_session_id; return;\n  end if;\n\n  select v.verification_hash into v_hash from public.consumer_packet_verifications v\n    where v.briefcase_item_id = p_briefcase_item_id and v.status = ''verified'' for update;\n  if v_hash is null or p_expected_verification_hash is null\n     or p_expected_verification_hash !~ ''^[0-9a-f]{64}$''\n     or v_hash is distinct from p_expected_verification_hash then\n    return query select false, ''verification_changed''::text, p_briefcase_item_id, null::text; return;\n  end if;\n\n  -- A replacement changes only the Session, never who/what the order belongs to.\n  if v_item.payment_allowed is not true\n     or p_product_id is distinct from public.expungement_packet_product_id()\n     or v_item.payment_product_id is distinct from p_product_id\n     or p_person_id is null or v_item.payment_person_id is distinct from p_person_id\n     or p_matter_id is distinct from public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id)\n     or v_item.payment_matter_id is distinct from p_matter_id\n     or p_payment_provider is distinct from ''stripe''\n     or v_item.payment_provider is distinct from p_payment_provider then\n    return query select false, ''checkout_binding_invalid''::text, p_briefcase_item_id, null::text; return;\n  end if;\n\n  if exists (select 1 from public.consumer_briefcase_items i\n    where i.checkout_session_id = p_checkout_session_id and i.id <> p_briefcase_item_id) then\n    return query select false, ''checkout_session_in_use''::text, p_briefcase_item_id, null::text; return;\n  end if;\n  if v_item.checkout_session_id is distinct from p_expected_checkout_session_id then\n    return query select false, ''checkout_replacement_conflict''::text, p_briefcase_item_id, v_item.checkout_session_id; return;\n  end if;\n\n  -- Never clear or rewrite payment evidence, including when it is NULL today.\n  update public.consumer_briefcase_items i set\n    checkout_session_id = p_checkout_session_id, updated_at = now()\n    where i.id = p_briefcase_item_id and i.checkout_session_id = p_expected_checkout_session_id;\n  return query select true, ''replaced''::text, p_briefcase_item_id, p_checkout_session_id;\nexception when unique_violation then\n  -- Another item won the unique Session claim after the pre-check. PostgreSQL\n  -- rolls this block back, preserving this item''s predecessor and all evidence.\n  return query select false, ''checkout_session_in_use''::text, p_briefcase_item_id, null::text;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:sponsored_packet_render_authority":{"sponsored_packet_render_authority(text,uuid,uuid,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.sponsored_packet_render_authority(p_route_key text, p_session_id uuid, p_briefcase_item_id uuid, p_consumer_auth_user_id uuid)\n RETURNS TABLE(valid boolean, reason text, partner_slug text, partner_id uuid, clinic_event_id uuid, clinic_case_id uuid)\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_route public.sponsored_packet_render_routes%rowtype;\n  v_item public.consumer_briefcase_items%rowtype;\n  v_source public.consumer_pending_screening_results%rowtype;\n  v_session public.screening_sessions%rowtype;\n  v_case public.clinic_cases%rowtype;\n  v_event public.clinic_events%rowtype;\n  v_partner_id uuid;\nbegin\n  if p_route_key is null or p_session_id is null\n     or p_briefcase_item_id is null or p_consumer_auth_user_id is null then\n    return query select false, ''invalid_input''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  select * into v_route from public.sponsored_packet_render_routes r\n   where r.route_key = p_route_key and r.active;\n  if not found then\n    return query select false, ''route_not_registered''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  select * into v_item from public.consumer_briefcase_items i\n   where i.id = p_briefcase_item_id and i.user_id = p_consumer_auth_user_id;\n  if not found then\n    return query select false, ''wrong_owner''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_item.jurisdiction is distinct from v_route.jurisdiction then\n    return query select false, ''wrong_jurisdiction_or_route''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  select * into v_source from public.consumer_pending_screening_results p\n   where p.pending_id = v_item.source_pending_result_id;\n  if not found or v_source.status <> ''CLAIMED''\n     or v_source.claimed_matter_id is distinct from v_item.id\n     or v_source.claimed_user_id is distinct from v_item.user_id then\n    return query select false, ''wrong_item''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_source.anonymous_session_id is distinct from p_session_id then\n    return query select false, ''wrong_session''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_source.product <> ''rcap_partner''\n     or v_source.partner_slug is distinct from v_route.partner_slug then\n    return query select false, ''wrong_partner''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_source.jurisdiction is distinct from v_route.jurisdiction then\n    return query select false, ''wrong_jurisdiction_or_route''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  select * into v_session from public.screening_sessions s where s.session_id = p_session_id;\n  if not found or v_session.flow_mode <> ''rcap'' or v_session.partner_benefit_active is not true then\n    return query select false, ''sponsorship_inactive''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_session.partner_slug is distinct from v_route.partner_slug then\n    return query select false, ''wrong_partner''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_session.jurisdiction is distinct from v_route.jurisdiction then\n    return query select false, ''wrong_jurisdiction_or_route''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  select c.* into v_case from public.clinic_cases c\n   where c.event_id = v_source.event_id\n     and c.participant_user_id = v_item.user_id\n     and c.screening_session_id = p_session_id\n     and c.matter_id = v_item.id;\n  if not found then\n    return query select false, ''clinic_scope_mismatch''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_case.jurisdiction is distinct from v_route.jurisdiction or v_case.route_disposition <> ''packet'' then\n    return query select false, ''wrong_jurisdiction_or_route''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  select * into v_event from public.clinic_events e where e.id = v_case.event_id;\n  if not found\n     or v_event.partner_slug is distinct from v_route.partner_slug\n     or v_event.program_key is distinct from v_route.program_key\n     or (v_route.clinic_event_name is not null and v_event.name is distinct from v_route.clinic_event_name) then\n    return query select false, ''clinic_scope_mismatch''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_event.jurisdiction is distinct from v_route.jurisdiction then\n    return query select false, ''wrong_jurisdiction_or_route''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n  if v_event.status <> ''published''\n     or v_event.sponsorship_allocation is null or v_event.sponsorship_allocation < 0 then\n    return query select false, ''sponsorship_inactive''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  select pr.id into v_partner_id from public.partner_records pr\n   where pr.partner_slug = v_route.partner_slug;\n  if v_partner_id is null then\n    return query select false, ''no_entitlement''::text, null::text, null::uuid, null::uuid, null::uuid;\n    return;\n  end if;\n\n  return query select true, null::text, v_route.partner_slug, v_partner_id, v_event.id, v_case.id;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"column:consumer_briefcase_items.amount_cents":{"type":"integer","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.jurisdiction":{"type":"text","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.summary_json":{"type":"jsonb","default":"''{}''::jsonb","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:partner_packet_entitlement.created_at":{"type":"timestamp with time zone","default":"now()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:partner_packet_entitlement.expires_at":{"type":"timestamp with time zone","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:partner_packet_entitlement.packet_cap":{"type":"integer","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:partner_packet_entitlement.partner_id":{"type":"uuid","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:partner_packet_entitlement.updated_at":{"type":"timestamp with time zone","default":"now()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:sponsored_packet_render_routes.active":{"type":"boolean","default":"true","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:guard_packet_render_job_transition":{"guard_packet_render_job_transition()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":true,"service_role":true,"authenticated":true,"rcap_render_worker":true,"rcap_packet_delivery":true},"definition":"CREATE OR REPLACE FUNCTION public.guard_packet_render_job_transition()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_authority text := public.rcap_packet_mutation_authority();\nbegin\n  if new.status <> old.status then\n    if not (\n      (old.status = ''queued'' and new.status in (''claimed'', ''failed''))\n      or (old.status = ''claimed'' and new.status in (''rendering'', ''failed'', ''queued''))\n      or (old.status = ''rendering'' and new.status in (''validating'', ''failed''))\n      or (old.status = ''validating'' and new.status in (''artifact_validated'', ''failed''))\n      or (old.status = ''artifact_validated'' and new.status = ''delivered'')\n      or (old.status = ''failed'' and new.status = ''queued'')\n    ) then\n      raise exception ''packet_render_jobs: illegal transition % -> %'', old.status, new.status;\n    end if;\n\n    if old.status = ''queued'' and new.status = ''claimed''\n       and v_authority <> ''claim_packet_render_job'' then\n      raise exception ''packet_render_jobs: claiming requires claim_packet_render_job'';\n    end if;\n\n    if new.status = ''artifact_validated''\n       and v_authority <> ''finalize_packet_render_job'' then\n      raise exception ''packet_render_jobs: artifact_validated is written only by finalize_packet_render_job'';\n    end if;\n\n    if new.status = ''delivered''\n       and v_authority <> ''record_packet_delivery_event'' then\n      raise exception ''packet_render_jobs: delivered is written only by record_packet_delivery_event'';\n    end if;\n\n    if old.status = ''failed'' and new.status = ''queued'' then\n      if v_authority not in (''requeue_retryable_packet_render_jobs'', ''requeue_packet_render_job_manual'') then\n        raise exception ''packet_render_jobs: failed jobs return to queued only through a requeue function'';\n      end if;\n      if old.failure_disposition = ''terminal''\n         and v_authority <> ''requeue_packet_render_job_manual'' then\n        raise exception ''packet_render_jobs: a terminal failure is requeued only manually with recorded authorization'';\n      end if;\n    end if;\n\n    if new.status in (''rendering'', ''validating'')\n       and v_authority not in (''start_packet_render'', ''start_packet_validation'') then\n      raise exception ''packet_render_jobs: worker transitions require their canonical functions'';\n    end if;\n\n    if new.status = ''failed''\n       and v_authority not in (''fail_packet_render_job'', ''release_expired_packet_render_claims'', ''finalize_packet_render_job'') then\n      raise exception ''packet_render_jobs: failure is recorded only through its canonical functions'';\n    end if;\n\n    -- Per-state timestamps, carried over from the phase-49 guard.\n    new.claimed_at            := case when new.status = ''claimed''            then now() else new.claimed_at end;\n    new.rendering_at          := case when new.status = ''rendering''          then now() else new.rendering_at end;\n    new.validating_at         := case when new.status = ''validating''         then now() else new.validating_at end;\n    new.artifact_validated_at := case when new.status = ''artifact_validated'' then now() else new.artifact_validated_at end;\n    new.delivered_at          := case when new.status = ''delivered''          then now() else new.delivered_at end;\n\n    if new.status = ''queued'' then\n      new.claimed_by := null;\n      new.claimed_at := null;\n    end if;\n  end if;\n\n  if (new.delivery_eligibility is distinct from old.delivery_eligibility\n      or new.accounting_result is distinct from old.accounting_result\n      or new.credit_ledger_id is distinct from old.credit_ledger_id)\n     and v_authority <> ''finalize_packet_render_job'' then\n    raise exception ''packet_render_jobs: accounting fields are written only by finalize_packet_render_job'';\n  end if;\n\n  if (new.output_storage_path is distinct from old.output_storage_path\n      or new.output_sha256 is distinct from old.output_sha256\n      or new.normalized_output_sha256 is distinct from old.normalized_output_sha256\n      or new.container_digest is distinct from old.container_digest)\n     and v_authority <> ''finalize_packet_render_job'' then\n    raise exception ''packet_render_jobs: artifact evidence is written only by finalize_packet_render_job'';\n  end if;\n\n  if old.partner_id is not null and new.partner_id is distinct from old.partner_id then\n    raise exception ''packet_render_jobs: partner_id is immutable'';\n  end if;\n  if old.person_id is not null and new.person_id is distinct from old.person_id then\n    raise exception ''packet_render_jobs: person_id is immutable'';\n  end if;\n  if old.matter_id is not null and new.matter_id is distinct from old.matter_id then\n    raise exception ''packet_render_jobs: matter_id is immutable'';\n  end if;\n\n  new.updated_at := now();\n  return new;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":true,"securityDefiner":false}},"functions:rcap_participant_erasure_authority":{"rcap_participant_erasure_authority()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.rcap_participant_erasure_authority()\n RETURNS text\n LANGUAGE sql\n STABLE\n SET search_path TO ''''\nAS $function$\n  select coalesce(current_setting(''rcap.participant_erasure_authority'', true), '''');\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":false}},"policies:consumer_packet_artifact_provenance":[],"policies:consumer_packet_payment_consumption":[],"column:consumer_briefcase_items.packet_status":{"type":"text","default":"''not_started''::text","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.pathway_label":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_payment_consumption.id":{"type":"uuid","default":"gen_random_uuid()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_verifications.revision":{"type":"integer","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_delivery_events.request_context":{"type":"jsonb","default":"''{}''::jsonb","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.failure_disposition":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.output_storage_path":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.sponsored_route_key":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:partner_packet_entitlement.overage_cap":{"type":"integer","default":"0","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:bind_consumer_checkout_verification":{"bind_consumer_checkout_verification(uuid,uuid,text,text,text,uuid,uuid,text)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.bind_consumer_checkout_verification(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid, p_checkout_session_id text, p_payment_provider text, p_product_id text, p_person_id uuid, p_matter_id uuid, p_expected_verification_hash text)\n RETURNS TABLE(ok boolean, reason text, briefcase_item_id uuid, checkout_session_id text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_item public.consumer_briefcase_items%rowtype;\n  v_hash text;\n  v_other uuid;\nbegin\n  select * into v_item from public.consumer_briefcase_items i\n   where i.id = p_briefcase_item_id for update;\n  if not found or v_item.user_id is distinct from p_consumer_auth_user_id then\n    return query select false, ''item_not_found''::text, null::uuid, null::text; return;\n  end if;\n  select v.verification_hash into v_hash from public.consumer_packet_verifications v\n   where v.briefcase_item_id = p_briefcase_item_id and v.status = ''verified'' for update;\n  if v_hash is distinct from p_expected_verification_hash then\n    return query select false, ''verification_changed''::text, p_briefcase_item_id, null::text; return;\n  end if;\n  if v_item.payment_allowed is not true or v_item.payment_status = ''not_applicable''\n     or p_product_id is distinct from public.expungement_packet_product_id()\n     or p_matter_id is distinct from public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id)\n     or p_person_id is null or p_payment_provider not in (''stripe'', ''dry_run'')\n     or nullif(trim(coalesce(p_checkout_session_id, '''')), '''') is null then\n    return query select false, ''checkout_binding_invalid''::text, p_briefcase_item_id, null::text; return;\n  end if;\n  select i.id into v_other from public.consumer_briefcase_items i\n    where i.checkout_session_id = p_checkout_session_id and i.id <> p_briefcase_item_id limit 1;\n  if v_other is not null then\n    return query select false, ''checkout_session_in_use''::text, p_briefcase_item_id, null::text; return;\n  end if;\n  if v_item.checkout_session_id is not null and v_item.checkout_session_id <> p_checkout_session_id then\n    return query select false, ''checkout_binding_conflict''::text, p_briefcase_item_id, v_item.checkout_session_id; return;\n  end if;\n  update public.consumer_briefcase_items i set\n    checkout_session_id = p_checkout_session_id,\n    payment_provider = p_payment_provider,\n    payment_product_id = p_product_id,\n    payment_person_id = p_person_id,\n    payment_matter_id = p_matter_id,\n    payment_status = case when i.payment_status = ''paid'' then ''paid'' else ''unpaid'' end,\n    amount_cents = case when i.payment_status = ''paid'' then i.amount_cents else null end,\n    updated_at = now()\n  where i.id = p_briefcase_item_id;\n  return query select true, ''bound''::text, p_briefcase_item_id, p_checkout_session_id;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:packet_render_jobs_guard_transition":{},"column:consumer_briefcase_items.discount_cents":{"type":"integer","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.payment_status":{"type":"text","default":"''not_applicable''::text","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_verifications.matter_id":{"type":"uuid","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.delivery_eligibility":{"type":"text","default":"''not_evaluated''::text","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.sponsored_session_id":{"type":"uuid","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:partner_packet_entitlement.effective_at":{"type":"timestamp with time zone","default":"now()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:partner_packet_entitlement.pause_at_cap":{"type":"boolean","default":"true","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:authorize_consumer_artifact_download":{"authorize_consumer_artifact_download(uuid,uuid,text)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.authorize_consumer_artifact_download(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid, p_token_hash text)\n RETURNS TABLE(grant_id uuid, artifact_storage_path text, artifact_sha256 text, file_name text, content_type text, render_job_id uuid)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_grant public.consumer_artifact_download_grants%rowtype;\n  v_job uuid;\nbegin\n  select g.* into v_grant from public.consumer_artifact_download_grants g\n  join public.consumer_briefcase_items i\n    on i.id = g.briefcase_item_id and i.user_id = p_consumer_auth_user_id\n  join public.consumer_packet_artifact_provenance p\n    on p.briefcase_item_id = g.briefcase_item_id\n   and p.consumer_auth_user_id = g.consumer_auth_user_id\n   and p.matter_id = g.matter_id\n   and p.revision = g.artifact_revision\n   and p.verification_hash = g.verification_hash\n  join public.consumer_packet_verifications v\n    on v.briefcase_item_id = g.briefcase_item_id\n   and v.consumer_auth_user_id = g.consumer_auth_user_id\n   and v.status = ''verified''\n   and v.verification_hash = g.verification_hash\n  where g.token_hash = p_token_hash\n    and g.consumer_auth_user_id = p_consumer_auth_user_id\n    and g.briefcase_item_id = p_briefcase_item_id\n    and g.revoked_at is null\n    and g.expires_at > now()\n  for update of g;\n  if not found then return; end if;\n\n  -- Deterministic, grant-consistent provenance lookup. briefcase_item_id is\n  -- the primary key today, so at most one row can match — but future\n  -- per-revision provenance rows must not turn this into an arbitrary pick,\n  -- so the lookup is pinned to the grant''s owner, matter, revision and\n  -- verification hash, and ordered with an explicit LIMIT.\n  select p.render_job_id into v_job\n  from public.consumer_packet_artifact_provenance p\n  where p.briefcase_item_id = v_grant.briefcase_item_id\n    and p.consumer_auth_user_id = v_grant.consumer_auth_user_id\n    and p.matter_id = v_grant.matter_id\n    and p.revision = v_grant.artifact_revision\n    and p.verification_hash = v_grant.verification_hash\n  order by p.revision desc, p.render_job_id desc\n  limit 1;\n  update public.consumer_artifact_download_grants g set\n    download_count = g.download_count + 1,\n    last_downloaded_at = now()\n  where g.id = v_grant.id;\n  return query select v_grant.id, v_grant.artifact_storage_path,\n    v_grant.artifact_sha256, v_grant.file_name, v_grant.content_type, v_job;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:packet_render_jobs_paid_matter_guard":{"packet_render_jobs_paid_matter_guard()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":true,"service_role":true,"authenticated":true,"rcap_render_worker":true,"rcap_packet_delivery":true},"definition":"CREATE OR REPLACE FUNCTION public.packet_render_jobs_paid_matter_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_valid boolean;\n  v_reason text;\nbegin\n  if new.partner_id is not null then return new; end if;\n  select a.valid, a.reason into v_valid, v_reason\n    from public.consumer_packet_payment_authority(\n      new.consumer_briefcase_item_id,\n      new.consumer_auth_user_id,\n      public.expungement_packet_product_id(),\n      new.person_id,\n      new.matter_id\n    ) a;\n  if not coalesce(v_valid, false) then\n    raise exception ''packet_render_jobs: consumer payment binding refused (%)'', coalesce(v_reason, ''unknown'');\n  end if;\n  return new;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":true,"securityDefiner":true}},"functions:persist_consumer_packet_verification":{"persist_consumer_packet_verification(uuid,uuid,text,integer,jsonb,jsonb,text,jsonb,text,text,text,jsonb,timestamp with time zone)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.persist_consumer_packet_verification(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid, p_expected_prior_hash text, p_expected_prior_revision integer, p_answer_delta jsonb, p_packet_information_metadata jsonb, p_next_draft_hash text, p_next_draft_snapshot jsonb, p_next_verification_status text, p_next_verification_reason text, p_next_verification_hash text, p_next_verification_snapshot jsonb, p_next_verification_invalidated_at timestamp with time zone)\n RETURNS TABLE(status text, reason text, hash text, snapshot jsonb, draft_hash text, draft_snapshot jsonb, revision integer, invalidated_at text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_item public.consumer_briefcase_items%rowtype;\n  v_prior public.consumer_packet_verifications%rowtype;\n  v_next_revision integer;\n  v_verification_display jsonb;\nbegin\n  if p_consumer_auth_user_id is null or p_briefcase_item_id is null\n     or p_expected_prior_revision is null or p_expected_prior_revision < 0\n     or p_next_draft_hash !~ ''^[a-f0-9]{64}$''\n     or p_next_draft_snapshot ->> ''schemaVersion'' <> ''expungement-ai/protected-packet-draft/v1''\n     or p_next_verification_status not in (''unverified'', ''verified'', ''invalidated'')\n     or nullif(trim(coalesce(p_next_verification_reason, '''')), '''') is null\n     or coalesce(jsonb_typeof(p_answer_delta), '''') <> ''object''\n     or coalesce(jsonb_typeof(p_packet_information_metadata), '''') <> ''object'' then\n    return;\n  end if;\n  if (p_next_verification_status = ''verified'') is distinct from\n     coalesce((p_next_verification_hash ~ ''^[a-f0-9]{64}$''\n      and p_next_verification_snapshot ->> ''schemaVersion'' = ''expungement-ai/final-verification/v1''), false) then\n    return;\n  end if;\n  if p_next_verification_status <> ''verified''\n     and (p_next_verification_hash is not null or p_next_verification_snapshot is not null) then\n    return;\n  end if;\n\n  select * into v_item from public.consumer_briefcase_items i\n   where i.id = p_briefcase_item_id and i.user_id = p_consumer_auth_user_id for update;\n  if not found then return; end if;\n\n  select * into v_prior from public.consumer_packet_verifications v\n   where v.briefcase_item_id = p_briefcase_item_id for update;\n\n  if found then\n    if v_prior.consumer_auth_user_id is distinct from p_consumer_auth_user_id\n       or v_prior.revision is distinct from p_expected_prior_revision\n       or (case when v_prior.status = ''verified'' then v_prior.verification_hash else null end)\n          is distinct from p_expected_prior_hash then\n      return;\n    end if;\n    if p_next_draft_hash = v_prior.draft_hash\n       and p_next_verification_status = v_prior.status\n       and p_next_verification_hash is not distinct from v_prior.verification_hash\n       and p_next_draft_snapshot = v_prior.draft_snapshot\n       and p_next_verification_snapshot is not distinct from v_prior.verification_snapshot then\n      v_next_revision := v_prior.revision;\n    else\n      v_next_revision := v_prior.revision + 1;\n    end if;\n    update public.consumer_packet_verifications v set\n      status = p_next_verification_status,\n      reason = p_next_verification_reason,\n      verification_hash = p_next_verification_hash,\n      verification_snapshot = p_next_verification_snapshot,\n      draft_hash = p_next_draft_hash,\n      draft_snapshot = p_next_draft_snapshot,\n      revision = v_next_revision,\n      invalidated_at = p_next_verification_invalidated_at,\n      updated_at = now()\n    where v.briefcase_item_id = p_briefcase_item_id;\n  else\n    if p_expected_prior_revision <> 0 or p_expected_prior_hash is not null then return; end if;\n    v_next_revision := case when p_next_verification_status = ''unverified'' then 0 else 1 end;\n    insert into public.consumer_packet_verifications (\n      briefcase_item_id, consumer_auth_user_id, matter_id, status, reason,\n      verification_hash, verification_snapshot, draft_hash, draft_snapshot,\n      revision, invalidated_at\n    ) values (\n      p_briefcase_item_id, p_consumer_auth_user_id,\n      public.consumer_matter_id_for_briefcase_item(p_briefcase_item_id),\n      p_next_verification_status, p_next_verification_reason,\n      p_next_verification_hash, p_next_verification_snapshot,\n      p_next_draft_hash, p_next_draft_snapshot, v_next_revision,\n      p_next_verification_invalidated_at\n    );\n  end if;\n\n  v_verification_display := jsonb_strip_nulls(jsonb_build_object(\n    ''status'', p_next_verification_status,\n    ''reason'', p_next_verification_reason,\n    ''hash'', p_next_verification_hash,\n    ''snapshot'', p_next_verification_snapshot,\n    ''draftHash'', p_next_draft_hash,\n    ''draftSnapshot'', p_next_draft_snapshot,\n    ''revision'', v_next_revision,\n    ''invalidatedAt'', p_next_verification_invalidated_at\n  ));\n  update public.consumer_briefcase_items i set\n    summary_json = jsonb_set(\n      coalesce(i.summary_json, ''{}''::jsonb),\n      ''{commercialFlow}'',\n      coalesce(i.summary_json -> ''commercialFlow'', ''{}''::jsonb)\n        || jsonb_build_object(\n          ''packetInformation'', p_packet_information_metadata,\n          ''verification'', v_verification_display\n        ),\n      true\n    ),\n    packet_status = case\n      when p_next_verification_status <> ''verified'' and i.packet_status in (''ready'', ''downloaded'') then ''pending''\n      else i.packet_status\n    end,\n    updated_at = now()\n  where i.id = p_briefcase_item_id;\n\n  return query select v.status, v.reason, v.verification_hash, v.verification_snapshot,\n      v.draft_hash, v.draft_snapshot, v.revision,\n      case when v.invalidated_at is null then null else v.invalidated_at::text end\n    from public.consumer_packet_verifications v\n    where v.briefcase_item_id = p_briefcase_item_id;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:release_expired_packet_render_claims":{"release_expired_packet_render_claims()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":true,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.release_expired_packet_render_claims()\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_count integer;\nbegin\n  perform set_config(''rcap.packet_mutation_authority'', ''release_expired_packet_render_claims'', true);\n  update public.packet_render_jobs j\n  set retry_reconciliation_history = j.retry_reconciliation_history || jsonb_build_array(jsonb_build_object(\n        ''authority'', ''release_expired_packet_render_claims'', ''at'', now(),\n        ''reason'', case when j.attempt_count >= j.max_attempts then ''attempt_limit_reached'' else ''lease_expired'' end,\n        ''prior_status'', j.status, ''prior_failure_disposition'', j.failure_disposition,\n        ''prior_error_code'', j.error_code, ''attempt_count'', j.attempt_count,\n        ''max_attempts'', j.max_attempts, ''next_attempt_at'', j.next_attempt_at,\n        ''claim_expires_at'', j.claim_expires_at, ''claimed_by'', j.claimed_by, ''claimed_at'', j.claimed_at)),\n      status = case when j.status = ''claimed'' and j.attempt_count < j.max_attempts then ''queued'' else ''failed'' end,\n      failure_disposition = case\n        when j.status = ''claimed'' and j.attempt_count < j.max_attempts then null\n        when j.attempt_count < j.max_attempts then ''retryable'' else ''terminal'' end,\n      error_code = case when j.status = ''claimed'' and j.attempt_count < j.max_attempts then j.error_code\n                        else coalesce(j.error_code, ''timeout'') end,\n      last_error_detail = coalesce(j.last_error_detail,\n        case when j.attempt_count >= j.max_attempts then ''attempt limit reached during lease housekeeping''\n             else ''claim lease expired before the worker finished'' end),\n      next_attempt_at = case\n        when j.attempt_count >= j.max_attempts then null\n        when j.status = ''claimed'' then j.next_attempt_at\n        else now() + make_interval(secs => least(3600, 30 * power(2, j.attempt_count))::integer) end,\n      claim_expires_at = null,\n      fencing_token = null\n  where (j.status in (''claimed'', ''rendering'', ''validating'')\n         and j.claim_expires_at is not null and j.claim_expires_at < now())\n     or (j.status = ''queued'' and j.attempt_count >= j.max_attempts);\n  get diagnostics v_count = row_count;\n  perform set_config(''rcap.packet_mutation_authority'', '''', true);\n  return v_count;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:requeue_retryable_packet_render_jobs":{"requeue_retryable_packet_render_jobs()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":true,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.requeue_retryable_packet_render_jobs()\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_key record;\n  v_job public.packet_render_jobs%rowtype;\n  v_winner uuid;\n  v_live uuid;\n  v_reason text;\n  v_constraint text;\n  v_sqlstate text;\n  v_schema text;\n  v_table text;\n  v_count integer := 0;\nbegin\n  perform set_config(''rcap.packet_mutation_authority'', ''requeue_retryable_packet_render_jobs'', true);\n  for v_key in\n    select distinct packet_id, input_hash from public.packet_render_jobs\n    where status = ''failed'' and failure_disposition = ''retryable''\n    order by packet_id, input_hash\n  loop\n    -- Housekeepers serialize by logical input, not the whole queue. A busy input\n    -- does not block unrelated inputs. The unique index also arbitrates enqueue.\n    if not pg_try_advisory_xact_lock(hashtextextended(v_key.packet_id::text || '':'' || v_key.input_hash, 0)) then\n      continue;\n    end if;\n    select id into v_live from public.packet_render_jobs\n    where packet_id = v_key.packet_id and input_hash = v_key.input_hash and status <> ''failed'';\n    select id into v_winner from public.packet_render_jobs\n    where packet_id = v_key.packet_id and input_hash = v_key.input_hash\n      and status = ''failed'' and failure_disposition = ''retryable'' and attempt_count < max_attempts\n      and next_attempt_at is not null and isfinite(next_attempt_at)\n    order by created_at, id limit 1;\n\n    for v_job in\n      select * from public.packet_render_jobs\n      where packet_id = v_key.packet_id and input_hash = v_key.input_hash\n        and status = ''failed'' and failure_disposition = ''retryable''\n      order by created_at, id for update\n    loop\n      v_sqlstate := null;\n      v_constraint := null;\n      v_reason := case\n        when v_job.attempt_count >= v_job.max_attempts then ''attempt_limit_reached''\n        when v_live is not null then ''live_sibling_exists''\n        when v_job.next_attempt_at is null or not isfinite(v_job.next_attempt_at) then ''canonical_retry_time_missing''\n        when v_job.id is distinct from v_winner then ''duplicate_retry_superseded''\n        else null end;\n      if v_reason is null and v_job.next_attempt_at <= now() then\n        begin\n          update public.packet_render_jobs j\n          set status = ''queued'', failure_disposition = null,\n              retry_reconciliation_history = j.retry_reconciliation_history || jsonb_build_array(jsonb_build_object(\n                ''authority'', ''requeue_retryable_packet_render_jobs'', ''at'', now(), ''reason'', ''canonical_retry_due'',\n                ''prior_status'', j.status, ''prior_failure_disposition'', j.failure_disposition,\n                ''prior_error_code'', j.error_code, ''attempt_count'', j.attempt_count,\n                ''max_attempts'', j.max_attempts, ''next_attempt_at'', j.next_attempt_at,\n                ''claimed_by'', j.claimed_by, ''claimed_at'', j.claimed_at))\n          where j.id = v_job.id;\n          v_count := v_count + 1;\n          v_live := v_job.id;\n        exception when unique_violation then\n          get stacked diagnostics v_constraint = constraint_name, v_sqlstate = returned_sqlstate,\n            v_schema = schema_name, v_table = table_name;\n          if v_sqlstate = ''23505'' and v_constraint = ''packet_render_jobs_input_hash_live_unique''\n             and v_schema = ''public'' and v_table = ''packet_render_jobs'' then\n            -- A concurrent enqueue won. Only this row''s attempted requeue is\n            -- rolled back; other logical inputs still make progress.\n            select id into v_live from public.packet_render_jobs\n            where packet_id = v_key.packet_id and input_hash = v_key.input_hash and status <> ''failed'';\n            if v_live is null then raise; end if;\n            v_reason := ''concurrent_live_sibling_won'';\n          else\n            -- A trigger or another relation''s constraint is not this race.\n            raise;\n          end if;\n        end;\n      end if;\n      if v_reason is not null then\n        update public.packet_render_jobs j\n        set failure_disposition = ''terminal'', next_attempt_at = null,\n            retry_reconciliation_history = j.retry_reconciliation_history || jsonb_build_array(jsonb_build_object(\n              ''authority'', ''requeue_retryable_packet_render_jobs'', ''at'', now(), ''reason'', v_reason,\n              ''canonical_job_id'', coalesce(v_live, v_winner),\n              ''requeue_sqlstate'', v_sqlstate, ''requeue_constraint'', v_constraint,\n              ''prior_status'', j.status, ''prior_failure_disposition'', j.failure_disposition,\n              ''prior_error_code'', j.error_code, ''attempt_count'', j.attempt_count,\n              ''max_attempts'', j.max_attempts, ''next_attempt_at'', j.next_attempt_at,\n                ''claimed_by'', j.claimed_by, ''claimed_at'', j.claimed_at))\n        where j.id = v_job.id;\n      end if;\n    end loop;\n  end loop;\n  perform set_config(''rcap.packet_mutation_authority'', '''', true);\n  return v_count;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"column:consumer_briefcase_items.next_steps_json":{"type":"jsonb","default":"''[]''::jsonb","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.payment_allowed":{"type":"boolean","default":"false","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_verifications.created_at":{"type":"timestamp with time zone","default":"now()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false