false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:set_partner_packet_entitlement_updated_at":{"set_partner_packet_entitlement_updated_at()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":true,"service_role":true,"authenticated":true,"rcap_render_worker":true,"rcap_packet_delivery":true},"definition":"CREATE OR REPLACE FUNCTION public.set_partner_packet_entitlement_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":true,"securityDefiner":false}},"column:consumer_packet_artifact_provenance.matter_id":{"type":"uuid","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_payment_consumption.matter_id":{"type":"uuid","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_payment_consumption.person_id":{"type":"uuid","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.consumer_briefcase_item_id":{"type":"uuid","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.consumer_verification_hash":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:consumer_payment_consumption_binding_guard":{"consumer_payment_consumption_binding_guard()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":true,"service_role":true,"authenticated":true,"rcap_render_worker":true,"rcap_packet_delivery":true},"definition":"CREATE OR REPLACE FUNCTION public.consumer_payment_consumption_binding_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_valid boolean;\n  v_reason text;\n  v_session text;\nbegin\n  if tg_op = ''UPDATE'' then\n    if new.consumer_briefcase_item_id is distinct from old.consumer_briefcase_item_id\n       or new.consumer_auth_user_id is distinct from old.consumer_auth_user_id\n       or new.provider_event_id is distinct from old.provider_event_id\n       or new.person_id is distinct from old.person_id\n       or new.matter_id is distinct from old.matter_id\n       or new.product_id is distinct from old.product_id\n       or new.checkout_session_id is distinct from old.checkout_session_id\n       or new.amount_cents is distinct from old.amount_cents\n       or new.currency is distinct from old.currency then\n      raise exception ''consumer payment consumption binding is immutable'';\n    end if;\n    -- A refund removes authority for new work, but Phase 52 deliberately keeps\n    -- an already-delivered artifact and its consumption evidence. A benign\n    -- maintenance update therefore must not re-run current payment authority.\n    return new;\n  end if;\n\n  select a.valid, a.reason, b.checkout_session_id\n    into v_valid, v_reason, v_session\n    from public.consumer_briefcase_items b\n    cross join lateral public.consumer_packet_payment_authority(\n      new.consumer_briefcase_item_id,\n      new.consumer_auth_user_id,\n      public.expungement_packet_product_id(),\n      new.person_id,\n      new.matter_id\n    ) a\n   where b.id = new.consumer_briefcase_item_id;\n  if not coalesce(v_valid, false) then\n    raise exception ''consumer payment consumption binding refused (%)'', coalesce(v_reason, ''unknown'');\n  end if;\n  new.product_id := public.expungement_packet_product_id();\n  new.checkout_session_id := v_session;\n  new.amount_cents := 5000;\n  new.currency := ''usd'';\n  return new;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":true,"securityDefiner":true}},"functions:get_consumer_packet_verification_authority":{"get_consumer_packet_verification_authority(uuid,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.get_consumer_packet_verification_authority(p_consumer_auth_user_id uuid, p_briefcase_item_id uuid)\n RETURNS TABLE(status text, reason text, hash text, snapshot jsonb, draft_hash text, draft_snapshot jsonb, revision integer, invalidated_at text)\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\n  select v.status, v.reason, v.verification_hash, v.verification_snapshot,\n         v.draft_hash, v.draft_snapshot, v.revision,\n         case when v.invalidated_at is null then null else v.invalidated_at::text end\n  from public.consumer_packet_verifications v\n  join public.consumer_briefcase_items i on i.id = v.briefcase_item_id\n  where v.briefcase_item_id = p_briefcase_item_id\n    and v.consumer_auth_user_id = p_consumer_auth_user_id\n    and i.user_id = p_consumer_auth_user_id;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"functions:publish_validated_consumer_render_artifact":{"publish_validated_consumer_render_artifact()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.publish_validated_consumer_render_artifact()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_verification text;\n  v_valid_payment boolean;\n  v_artifact jsonb;\nbegin\n  if new.partner_id is not null\n     or new.consumer_auth_user_id is null\n     or new.consumer_briefcase_item_id is null\n     or new.matter_id is null\n     or new.consumer_verification_hash is null\n     or new.status not in (''artifact_validated'', ''delivered'')\n     or new.delivery_eligibility <> ''eligible''\n     or new.accounting_result not in (''zero_charge'', ''consumed'', ''already_consumed'', ''overage_consumed'')\n     or new.output_storage_path is null\n     or new.output_sha256 !~ ''^[a-f0-9]{64}$'' then\n    return new;\n  end if;\n\n  select v.verification_hash into v_verification\n  from public.consumer_packet_verifications v\n  where v.briefcase_item_id = new.consumer_briefcase_item_id\n    and v.consumer_auth_user_id = new.consumer_auth_user_id\n    and v.status = ''verified''\n  for update;\n  if v_verification is null or v_verification is distinct from new.consumer_verification_hash then\n    return new;\n  end if;\n\n  select a.valid into v_valid_payment\n  from public.consumer_packet_payment_authority(\n    new.consumer_briefcase_item_id,\n    new.consumer_auth_user_id,\n    public.expungement_packet_product_id(),\n    new.person_id,\n    new.matter_id\n  ) a;\n  if not coalesce(v_valid_payment, false) then return new; end if;\n\n  if new.output_storage_path not like\n       ''packet-artifacts/consumer/'' || new.matter_id::text || ''/'' || new.id::text || ''/'' || new.output_sha256 || ''.pdf''\n     or position(''..'' in new.output_storage_path) > 0 then\n    return new;\n  end if;\n\n  v_artifact := jsonb_build_object(\n    ''provider'', ''rcap_durable_render_v1'',\n    ''source'', ''verified_render_job'',\n    ''packetId'', new.packet_id,\n    ''renderJobId'', new.id,\n    ''artifactSha256'', new.output_sha256,\n    ''storagePath'', new.output_storage_path,\n    ''fileName'', ''record-clearing-packet.pdf'',\n    ''contentType'', ''application/pdf'',\n    ''generatedAt'', new.artifact_validated_at,\n    ''downloadPath'', ''/api/expungement-ai/packet/download-link?briefcaseItemId='' || new.consumer_briefcase_item_id::text,\n    ''pageCount'', new.page_count\n  );\n\n  insert into public.consumer_packet_artifact_provenance(\n    briefcase_item_id, consumer_auth_user_id, matter_id, render_job_id,\n    verification_hash, entitlement_source, artifact\n  ) values (\n    new.consumer_briefcase_item_id, new.consumer_auth_user_id, new.matter_id,\n    new.id, new.consumer_verification_hash, ''consumer_payment'', v_artifact\n    ) on conflict on constraint consumer_packet_artifact_provenance_pkey do update\n    set render_job_id = excluded.render_job_id,\n        verification_hash = excluded.verification_hash,\n        artifact = excluded.artifact\n    where consumer_packet_artifact_provenance.consumer_auth_user_id = excluded.consumer_auth_user_id\n      and consumer_packet_artifact_provenance.matter_id = excluded.matter_id\n      and consumer_packet_artifact_provenance.entitlement_source = excluded.entitlement_source\n      and consumer_packet_artifact_provenance.verification_hash is distinct from excluded.verification_hash;\n\n  if exists (\n    select 1 from public.consumer_packet_artifact_provenance p\n    where p.briefcase_item_id = new.consumer_briefcase_item_id\n      and p.consumer_auth_user_id = new.consumer_auth_user_id\n      and p.matter_id = new.matter_id\n      and p.render_job_id = new.id\n      and p.verification_hash = new.consumer_verification_hash\n      and p.artifact = v_artifact\n  ) then\n    update public.consumer_briefcase_items i\n    set artifact_refs_json = v_artifact || case\n          when i.artifact_refs_json ? ''attribution''\n            then jsonb_build_object(''attribution'', i.artifact_refs_json -> ''attribution'')\n          else ''{}''::jsonb\n        end,\n        packet_status = ''ready'', updated_at = now()\n    where i.id = new.consumer_briefcase_item_id\n      and i.user_id = new.consumer_auth_user_id;\n  end if;\n  return new;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"index:packet_credit_ledger.packet_credit_ledger_pkey":{"ready":true,"valid":true,"definition":"CREATE UNIQUE INDEX packet_credit_ledger_pkey ON public.packet_credit_ledger USING btree (id)"},"column:consumer_artifact_download_grants.content_type":{"type":"text","default":"''application/pdf''::text","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_artifact_provenance.created_at":{"type":"timestamp with time zone","default":"now()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_artifact_provenance.updated_at":{"type":"timestamp with time zone","default":"now()","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT"