ervice_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:packet_render_jobs.retry_reconciliation_history":{"type":"jsonb","default":"''[]''::jsonb","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:sponsored_packet_render_routes.packet_family_id":{"type":"text","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"index:packet_render_jobs.packet_render_jobs_packet_idx":{"ready":true,"valid":true,"definition":"CREATE INDEX packet_render_jobs_packet_idx ON public.packet_render_jobs USING btree (packet_id, created_at)"},"column:consumer_artifact_download_grants.download_count":{"type":"integer","default":"0","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_payment_consumption.amount_cents":{"type":"integer","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:sponsored_packet_render_routes.artifact_provider":{"type":"text","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:sponsored_packet_render_routes.clinic_event_name":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:sponsored_packet_render_routes.registry_track_id":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:consumer_packet_artifact_provenance_immutable":{"consumer_packet_artifact_provenance_immutable()":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.consumer_packet_artifact_provenance_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_erasure boolean := public.rcap_participant_erasure_authority() = ''erase_participant_identifiers'';\n  v_job public.packet_render_jobs%rowtype;\n  v_hash text;\n  v_valid boolean;\n  v_changed boolean;\nbegin\n  if tg_op = ''UPDATE'' then\n    if new.briefcase_item_id is distinct from old.briefcase_item_id\n       or new.matter_id is distinct from old.matter_id\n       or new.entitlement_source is distinct from old.entitlement_source\n       or new.legacy_evidence is distinct from old.legacy_evidence\n       or new.superseded_artifacts is distinct from old.superseded_artifacts then\n      raise exception ''consumer_packet_artifact_provenance: identity and history are immutable'';\n    end if;\n    if new.consumer_auth_user_id is distinct from old.consumer_auth_user_id and not v_erasure then\n      raise exception ''consumer_packet_artifact_provenance: consumer_auth_user_id is immutable once set'';\n    end if;\n    v_changed := new.render_job_id is distinct from old.render_job_id\n      or new.verification_hash is distinct from old.verification_hash\n      or new.artifact is distinct from old.artifact;\n    if v_changed then\n      -- No GUC or caller flag authorizes replacement: the committed job and\n      -- current protected verification independently prove its entire identity.\n      if v_erasure or old.render_job_id is null or new.render_job_id is null\n         or new.render_job_id = old.render_job_id\n         or new.verification_hash is not distinct from old.verification_hash\n         or new.verification_hash is null then\n        raise exception ''consumer_packet_artifact_provenance: replacement requires a new verified job'';\n      end if;\n      select v.verification_hash into v_hash\n      from public.consumer_packet_verifications v\n      join public.consumer_briefcase_items i\n        on i.id = v.briefcase_item_id and i.user_id = v.consumer_auth_user_id\n      where v.briefcase_item_id = new.briefcase_item_id\n        and v.consumer_auth_user_id = new.consumer_auth_user_id\n        and v.matter_id = new.matter_id and v.status = ''verified''\n      for update of v;\n      if v_hash is distinct from new.verification_hash then\n        raise exception ''consumer_packet_artifact_provenance: replacement verification is stale'';\n      end if;\n      select * into v_job from public.packet_render_jobs where id = new.render_job_id;\n      if not found or v_job.matter_id is distinct from new.matter_id\n         or v_job.status not in (''artifact_validated'', ''delivered'')\n         or v_job.delivery_eligibility is distinct from ''eligible''\n         or coalesce(v_job.accounting_result, '''') not in (''zero_charge'', ''consumed'', ''already_consumed'', ''overage_consumed'')\n         or v_job.output_sha256 is null\n         or v_job.output_sha256 is distinct from new.artifact ->> ''artifactSha256''\n         or v_job.output_storage_path is null\n         or v_job.output_storage_path is distinct from new.artifact ->> ''storagePath''\n         or v_job.id::text is distinct from new.artifact ->> ''renderJobId''\n         or new.artifact ->> ''contentType'' is distinct from ''application/pdf''\n         or new.artifact ->> ''provider'' is distinct from old.artifact ->> ''provider'' then\n        raise exception ''consumer_packet_artifact_provenance: replacement artifact is not its validated job'';\n      end if;\n      if new.entitlement_source = ''consumer_payment'' then\n        if v_job.partner_id is not null\n           or v_job.consumer_briefcase_item_id is distinct from new.briefcase_item_id\n           or v_job.consumer_auth_user_id is distinct from new.consumer_auth_user_id\n           or v_job.consumer_verification_hash is distinct from new.verification_hash then\n          raise exception ''consumer_packet_artifact_provenance: replacement consumer binding mismatch'';\n        end if;\n        select a.valid into v_valid from public.consumer_packet_payment_authority(\n          new.briefcase_item_id, new.consumer_auth_user_id,\n          public.expungement_packet_product_id(), v_job.person_id, new.matter_id\n        ) a;\n      elsif new.entitlement_source = ''partner_sponsorship'' then\n        if v_job.partner_id is null\n           or v_job.sponsored_consumer_briefcase_item_id is distinct from new.briefcase_item_id\n           or v_job.sponsored_consumer_auth_user_id is distinct from new.consumer_auth_user_id\n           or v_job.sponsored_verification_hash is distinct from new.verification_hash then\n          raise exception ''consumer_packet_artifact_provenance: replacement sponsored binding mismatch'';\n        end if;\n        select a.valid into v_valid from public.sponsored_packet_render_authority(\n          v_job.sponsored_route_key, v_job.sponsored_session_id,\n          new.briefcase_item_id, new.consumer_auth_user_id\n        ) a;\n      else\n        raise exception ''consumer_packet_artifact_provenance: legacy provenance cannot be replaced'';\n      end if;\n      if not coalesce(v_valid, false) then\n        raise exception ''consumer_packet_artifact_provenance: replacement entitlement refused'';\n      end if;\n      new.superseded_artifacts := old.superseded_artifacts || jsonb_build_array(\n        jsonb_build_object(''revision'', old.revision, ''renderJobId'', old.render_job_id,\n          ''verificationHash'', old.verification_hash, ''entitlementSource'', old.entitlement_source,\n          ''artifact'', old.artifact, ''createdAt'', old.created_at, ''supersededAt'', now()));\n      update public.consumer_artifact_download_grants\n      set revoked_at = coalesce(revoked_at, now())\n      where briefcase_item_id = old.briefcase_item_id and artifact_revision = old.revision;\n    end if;\n    new.revision := old.revision + 1;\n    new.updated_at := now();\n  end if;\n  return new;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":false}},"functions:packet_render_jobs_consumer_binding_immutable":{"packet_render_jobs_consumer_binding_immutable()":{"owner":"postgres","config":null,"execute":{"anon":true,"service_role":true,"authenticated":true,"rcap_render_worker":true,"rcap_packet_delivery":true},"definition":"CREATE OR REPLACE FUNCTION public.packet_render_jobs_consumer_binding_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nbegin\n  if tg_op = ''UPDATE'' then\n    if old.consumer_briefcase_item_id is not null\n       and new.consumer_briefcase_item_id is distinct from old.consumer_briefcase_item_id then\n      raise exception ''packet_render_jobs: consumer_briefcase_item_id is immutable once set'';\n    end if;\n    if old.consumer_auth_user_id is not null\n       and new.consumer_auth_user_id is distinct from old.consumer_auth_user_id then\n      raise exception ''packet_render_jobs: consumer_auth_user_id is immutable once set'';\n    end if;\n    if old.person_id is not null and new.person_id is distinct from old.person_id then\n      raise exception ''packet_render_jobs: person_id is immutable once set'';\n    end if;\n    if old.matter_id is not null and new.matter_id is distinct from old.matter_id then\n      raise exception ''packet_render_jobs: matter_id is immutable once set'';\n    end if;\n  end if;\n  return new;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":true,"securityDefiner":false}},"index:packet_credit_ledger.packet_credit_ledger_job_idx":{"ready":true,"valid":true,"definition":"CREATE INDEX packet_credit_ledger_job_idx ON public.packet_credit_ledger USING btree (render_job_id)"},"index:packet_render_jobs.packet_render_jobs_partner_idx":{"ready":true,"valid":true,"definition":"CREATE INDEX packet_render_jobs_partner_idx ON public.packet_render_jobs USING btree (partner_id, created_at DESC) WHERE (partner_id IS NOT NULL)"},"trigger:packet_credit_ledger.guard_packet_credit_ledger":{"enabled":"O","definition":"CREATE TRIGGER guard_packet_credit_ledger BEFORE INSERT OR DELETE OR UPDATE ON public.packet_credit_ledger FOR EACH ROW EXECUTE FUNCTION guard_packet_credit_ledger()"},"column:consumer_artifact_download_grants.artifact_sha256":{"type":"text","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_briefcase_items.source_pending_result_id":{"type":"uuid","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":true},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_artifact_provenance.render_job_id":{"type":"uuid","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:finalize_sponsored_packet_generation_for_route":{"finalize_sponsored_packet_generation_for_route(text,uuid,uuid,text,jsonb,uuid)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.finalize_sponsored_packet_generation_for_route(p_route_key text, p_session_id uuid, p_briefcase_item_id uuid, p_expected_verification_hash text, p_packet_artifact jsonb, p_render_job_id uuid DEFAULT NULL::uuid)\n RETURNS TABLE(ok boolean, recorded boolean, counted_as text, reason text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_route public.sponsored_packet_render_routes%rowtype;\n  v_item public.consumer_briefcase_items%rowtype;\n  v_verification public.consumer_packet_verifications%rowtype;\n  v_source public.consumer_pending_screening_results%rowtype;\n  v_session public.screening_sessions%rowtype;\n  v_case public.clinic_cases%rowtype;\n  v_event public.clinic_events%rowtype;\n  v_entitlement public.partner_entitlement%rowtype;\n  v_provenance public.consumer_packet_artifact_provenance%rowtype;\n  v_job public.packet_render_jobs%rowtype;\n  v_matter_id uuid;\n  v_event_artifact_count integer;\n  v_counted_as text;\nbegin\n  -- Refuse malformed caller values before taking a lock or changing a row.\n  if p_route_key is null\n     or p_session_id is null\n     or p_briefcase_item_id is null\n     or p_expected_verification_hash !~ ''^[a-f0-9]{64}$''\n     or jsonb_typeof(p_packet_artifact) is distinct from ''object'' then\n    return query select false, false, ''not_counted''::text, ''invalid_input''::text;\n    return;\n  end if;\n\n  select * into v_route from public.sponsored_packet_render_routes r\n   where r.route_key = p_route_key and r.active;\n  if not found then\n    return query select false, false, ''not_counted''::text, ''route_not_registered''::text;\n    return;\n  end if;\n\n  -- The canonical matter is the first lock. The function never accepts an\n  -- owner, matter, route, partner, event, or entitlement from its caller.\n  select * into v_item\n  from public.consumer_briefcase_items i\n  where i.id = p_briefcase_item_id\n  for update;\n  if not found then\n    return query select false, false, ''not_counted''::text, ''wrong_item''::text;\n    return;\n  end if;\n  v_matter_id := public.consumer_matter_id_for_briefcase_item(v_item.id);\n\n  -- Lock the protected verification row immediately after the matter. Display\n  -- JSON and packet_status are intentionally not verification authority.\n  select * into v_verification\n  from public.consumer_packet_verifications v\n  where v.briefcase_item_id = v_item.id\n  for update;\n  if not found\n     or v_verification.status <> ''verified''\n     or v_verification.verification_hash is distinct from p_expected_verification_hash then\n    return query select false, false, ''not_counted''::text, ''verification_mismatch''::text;\n    return;\n  end if;\n  if v_verification.consumer_auth_user_id is distinct from v_item.user_id then\n    return query select false, false, ''not_counted''::text, ''wrong_owner''::text;\n    return;\n  end if;\n  if v_verification.matter_id is distinct from v_matter_id then\n    return query select false, false, ''not_counted''::text, ''wrong_matter''::text;\n    return;\n  end if;\n  if v_item.jurisdiction <> v_route.jurisdiction\n     or v_verification.verification_snapshot ->> ''jurisdiction'' <> v_route.jurisdiction\n     or v_verification.verification_snapshot ->> ''pathwayId'' <> v_route.pathway_id\n     or (v_route.registry_track_id is not null\n         and v_verification.verification_snapshot ->> ''selectedTrackId'' is distinct from v_route.registry_track_id) then\n    return query select false, false, ''not_counted''::text, ''wrong_jurisdiction_or_route''::text;\n    return;\n  end if;\n\n  -- Reconstruct the same protected claimed source used by the server-side\n  -- presentation authority. It binds owner, item, anonymous source session,\n  -- partner product, and Clinic event without trusting request JSON.\n  select * into v_source\n  from public.consumer_pending_screening_results p\n  where p.pending_id = v_item.source_pending_result_id\n  for update;\n  if not found or v_source.status <> ''CLAIMED''\n     or v_source.claimed_matter_id is distinct from v_item.id then\n    return query select false, false, ''not_counted''::text, ''wrong_item''::text;\n    return;\n  end if;\n  if v_source.claimed_user_id is distinct from v_item.user_id then\n    return query select false, false, ''not_counted''::text, ''wrong_owner''::text;\n    return;\n  end if;\n  if v_source.anonymous_session_id is distinct from p_session_id then\n    return query select false, false, ''not_counted''::text, ''wrong_session''::text;\n    return;\n  end if;\n  if v_source.product <> ''rcap_partner''\n     or v_source.partner_slug is distinct from v_route.partner_slug then\n    return query select false, false, ''not_counted''::text, ''wrong_partner''::text;\n    return;\n  end if;\n  if v_source.jurisdiction <> v_route.jurisdiction then\n    return query select false, false, ''not_counted''::text, ''wrong_jurisdiction_or_route''::text;\n    return;\n  end if;\n\n  select * into v_session\n  from public.screening_sessions s\n  where s.session_id = p_session_id\n  for update;\n  if not found\n     or v_session.flow_mode <> ''rcap''\n     or v_session.partner_benefit_active is not true then\n    return query select false, false, ''not_counted''::text, ''sponsorship_inactive''::text;\n    return;\n  end if;\n  if v_session.partner_slug is distinct from v_source.partner_slug then\n    return query select false, false, ''not_counted''::text, ''wrong_partner''::text;\n    return;\n  end if;\n  if v_session.jurisdiction <> v_route.jurisdiction then\n    return query select false, false, ''not_counted''::text, ''wrong_jurisdiction_or_route''::text;\n    return;\n  end if;\n\n  select c.* into v_case\n  from public.clinic_cases c\n  where c.event_id = v_source.event_id\n    and c.participant_user_id = v_item.user_id\n    and c.screening_session_id = p_session_id\n    and c.matter_id = v_item.id\n  for update;\n  if not found then\n    return query select false, false, ''not_counted''::text, ''clinic_scope_mismatch''::text;\n    return;\n  end if;\n  if v_case.jurisdiction <> v_route.jurisdiction or v_case.route_disposition <> ''packet'' then\n    return query select false, false, ''not_counted''::text, ''wrong_jurisdiction_or_route''::text;\n    return;\n  end if;\n\n  select * into v_event\n  from public.clinic_events e\n  where e.id = v_case.event_id\n  for update;\n  if not found\n     or v_event.partner_slug is distinct from v_route.partner_slug\n     or v_event.program_key is distinct from v_route.program_key\n     or (v_route.clinic_event_name is not null and v_event.name is distinct from v_route.clinic_event_name) then\n    return query select false, false, ''not_counted''::text, ''clinic_scope_mismatch''::text;\n    return;\n  end if;\n  if v_event.jurisdiction is distinct from v_route.jurisdiction then\n    return query select false, false, ''not_counted''::text, ''wrong_jurisdiction_or_route''::text;\n    return;\n  end if;\n  if v_event.status <> ''published''\n     or v_event.sponsorship_allocation is null\n     or v_event.sponsorship_allocation <= 0 then\n    return query select false, false, ''not_counted''::text, ''sponsorship_inactive''::text;\n    return;\n  end if;\n\n  -- A participant-deliverable artifact is a Grade-A PDF bound to this exact\n  -- item, verification, specification, family, and immutable byte hash.\n  if p_packet_artifact ->> ''provider'' <> v_route.artifact_provider\n     or p_packet_artifact ->> ''source'' <> v_route.artifact_source\n     or p_packet_artifact ->> ''contentType'' <> v_route.artifact_content_type\n     or p_packet_artifact ->> ''packetId'' <> v_item.id::text\n     or p_packet_artifact ->> ''verificationHash'' <> p_expected_verification_hash\n     or p_packet_artifact ->> ''packetSpecificationId'' <> v_route.packet_specification_id\n     or p_packet_artifact ->> ''packetSpecificationVersion'' <> v_route.packet_specification_version\n     or p_packet_artifact ->> ''packetSpecificationSha256'' <> v_route.packet_specification_sha256\n     or p_packet_artifact ->> ''packetFamily'' <> v_route.packet_family_id\n     or p_packet_artifact ->> ''artifactSha256'' !~ ''^[a-f0-9]{64}$''\n     or coalesce((p_packet_artifact ->> ''pageCount'') ~ ''^[1-9][0-9]*$'', false) is not true\n     or coalesce((p_packet_artifact ->> ''documentCount'') ~ ''^[1-9][0-9]*$'', false) is not true then\n    return query select false, false, ''not_counted''::text, ''malformed_artifact''::text;\n    return;\n  end if;\n\n  -- An optional render job. When the caller names one it must be this\n  -- participant''s own sponsored job for this exact route, session and\n  -- verification, and it must already hold validated, deliverable bytes.\n  if p_render_job_id is not null then\n    select * into v_job\n    from public.packet_render_jobs j\n    where j.id = p_render_job_id\n    for update;\n    if not found\n       or v_job.sponsored_route_key is distinct from v_route.route_key\n       or v_job.sponsored_session_id is distinct from p_session_id\n       or v_job.sponsored_consumer_briefcase_item_id is distinct from v_item.id\n       or v_job.sponsored_consumer_auth_user_id is distinct from v_item.user_id\n       or v_job.sponsored_verification_hash is distinct from p_expected_verification_hash\n       or v_job.matter_id is distinct from v_matter_id\n       or v_job.status not in (''artifact_validated'', ''delivered'')\n       or v_job.delivery_eligibility <> ''eligible''\n       or coalesce(v_job.output_sha256, '''') <> (p_packet_artifact ->> ''artifactSha256'') then\n      return query select false, false, ''not_counted''::text, ''render_job_mismatch''::text;\n      return;\n    end if;\n  end if;\n\n  -- Lock existing provenance before reading the allowance. An exact retry is\n  -- successful and never approaches the credit counter. A changed verification\n  -- may publish another validated job for the same matter without recounting.\n  select * into v_provenance\n  from public.consumer_packet_artifact_provenance p\n  where p.briefcase_item_id = v_item.id\n  for update;\n  if found then\n    if v_provenance.consumer_auth_user_id = v_item.user_id\n       and v_provenance.matter_id = v_matter_id\n       and v_provenance.verification_hash = p_expected_verification_hash\n       and v_provenance.entitlement_source = ''partner_sponsorship''\n       and v_provenance.render_job_id is not distinct from p_render_job_id\n       and v_provenance.artifact = p_packet_artifact then\n      select a.metadata ->> ''counted_as'' into v_counted_as\n      from public.rcap_screening_analytics_events a\n      where a.session_id = p_session_id and a.partner_slug = v_route.partner_slug\n        and a.event_type = ''packet_generated''\n      order by a.occurred_at asc, a.id asc\n      limit 1;\n      return query select true, false, coalesce(v_counted_as, ''not_counted''), ''already_finalized''::text;\n      return;\n    end if;\n    -- A new protected verification can replace the current artifact for the\n    -- same sponsored matter. Every claim/event/route/job check above still ran.\n    -- Existing allowance evidence is reused; no counter or analytics event is\n    -- written on this path. Same-verification byte changes remain conflicts.\n    if p_render_job_id is not null and v_provenance.render_job_id is not null\n       and v_provenance.consumer_auth_user_id = v_item.user_id\n       and v_provenance.matter_id = v_matter_id\n       and v_provenance.entitlement_source = ''partner_sponsorship''\n       and v_provenance.verification_hash is distinct from p_expected_verification_hash\n       and exists (\n         select 1 from public.packet_render_jobs previous\n         where previous.id = v_provenance.render_job_id\n           and previous.sponsored_route_key = p_route_key\n           and previous.sponsored_session_id = p_session_id\n           and previous.sponsored_clinic_event_id = v_event.id\n           and previous.partner_id = v_job.partner_id\n       ) then\n      select a.metadata ->> ''counted_as'' into v_counted_as\n      from public.rcap_screening_analytics_events a\n      where a.session_id = p_session_id and a.partner_slug = v_route.partner_slug\n        and a.event_type = ''packet_generated''\n        and a.metadata ->> ''clinic_event_id'' = v_event.id::text\n      order by a.occurred_at asc, a.id asc limit 1;\n      if v_counted_as not in (''included'', ''overage'') or v_counted_as is null\n         or v_session.claimed_slot_state is distinct from ''consumed'' then\n        return query select false, false, ''not_counted''::text, ''prior_consumption_missing''::text;\n        return;\n      end if;\n      update public.consumer_packet_artifact_provenance\n      set render_job_id = p_render_job_id,\n          verification_hash = p_expected_verification_hash,\n          artifact = p_packet_artifact\n      where briefcase_item_id = v_item.id;\n      update public.consumer_briefcase_items\n      set artifact_refs_json = (p_packet_artifact - ''attribution'') || case\n            when v_item.artifact_refs_json ? ''attribution''\n              then jsonb_build_object(''attribution'', v_item.artifact_refs_json -> ''attribution'')\n            else ''{}''::jsonb\n          end,\n          packet_status = ''ready'', updated_at = now()\n      where id = v_item.id and user_id = v_item.user_id;\n      update public.clinic_cases\n      set queue_status = ''packet_ready'', last_activity_at = now(), updated_at = now()\n      where id = v_case.id;\n      return query select true, false, v_counted_as, ''regenerated''::text;\n      return;\n    end if;\n    return query select false, false, ''not_counted''::text, ''artifact_conflict''::text;\n    return;\n  end if;\n  if v_session.claimed_slot_state is distinct from ''claimed'' then\n    return query select false, false, ''not_counted''::text, ''sponsorship_already_consumed''::text;\n    return;\n  end if;\n\n  if not exists(select 1 from public.allocate_clinic_packet_funding(\n    v_item.id,v_item.user_id,p_expected_verification_hash) f where f.funding_mode=''sponsored'') then\n    return query select false,false,''capped''::text,''sponsor_capacity_requires_dtc''::text; return;\n  end if;\n\n  -- The event allocation is a second, narrower cap around the partner usage\n  -- window. Count only protected sponsored provenance for matters in this\n  -- exact event; a repeat was returned above and therefore cannot recount.\n  select count(*)::integer into v_event_artifact_count\n  from public.consumer_packet_artifact_provenance p\n  join public.clinic_cases c on c.matter_id = p.briefcase_item_id\n  where c.event_id = v_event.id\n    and p.entitlement_source = ''partner_sponsorship'';\n  if v_event_artifact_count >= v_event.sponsorship_allocation then\n    return query select false, false, ''capped''::text, ''event_sponsorship_exhausted''::text;\n    return;\n  end if;\n\n  select * into v_entitlement\n  from public.partner_entitlement pe\n  where pe.partner_slug = v_event.partner_slug\n  for update;\n  if not found then\n    return query select false, false, ''not_counted''::text, ''no_entitlement''::text;\n    return;\n  end if;\n  if v_entitlement.screenings_used < v_entitlement.screenings_allowed then\n    v_counted_as := ''included'';\n  elsif v_entitlement.pause_at_cap then\n    return query select false, false, ''capped''::text, ''paused_at_cap''::text;\n    return;\n  elsif v_entitlement.overage_enabled then\n    v_counted_as := ''overage'';\n  else\n    return query select false, false, ''not_counted''::text, ''cap_reached_no_overage''::text;\n    return;\n  end if;\n\n  -- All refusal branches are above this line. Any unexpected failure below is\n  -- raised so PostgreSQL rolls back the complete transaction rather than\n  -- returning a partially-mutated refusal.\n  if v_counted_as = ''included'' then\n    update public.partner_entitlement pe\n    set screenings_used = pe.screenings_used + 1, updated_at = now()\n    where pe.partner_slug = v_entitlement.partner_slug;\n  else\n    update public.partner_entitlement pe\n    set overage_packets = pe.overage_packets + 1,\n        overage_amount_cents = pe.overage_amount_cents + pe.overage_packet_price_cents,\n        updated_at = now()\n    where pe.partner_slug = v_entitlement.partner_slug;\n  end if;\n\n  update public.screening_sessions s\n  set claimed_slot_state = ''consumed'', status = ''completed'', updated_at = now()\n  where s.session_id = p_session_id and s.claimed_slot_state = ''claimed'';\n  if not found then raise exception ''sponsored finalization lost its locked session''; end if;\n\n  insert into public.rcap_record_events\n    (record_type, record_id, partner_slug, event_type, occurred_at, actor, metadata)\n  values\n    (''partner_entitlement'', v_event.partner_slug, v_event.partner_slug,\n     case when v_counted_as = ''overage''\n       then ''partner_packet_overage_recorded'' else ''partner_packet_credit_consumed'' end,\n     now(), ''system'', jsonb_build_object(\n       ''session_id'', p_session_id,\n       ''briefcase_item_id'', v_item.id,\n       ''counted_as'', v_counted_as,\n       ''clinic_event_id'', v_event.id\n     ));\n\n  insert into public.rcap_screening_analytics_events\n    (session_id, partner_slug, partner_access_code_id, campaign_name,\n     event_type, packet_route_available, occurred_at, metadata)\n  values\n    (v_session.session_id, v_session.partner_slug,\n     v_session.partner_access_code_id, v_session.campaign_name,\n     ''packet_generated'', true, now(),\n     jsonb_build_object(''counted_as'', v_counted_as, ''clinic_event_id'', v_event.id));\n  if v_counted_as = ''overage'' then\n    insert into public.rcap_screening_analytics_events\n      (session_id, partner_slug, partner_access_code_id, campaign_name,\n       event_type, packet_route_available, occurred_at, metadata)\n    values\n      (v_session.session_id, v_session.partner_slug,\n       v_session.partner_access_code_id, v_session.campaign_name,\n       ''packet_overage_recorded'', true, now(),\n       jsonb_build_object(\n         ''overage_packet_price_cents'', v_entitlement.overage_packet_price_cents,\n         ''clinic_event_id'', v_event.id\n       ));\n  end if;\n\n  insert into public.consumer_packet_artifact_provenance(\n    briefcase_item_id, consumer_auth_user_id, matter_id, render_job_id,\n    verification_hash, entitlement_source, artifact\n  ) values (\n    v_item.id, v_item.user_id, v_matter_id, p_render_job_id,\n    p_expected_verification_hash, ''partner_sponsorship'', p_packet_artifact\n  );\n\n  update public.consumer_briefcase_items i\n  set artifact_refs_json = coalesce(i.artifact_refs_json, ''{}''::jsonb) || p_packet_artifact,\n      packet_status = ''ready'', updated_at = now()\n  where i.id = v_item.id and i.user_id = v_item.user_id;\n  if not found then raise exception ''sponsored finalization lost its locked matter''; end if;\n\n  update public.clinic_cases c\n  set queue_status = ''packet_ready'', last_activity_at = now(), updated_at = now()\n  where c.id = v_case.id;\n\n  return query select true, true, v_counted_as, null::text;\nend;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"index:packet_delivery_events.packet_delivery_events_pkey":{"ready":true,"valid":true,"definition":"CREATE UNIQUE INDEX packet_delivery_events_pkey ON public.packet_delivery_events USING btree (id)"},"column:packet_render_jobs.sponsored_consumer_auth_user_id":{"type":"uuid","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":false,"SELECT":true,"UPDATE":false,"REFERENCES":false},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"constraint:packet_credit_ledger.packet_credit_ledger_pkey":{"validated":true,"deferrable":false,"definition":"PRIMARY KEY (id)"},"index:packet_render_jobs.packet_render_jobs_claimable_idx":{"ready":true,"valid":true,"definition":"CREATE INDEX packet_render_jobs_claimable_idx ON public.packet_render_jobs USING btree (renderer_kind, created_at) WHERE (status = ''queued''::text)"},"trigger:packet_render_jobs.guard_packet_render_job_delete":{"enabled":"O","definition":"CREATE TRIGGER guard_packet_render_job_delete BEFORE DELETE ON public.packet_render_jobs FOR EACH ROW EXECUTE FUNCTION guard_packet_render_job_delete()"},"trigger:packet_render_jobs.guard_packet_render_job_insert":{"enabled":"O","definition":"CREATE TRIGGER guard_packet_render_job_insert BEFORE INSERT ON public.packet_render_jobs FOR EACH ROW EXECUTE FUNCTION guard_packet_render_job_insert()"},"column:consumer_artifact_download_grants.artifact_revision":{"type":"integer","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_artifact_download_grants.briefcase_item_id":{"type":"uuid","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_artifact_download_grants.verification_hash":{"type":"text","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_artifact_provenance.legacy_evidence":{"type":"jsonb","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_verifications.consumer_auth_user_id":{"type":"uuid","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_verifications.verification_snapshot":{"type":"jsonb","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"functions:finalize_sponsored_packet_generation_if_verified":{"finalize_sponsored_packet_generation_if_verified(uuid,uuid,text,jsonb)":{"owner":"postgres","config":["search_path=\"\""],"execute":{"anon":false,"service_role":true,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"definition":"CREATE OR REPLACE FUNCTION public.finalize_sponsored_packet_generation_if_verified(p_session_id uuid, p_briefcase_item_id uuid, p_expected_verification_hash text, p_packet_artifact jsonb)\n RETURNS TABLE(ok boolean, recorded boolean, counted_as text, reason text)\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\n  select f.ok, f.recorded, f.counted_as, f.reason\n  from public.finalize_sponsored_packet_generation_for_route(\n    ''MS:non-conviction-expungement-for-dismissal-no-disposition-or-acquittal'',\n    p_session_id, p_briefcase_item_id, p_expected_verification_hash,\n    p_packet_artifact, null\n  ) f;\n$function$\n","grantOptions":{"anon":false,"service_role":false,"authenticated":false,"rcap_render_worker":false,"rcap_packet_delivery":false},"publicExecute":false,"securityDefiner":true}},"column:consumer_artifact_download_grants.last_downloaded_at":{"type":"timestamp with time zone","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:sponsored_packet_render_routes.artifact_content_type":{"type":"text","default":"''application/pdf''::text","notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"index:packet_delivery_events.packet_delivery_events_job_idx":{"ready":true,"valid":true,"definition":"CREATE INDEX packet_delivery_events_job_idx ON public.packet_delivery_events USING btree (render_job_id, created_at)"},"trigger:packet_delivery_events.guard_packet_delivery_events":{"enabled":"O","definition":"CREATE TRIGGER guard_packet_delivery_events BEFORE INSERT OR DELETE OR UPDATE ON public.packet_delivery_events FOR EACH ROW EXECUTE FUNCTION guard_packet_delivery_events()"},"column:consumer_packet_artifact_provenance.briefcase_item_id":{"type":"uuid","default":null,"notNull":true,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_artifact_provenance.verification_hash":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false}}},"column:consumer_packet_payment_consumption.provider_event_id":{"type":"text","default":null,"notNull":false,"identity":"","generated":"","privileges":{"anon":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"service_role":{"INSERT":true,"SELECT":true,"UPDATE":true,"REFERENCES":true},"authenticated":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_render_worker":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":false},"rcap_packet_delivery":{"INSERT":false,"SELECT":false,"UPDATE":false,"REFERENCES":