nition":"CHECK ((product_id = ''expungement_packet''::text))"},"constraint:sponsored_packet_render_routes.sponsored_packet_render_routes_pathway_id_check":{"validated":true,"deferrable":false,"definition":"CHECK ((NULLIF(TRIM(BOTH FROM pathway_id), ''''::text) IS NOT NULL))"},"trigger:consumer_packet_artifact_provenance.consumer_packet_artifact_provenance_immutable":{"enabled":"O","definition":"CREATE TRIGGER consumer_packet_artifact_provenance_immutable BEFORE UPDATE ON public.consumer_packet_artifact_provenance FOR EACH ROW EXECUTE FUNCTION consumer_packet_artifact_provenance_immutable()"},"constraint:consumer_briefcase_items.consumer_briefcase_items_paid_requires_server_evidence":{"validated":true,"deferrable":false,"definition":"CHECK (((payment_status <> ''paid''::text) OR ((payment_authority IS NOT NULL) AND (provider_event_id IS NOT NULL) AND (payment_recorded_at IS NOT NULL) AND (currency = ''usd''::text) AND (regular_price_cents = 5000) AND ((discount_cents >= 0) AND (discount_cents <= regular_price_cents)) AND (amount_cents = (regular_price_cents - discount_cents)) AND (NULLIF(TRIM(BOTH FROM COALESCE(checkout_session_id, ''''::text)), ''''::text) IS NOT NULL) AND (payment_product_id = ''expungement_packet''::text) AND (payment_person_id IS NOT NULL) AND (payment_matter_id = consumer_matter_id_for_briefcase_item(id)))))"},"constraint:consumer_packet_payment_consumption.consumer_payment_consumption_currency_check":{"validated":true,"deferrable":false,"definition":"CHECK ((currency = ''usd''::text))"},"constraint:sponsored_packet_render_routes.sponsored_packet_render_routes_jurisdiction_check":{"validated":true,"deferrable":false,"definition":"CHECK (((jurisdiction = upper(jurisdiction)) AND ((length(jurisdiction) >= 2) AND (length(jurisdiction) <= 3))))"},"constraint:sponsored_packet_render_routes.sponsored_packet_render_routes_partner_slug_check":{"validated":true,"deferrable":false,"definition":"CHECK ((NULLIF(TRIM(BOTH FROM partner_slug), ''''::text) IS N