ct_download_grants.consumer_artifact_download_grants_download_count_check":{"validated":true,"deferrable":false,"definition":"CHECK ((download_count >= 0))"},"constraint:consumer_artifact_download_grants.consumer_artifact_download_grants_artifact_sha256_check":{"validated":true,"deferrable":false,"definition":"CHECK ((artifact_sha256 ~ ''^[a-f0-9]{64}$''::text))"},"constraint:consumer_artifact_download_grants.consumer_artifact_download_grants_briefcase_item_id_fkey":{"validated":true,"deferrable":false,"definition":"FOREIGN KEY (briefcase_item_id) REFERENCES consumer_briefcase_items(id) ON DELETE CASCADE"},"constraint:consumer_packet_artifact_provenance.consumer_packet_artifact_provenance_render_job_id_fkey":{"validated":true,"deferrable":false,"definition":"FOREIGN KEY (render_job_id) REFERENCES packet_render_jobs(id)"},"constraint:consumer_artifact_download_grants.consumer_artifact_download_grants_artifact_revision_check":{"validated":true,"deferrable":false,"definition":"CHECK ((artifact_revision >= 1))"},"constraint:consumer_artifact_download_grants.consumer_artifact_download_grants_verification_hash_check":{"validated":true,"deferrable":false,"definition":"CHECK ((verification_hash ~ ''^[a-f0-9]{64}$''::text))"},"constraint:sponsored_packet_render_routes.sponsored_packet_render_routes_packet_specification_id_check":{"validated":true,"deferrable":false,"definition":"CHECK ((NULLIF(TRIM(BOTH FROM packet_specification_id), ''''::text) IS NOT NULL))"},"constraint:consumer_packet_artifact_provenance.consumer_packet_artifact_provenance_briefcase_item_id_fkey":{"validated":true,"deferrable":false,"definition":"FOREIGN KEY (briefcase_item_id) REFERENCES consumer_briefcase_items(id) ON DELETE CASCADE"},"constraint:sponsored_packet_render_routes.sponsored_packet_render_rout_packet_specification_version_check":{"validated":true,"deferrable":false,"definition":"CHECK ((NULLIF(TRIM(BOTH FROM packet_specification_version), ''''::text) IS NOT NULL))"},"constraint:sponsored_packet_render_routes.sponsored_packet_render_route_packet_specification_sha256_check":{"validated":true,"deferrable":false,"definition":"CHECK ((packet_specification_sha256 ~ ''^[a-f0-9]{64}$''::text))"},"constraint:consumer_artifact_download_grants.consumer_artifact_download_grants_artifact_storage_path_check":{"validated":true,"deferrable":false,"definition":"CHECK ((NULLIF(TRIM(BOTH FROM artifact_storage_path), ''''::text) IS NOT NULL))"},"constraint:consumer_packet_artifact_provenance.consumer_packet_artifact_provenance_verification_hash_check":{"validated":true,"deferrable":false,"definition":"CHECK (((verification_hash IS NULL) OR (verification_hash ~ ''^[a-f0-9]{64}$''::text)))"},"constraint:consumer_packet_artifact_provenance.consumer_packet_artifact_provenance_entitlement_source_check":{"validated":true,"deferrable":false,"definition":"CHECK ((entitlement_source = ANY (ARRAY[''consumer_payment''::text, ''partner_sponsorship''::text, ''legacy_backfill''::text])))"},"constraint:consumer_packet_artifact_provenance.consumer_packet_artifact_provenance_legacy_evidence_required":{"validated":true,"deferrable":false,"definition":"CHECK (((entitlement_source <> ''legacy_backfill''::text) OR (legacy_evidence IS NOT NULL)))"},"constraint:consumer_packet_artifact_provenance.consumer_packet_artifact_provenance_superseded_artifacts_check":{"validated":true,"deferrable":false,"definition":"CHECK ((jsonb_typeof(superseded_artifacts) = ''array''::text))"},"trigger:packet_render_jobs.clinic_sync_packet_reservation_after_job":{"enabled":"O","definition":"CREATE TRIGGER clinic_sync_packet_reservation_after_job AFTER UPDATE OF status, accounting_result, credit_ledger_id ON public.packet_render_jobs FOR EACH ROW EXECUTE FUNCTION clinic_sync_packet_reservation()"},"trigger:consumer_briefcase_items.reject_tombstoned_consumer_briefcase_writes":{"enabled":"O","definition":"CREATE TRIGGER reject_tombstoned_consumer_briefcase_writes BEFORE INSERT ON public.consumer_briefcase_items FOR EACH ROW EXECUTE FUNCTION reject_tombstoned_participant_write()"}}'::jsonb; begin
select catalog into actual from (with relations as (select * from pg_class where relnamespace = 'public'::regnamespace and relname in ('packet_render_jobs','partner_packet_entitlement','packet_credit_ledger','packet_delivery_events','consumer_briefcase_items','consumer_packet_payment_consumption','consumer_packet_verifications','consumer_packet_artifact_provenance','consumer_artifact_download_grants','sponsored_packet_render_routes')),
    functions as (select * from pg_proc where pronamespace = 'public'::regnamespace and proname in ('rcap_packet_mutation_authority','set_partner_packet_entitlement_updated_at','guard_packet_render_job_insert','guard_packet_render_job_transition','guard_packet_render_job_delete','guard_packet_credit_ledger','guard_packet_delivery_events','assert_packet_render_job_fencing','enqueue_packet_render_job','claim_packet_render_job','start_packet_render','start_packet_validation','fail_packet_render_job','release_expired_packet_render_claims','requeue_retryable_packet_render_jobs','requeue_packet_render_job_manual','finalize_packet_render_job','record_packet_delivery_event','packet_entitlement_balance','consume_rcap_packet_credit','packet_render_jobs_guard_transition','guard_packet_render_job_retry_history','consumer_render_job_verification_guard','get_consumer_packet_verification_authority','persist_consumer_packet_verification','consumer_packet_artifact_provenance_immutable','publish_validated_consumer_render_artifact','get_consumer_packet_artifact_authority','authorize_consumer_artifact_download','issue_consumer_artifact_download_grant','revoke_consumer_artifact_download_grant','sponsored_packet_render_authority','enqueue_verified_sponsored_packet_render','finalize_sponsored_packet_generation_for_route','finalize_sponsored_packet_generation_if_verified','consumer_packet_payment_authority','record_consumer_packet_payment','replace_consumer_checkout_session','bind_consumer_checkout_verification','enqueue_verified_consumer_packet_render','consumer_matter_id_for_briefcase_item','expungement_packet_product_id','packet_render_jobs_paid_matter_guard','packet_render_jobs_consumer_binding_immutable','consumer_payment_consumption_binding_guard','rcap_participant_erasure_authority')),
    entries as (
      select 'table:' || c.relname as key, jsonb_build_object('owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,
        'privileges',(select jsonb_object_agg(r, (select jsonb_object_agg(priv,has_table_privilege(r,c.oid,priv))
          from unnest(array['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) priv)) from unnest(array['anon','authenticated','service_role','rcap_render_worker','rcap_packet_delivery']) r),
        'publicAcl',(select coalesce(jsonb_agg(privilege_type order by privilege_type),'[]') from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) where grantee=0)) as value
      from relations c
      union all select 'column:'||c.relname||'.'||a.attname, jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),
        'notNull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),
        'privileges',(select jsonb_object_agg(r, (select jsonb_object_agg(priv,has_column_privilege(r,c.oid,a.attnum,priv))
          from unnest(array['SELECT','INSERT','UPDATE','REFERENCES']) priv)) from unnest(array['anon','authenticated','service_role','rcap_render_worker','rcap_packet_delivery']) r))
      from relations c join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped
      left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum
      union all select 'constraint:'||c.relname||'.'||x.conname, jsonb_build_object('definition',pg_get_constraintdef(x.oid),'validated',x.convalidated,'deferrable',x.condeferrable)
      from relations c join pg_constraint x on x.conrelid=c.oid
      union all select 'index:'||c.relname||'.'||i.relname, jsonb_build_object('definition',pg_get_indexdef(i.oid),'valid',x.indisvalid,'ready',x.indisready)
      from relations c join pg_index x on x.indrelid=c.oid join pg_class i on i.oid=x.indexrelid
      union all select 'trigger:'||c.relname||'.'||t.tgname, jsonb_build_object('definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled)
      from relations c join pg_trigger t on t.tgrelid=c.oid and not t.tgisinternal
      union all select 'policies:'||c.relname, coalesce((select jsonb_agg(jsonb_build_object('name',p.polname,'permissive',p.polpermissive,'command',p.polcmd,
        'roles',(select jsonb_agg(case when r=0 then 'PUBLIC' else pg_get_userbyid(r) end order by r) from unnest(p.polroles) r),
        'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) order by p.polname)
        from pg_policy p where p.polrelid=c.oid),'[]') from relations c
      union all select 'functions:'||name, coalesce((select jsonb_object_agg(p.oid::regprocedure::text,
        jsonb_build_object('owner',pg_get_userbyid(p.proowner),'definition',pg_get_functiondef(p.oid),'securityDefiner',p.prosecdef,'config',p.proconfig,
        'grantOptions',(select jsonb_object_agg(r,has_function_privilege(r,p.oid,'EXECUTE WITH GRANT OPTION')) from unnest(array['anon','authenticated','service_role','rcap_render_worker','rcap_packet_delivery']) r),
        'execute',(select jsonb_object_agg(r,has_function_privilege(r,p.oid,'EXECUTE')) from unnest(array['anon','authenticated','service_role','rcap_render_worker','rcap_packet_delivery']) r),
        'publicExecute',exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) where grantee=0 and privilege_type='EXECUTE')))
        from functions p where p.proname=name),'{}') from unnest(array['rcap_packet_mutation_authority','set_partner_packet_entitlement_updated_at','guard_packet_render_job_insert','guard_packet_render_job_transition','guard_packet_render_job_delete','guard_packet_credit_ledger','guard_packet_delivery_events','assert_packet_render_job_fencing','enqueue_packet_render_job','claim_packet_render_job','start_packet_render','start_packet_validation','fail_packet_render_job','release_expired_packet_render_claims','requeue_retryable_packet_render_jobs','requeue_packet_render_job_manual','finalize_packet_render_job','record_packet_delivery_event','packet_entitlement_balance','consume_rcap_packet_credit','packet_render_jobs_guard_transition','guard_packet_render_job_retry_history','consumer_render_job_verification_guard','get_consumer_packet_verification_authority','persist_consumer_packet_verification','consumer_packet_artifact_provenance_immutable','publish_validated_consumer_render_artifact','get_consumer_packet_artifact_authority','authorize_consumer_artifact_download','issue_consumer_artifact_download_grant','revoke_consumer_artifact_download_grant','sponsored_packet_render_authority','enqueue_verified_sponsored_packet_render','finalize_sponsored_packet_generation_for_route','finalize_sponsored_packet_generation_if_verified','consumer_packet_payment_authority','record_consumer_packet_payment','replace_consumer_checkout_session','bind_consumer_checkout_verification','enqueue_verified_consumer_packet_render','consumer_matter_id_for_briefcase_item','expungement_packet_product_id','packet_render_jobs_paid_matter_guard','packet_render_jobs_consumer_binding_immutable','consumer_payment_consumption_binding_guard','rcap_participant_erasure_authority']) name
      union all select 'browserMutationRpcs', coalesce((select jsonb_agg(p.oid::regprocedure::text order by p.oid::regprocedure::text)
        from pg_proc p where p.pronamespace='public'::regnamespace and p.prosecdef
        and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('authenticated',p.oid,'EXECUTE'))
        and (p.prosrc ~* '(insert[[:space:]]+into|update|delete[[:space:]]+from)[[:space:]]+(public[.])?(packet_render_jobs|packet_credit_ledger|packet_delivery_events|partner_packet_entitlement|rcap_packet_credit_consumptions|rcap_partner_packet_allocation)([[:space:]]|[(])'
          or p.prosrc ~* '(claim_packet_render_job|start_packet_render|start_packet_validation|fail_packet_render_job|finalize_packet_render_job|release_expired_packet_render_claims|requeue_retryable_packet_render_jobs)[[:space:]]*[(]')), '[]')
      union all select 'absent:phase49_accounting', jsonb_build_object(
        'rcap_packet_credit_consumptions',to_regclass('public.rcap_packet_credit_consumptions') is null,
        'rcap_partner_packet_allocation',to_regclass('public.rcap_partner_packet_allocation') is null,
        'packet_render_jobs_guard_transition',not exists(select 1 from pg_trigger where tgrelid='public.packet_render_jobs'::regclass and tgname='packet_render_jobs_guard_transition'))
      union all select 'bucket:rcap-packet-artifacts-private', coalesce((select jsonb_build_object('public',public,'fileSizeLimit',file_size_limit,'allowedMimeTypes',allowed_mime_types)
        from storage.buckets where id='rcap-packet-artifacts-private'),'null')
    ) select jsonb_object_agg(key,value order by key) as catalog from entries) captured;
if actual is distinct from expected then raise exception 'packet_forward_postcondition_failed: %', (select string_agg(k, ', ' order by k) from (select jsonb_object_keys(actual) k union select jsonb_object_keys(expected)) keys where actual->k is distinct from expected->k); end if;
end $catalog_gate$;

do $funding_gate$ declare funding_actual jsonb; begin select catalog into funding_actual from (with objects as (
 select 'table:'||c.relname as key, jsonb_build_object(
 'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,
 'columns',coalesce((select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'acl',a.attacl::text) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'[]'::jsonb),
 'constraints',coalesce((select jsonb_object_agg(conname,jsonb_build_object('type',contype,'definition',pg_get_constraintdef(oid,true),'validated',convalidated)) from pg_constraint where conrelid=c.oid and contype<>'n'),'{}'::jsonb),
 'indexes',coalesce((select jsonb_object_agg(i.relname,jsonb_build_object('definition',pg_get_indexdef(i.oid),'valid',x.indisvalid,'ready',x.indisready)) from pg_index x join pg_class i on i.oid=x.indexrelid where x.indrelid=c.oid),'{}'::jsonb),
 'policies',coalesce((select jsonb_object_agg(polname,jsonb_build_object('permissive',polpermissive,'roles',(select jsonb_agg(case when r=0 then 'public' else pg_get_userbyid(r) end order by case when r=0 then 'public' else pg_get_userbyid(r) end) from unnest(polroles) r),'command',polcmd,'using',pg_get_expr(polqual,polrelid),'check',pg_get_expr(polwithcheck,polrelid))) from pg_policy where polrelid=c.oid),'{}'::jsonb),
 'triggers',coalesce((select jsonb_object_agg(tgname,jsonb_build_object('definition',pg_get_triggerdef(oid,true),'enabled',tgenabled)) from pg_trigger where tgrelid=c.oid and not tgisinternal),'{}'::jsonb),
 'effectivePrivileges',(select jsonb_object_agg(r,(select jsonb_object_agg(priv,jsonb_build_object('allowed',has_table_privilege(r,c.oid,priv),'grantable',has_table_privilege(r,c.oid,priv||' WITH GRANT OPTION'))) from unnest(array['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) priv)) from unnest(array['anon','authenticated','service_role','rcap_render_worker','rcap_packet_delivery']) r),
 'acl',coalesce((select jsonb_agg(jsonb_build_object('role',case when x.grantee=0 then 'public' else pg_get_userbyid(x.grantee) end,'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) order by case when x.grantee=0 then 'public' else pg_get_userbyid(x.grantee) end,x.privilege_type,pg_get_userbyid(x.grantor)) from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x),'[]'::jsonb)
 ) value from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='clinic_packet_funding'
 union all
 select 'function:'||p.proname||'('||replace(oidvectortypes(p.proargtypes),', ', ',')||')',jsonb_build_object(
 'kind',p.prokind,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'securityDefiner',p.prosecdef,'config',p.proconfig,'volatility',p.provolatile,'language',l.lanname,
 'acl',coalesce((select jsonb_agg(jsonb_build_object('role',case when x.grantee=0 then 'public' else pg_get_userbyid(x.grantee) end,'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) order by case when x.grantee=0 then 'public' else pg_get_userbyid(x.grantee) end,x.privilege_type,pg_get_userbyid(x.grantor)) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x),'[]'::jsonb),
 'execute',(select jsonb_object_agg(r,jsonb_build_object('allowed',has_function_privilege(r,p.oid,'EXECUTE'),'grantable',has_function_privilege(r,p.oid,'EXECUTE WITH GRANT OPTION'))) from unnest(array['anon','authenticated','service_role','rcap_render_worker','rcap_packet_delivery']) r)
 ) from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname='public' and p.proname in ('allocate_clinic_packet_funding','clinic_packet_dtc_authorized','clinic_entry_sponsor_capacity')
) select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) as catalog from objects) source; if funding_actual is distinct from '{"table:clinic_packet_funding":{"acl":[{"role":"postgres","grantor":"postgres","grantable":false,"privilege":"DELETE"},{"role":"postgres","grantor":"postgres","grantable":false,"privilege":"INSERT"},{"role":"postgres","grantor":"postgres","grantable":false,"privilege":"MAINTAIN"},{"role":"postgres","grantor":"postgres","grantable":false,"privilege":"REFERENCES"},{"role":"postgres","grantor":"postgres","grantable":false,"privilege":"SELECT"},{"role":"postgres","grantor":"postgres","grantable":false,"privilege":"TRIGGER"},{"role":"postgres","grantor":"postgres","grantable":false,"privilege":"TRUNCATE"},{"role":"postgres","grantor":"postgres","grantable":false,"privilege":"UPDATE"},{"role":"service_role","grantor":"postgres","grantable":false,"privilege":"SELECT"}],"rls":true,"kind":"r","owner":"postgres","columns":[{"acl":null,"name":"briefcase_item_id","type":"uuid","default":null,"notNull":true,"identity":"","generated":""},{"acl":null,"name":"consumer_auth_user_id","type":"uuid","default":null,"notNull":true,"identity":"","generated":""},{"acl":null,"name":"source_session_id","type":"uuid","default":null,"notNull":true,"identity":"","generated":""},{"acl":null,"name":"event_id","type":"uuid","default":null,"notNull":true,"identity":"","generated":""},{"acl":null,"name":"partner_slug","type":"text","default":null,"notNull":true,"identity":"","generated":""},{"acl":null,"name":"packet_entitlement_id","type":"uuid","default":null,"notNull":true,"identity":"","generated":""},{"acl":null,"name":"route_key","type":"text","default":null,"notNull":true,"identity":"","generated":""},{"acl":null,"name":"packet_family_id","type":"text","default":null,"notNull":true,"identity":"","generated":""},{"acl":null,"name":"initial_verification_hash","type":"text","default":null,"notNull":true,"identity":"","generated":""},{"acl":null,"name":"funding_mode","type":"text","default":null,"notNull":true,"identity":"","generated":""},{"acl":null,"name":"reason","type":"text","default":null,"notNull":true,"identity":"","generated":""},{"acl":null,"name":"created_at","type":"timestamp with time zone","default":"now()","notNull":true,"identity":"","generated":""}],"indexes":{"clinic_packet_funding_pkey":{"ready":true,"valid":true,"definition":"CREATE UNIQUE INDEX clinic_packet_funding_pkey ON public.clinic_packet_funding USING btree (briefcase_item_id)"}},"forceRls":false,"policies":{},"triggers":{},"constraints":{"clinic_packet_funding_pkey":{"type":"p","validated":true,"definition":"PRIMARY KEY (briefcase_item_id)"},"clinic_packet_funding_reason_check":{"type":"c","validated":true,"definition":"CHECK (reason = ANY (ARRAY[''slot_reserved''::text, ''event_cap_exhausted''::text, ''partner_cap_exhausted''::text]))"},"clinic_packet_funding_event_id_fkey":{"type":"f","validated":true,"definition":"FOREIGN KEY (event_id) REFERENCES clinic_events(id)"},"clinic_packet_funding_funding_mode_check":{"type":"c","validated":true,"definition":"CHECK (funding_mode = ANY (ARRAY[''sponsored''::text, ''dtc''::text]))"},"clinic_packet_funding_briefcase_item_id_fkey":{"type":"f","validated":true,"definition":"FOREIGN KEY (briefcase_item_id) REFERENCES consumer_briefcase_items(id) ON DELETE CASCADE"},"clinic_packet_funding_packet_entitlement_id_fkey":{"type":"f","validated":true,"definition":"FOREIGN KEY (packet_entitlement_id) REFERENCES partner_packet_entitlement(id)"},"clinic_packet_funding_initial_verification_hash_check":{"type":"c","validated":true,"definition":"CHECK (initial_verification_hash ~ ''^[a-f0-9]{64}$''::text)"}},"effectivePrivileges":{"anon":{"DELETE":{"allowed":false,"grantable":false},"INSERT":{"allowed":false,"grantable":false},"SELECT":{"allowed":false,"grantable":false},"UPDATE":{"allowed":false,"grantable":false},"TRIGGER":{"allowed":false,"grantable":false},"TRUNCATE":{"allowed":false,"grantable":false},"REFERENCES":{"allowed":false,"grantable":false}},"service_role":{"DELETE":{"allowed":false,"grantable":false},"INSERT":{"allowed":false,"grantable":false},"SELECT":{"allowed":true,"grantable":false},"UPDATE":{"allowed":false,"grantable":false},"TRIGGER":{"allowed":false,"grantable":false},"TRUNCATE":{"allowed":false,"grantable":false},"REFERENCES":{"allowed":false,"grantable":false}},"authenticated":{"DELETE":{"allowed":false,"grantable":false},"INSERT":{"allowed":false,"grantable":false},"SELECT":{"allowed":false,"grantable":false},"UPDATE":{"allowed":false,"grantable":false},"TRIGGER":{"allowed":false,"grantable":false},"TRUNCATE":{"allowed":false,"grantable":false},"REFERENCES":{"allowed":false,"grantable":false}},"rcap_render_worker":{"DELETE":{"allowed":false,"grantable":false},"INSERT":{"allowed":false,"grantable":false},"SELECT":{"allowed":false,"grantable":false},"UPDATE":{"allowed":false,"grantable":false},"TRIGGER":{"allowed":false,"grantable":false},"TRUNCATE":{"allowed":false,"grantable":false},"REFERENCES":{"allowed":false,"grantable":false}},"rcap_packet_delivery":{"DELETE":{"allowed":false,"grantable":false},"INSERT":{"allowed":false,"grantable":false},"SELECT":{"allowed":false,"grantable":false},"UPDATE":{"allowed":false,"grantable":false},"TRIGGER":{"allowed":false,"grantable":false},"TRUNCATE":{"allowed":false,"grantable":false},"REFERENCES":{"allowed":false,"grantable":false}}}},"function:clinic_packet_dtc_authorized(uuid,uuid)":{"acl":[{"role":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"role":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"kind":"f","owner":"postgres","config":["search_path=\"\""],"execute":{"anon":{"allowed":false,"grantable":false},"service_role":{"allowed":true,"grantable":false},"authenticated":{"allowed":false,"grantable":false},"rcap_render_worker":{"allowed":false,"grantable":false},"rcap_packet_delivery":{"allowed":false,"grantable":false}},"language":"sql","definition":"CREATE OR REPLACE FUNCTION public.clinic_packet_dtc_authorized(p_item uuid, p_owner uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\n  select exists(select 1 from public.clinic_packet_funding f\n    join public.consumer_briefcase_items i on i.id=f.briefcase_item_id and i.user_id=f.consumer_auth_user_id\n    join public.consumer_pending_screening_results s on s.pending_id=i.source_pending_result_id\n      and s.claimed_matter_id=i.id and s.claimed_user_id=i.user_id and s.status=''CLAIMED''\n      and s.anonymous_session_id=f.source_session_id and s.event_id=f.event_id and s.partner_slug=f.partner_slug\n      and s.product=''rcap_partner''\n    join public.clinic_events e on e.id=f.event_id and e.partner_slug=f.partner_slug\n    join public.clinic_cases c on c.event_id=f.event_id and c.matter_id=i.id\n      and c.participant_user_id=i.user_id and c.screening_session_id=f.source_session_id\n    join public.consumer_packet_verifications v on v.briefcase_item_id=i.id and v.consumer_auth_user_id=i.user_id\n      and (v.verification_snapshot->>''jurisdiction'')||'':''||(v.verification_snapshot->>''pathwayId'')=f.route_key\n    join public.sponsored_packet_render_routes r on r.route_key=f.route_key and r.packet_family_id=f.packet_family_id\n      and (r.registry_track_id is null or r.registry_track_id=v.verification_snapshot->>''selectedTrackId'')\n    where f.briefcase_item_id=p_item and f.consumer_auth_user_id=p_owner and f.funding_mode=''dtc'');\n$function$\n","volatility":"s","securityDefiner":true},"function:clinic_entry_sponsor_capacity(uuid,text)":{"acl":[{"role":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"role":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"kind":"f","owner":"postgres","config":["search_path=\"\""],"execute":{"anon":{"allowed":false,"grantable":false},"service_role":{"allowed":true,"grantable":false},"authenticated":{"allowed":false,"grantable":false},"rcap_render_worker":{"allowed":false,"grantable":false},"rcap_packet_delivery":{"allowed":false,"grantable":false}},"language":"plpgsql","definition":"CREATE OR REPLACE FUNCTION public.clinic_entry_sponsor_capacity(p_event uuid, p_partner text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare e public.clinic_events%rowtype; allowance public.partner_entitlement%rowtype;\n  event_used bigint; reserved bigint; packet_allowance public.partner_packet_entitlement%rowtype; packet_used bigint;\nbegin\n  select * into e from public.clinic_events where id=p_event and partner_slug=p_partner and status=''published'';\n  if not found then raise exception ''invalid_event_scope''; end if;\n  select * into allowance from public.partner_entitlement where partner_slug=e.partner_slug;\n  if not found then raise exception ''missing_sponsor_authority''; end if;\n  select count(*) into event_used from (\n    select f.briefcase_item_id from public.clinic_packet_funding f where f.event_id=e.id and f.funding_mode=''sponsored''\n    union select p.briefcase_item_id from public.consumer_packet_artifact_provenance p\n      join public.clinic_cases c on c.matter_id=p.briefcase_item_id where c.event_id=e.id and p.entitlement_source=''partner_sponsorship''\n  ) used;\n  select count(*) into reserved from public.clinic_packet_funding f where f.partner_slug=e.partner_slug and f.funding_mode=''sponsored''\n    and not exists(select 1 from public.consumer_packet_artifact_provenance p where p.briefcase_item_id=f.briefcase_item_id and p.entitlement_source=''partner_sponsorship'');\n  select ent.* into packet_allowance from public.partner_packet_entitlement ent join public.partner_records p on p.id=ent.partner_id\n    where p.partner_slug=e.partner_slug and ent.effective_at<=now() and (ent.expires_at is null or ent.expires_at>now())\n    order by ent.effective_at desc limit 1;\n  if not found then raise exception ''missing_sponsor_authority''; end if;\n  select count(*) into packet_used from (\n    select l.matter_id from public.packet_credit_ledger l where l.entitlement_id=packet_allowance.id and l.event_type in (''consumed'',''overage_consumed'')\n    union select public.consumer_matter_id_for_briefcase_item(f.briefcase_item_id) from public.clinic_packet_funding f where f.packet_entitlement_id=packet_allowance.id and f.funding_mode=''sponsored''\n  ) used;\n  return event_used<e.sponsorship_allocation and allowance.screenings_used+reserved<allowance.screenings_allowed and packet_used<packet_allowance.packet_cap;\nend;\n$function$\n","volatility":"s","securityDefiner":true},"function:allocate_clinic_packet_funding(uuid,uuid,text)":{"acl":[{"role":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"role":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"kind":"f","owner":"postgres","config":["search_path=\"\""],"execute":{"anon":{"allowed":false,"grantable":false},"service_role":{"allowed":true,"grantable":false},"authenticated":{"allowed":false,"grantable":false},"rcap_render_worker":{"allowed":false,"grantable":false},"rcap_packet_delivery":{"allowed":false,"grantable":false}},"language":"plpgsql","definition":"CREATE OR REPLACE FUNCTION public.allocate_clinic_packet_funding(p_briefcase_item_id uuid, p_consumer_auth_user_id uuid, p_expected_verification_hash text)\n RETURNS TABLE(funding_mode text, reason text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''\nAS $function$\ndeclare\n  v_item public.consumer_briefcase_items%rowtype;\n  v_verification public.consumer_packet_verifications%rowtype;\n  v_source public.consumer_pending_screening_results%rowtype;\n  v_session public.screening_sessions%rowtype;\n  v_case public.clinic_cases%rowtype;\n  v_event public.clinic_events%rowtype;\n  v_entitlement public.partner_entitlement%rowtype;\n  v_choice public.clinic_packet_funding%rowtype;\n  v_packet_entitlement public.partner_packet_entitlement%rowtype;\n  v_packet_used bigint;\n  v_route public.sponsored_packet_render_routes%rowtype;\n  v_scope record;\n  v_event_used bigint;\n  v_partner_reserved bigint;\n  v_mode text := ''sponsored'';\n  v_reason text := ''slot_reserved'';\nbegin\n  -- Match the canonical finalizer lock order. No client-selected sponsor/event.\n  select * into v_item from public.consumer_briefcase_items\n    where id=p_briefcase_item_id and user_id=p_consumer_auth_user_id for update;\n  if not found then return query select ''denied''::text,''wrong_owner''::text; return; end if;\n  select * into v_verification from public.consumer_packet_verifications\n    where briefcase_item_id=v_item.id for update;\n  if not found or v_verification.consumer_auth_user_id is distinct from v_item.user_id\n     or v_verification.matter_id is distinct from public.consumer_matter_id_for_briefcase_item(v_item.id)\n     or v_verification.status is distinct from ''verified''\n     or v_verification.verification_hash is distinct from p_expected_verification_hash\n     or p_expected_verification_hash is null then\n    return query select ''denied''::text,''verification_mismatch''::text; return;\n  end if;\n  select * into v_source from public.consumer_pending_screening_results\n    where pending_id=v_item.source_pending_result_id for update;\n  if not found or v_source.product is distinct from ''rcap_partner''\n     or v_source.claimed_user_id is distinct from v_item.user_id\n     or v_source.claimed_matter_id is distinct from v_item.id or v_source.status is distinct from ''CLAIMED'' then\n    return query select ''denied''::text,''source_mismatch''::text; return;\n  end if;\n  select * into v_session from public.screening_sessions\n    where session_id=v_source.anonymous_session_id for update;\n  select * into v_case from public.clinic_cases\n    where matter_id=v_item.id and participant_user_id=v_item.user_id\n      and screening_session_id=v_source.anonymous_session_id and event_id=v_source.event_id for update;\n  if not found then return query select ''denied''::text,''clinic_scope_mismatch''::text; return; end if;\n  select * into v_event from public.clinic_events where id=v_case.event_id for update;\n  select * into v_route from public.sponsored_packet_render_routes\n    where route_key=(v_verification.verification_snapshot->>''jurisdiction'')||'':''||\n      (v_verification.verification_snapshot->>''pathwayId'') and active;\n  if not found or (v_route.registry_track_id is not null and v_route.registry_track_id is distinct from\n       v_verification.verification_snapshot->>''selectedTrackId'') then\n    return query select ''denied''::text,''route_mismatch''::text; return;\n  end if;\n  select * into v_scope from public.sponsored_packet_render_authority(\n    v_route.route_key, v_source.anonymous_session_id, v_item.id, v_item.user_id);\n  if not coalesce(v_scope.valid,false) then return query select ''denied''::text,v_scope.reason; return; end if;\n  select * into v_choice from public.clinic_packet_funding where briefcase_item_id=v_item.id;\n  if found then\n    if v_choice.consumer_auth_user_id is distinct from v_item.user_id\n       or v_choice.source_session_id is distinct from v_source.anonymous_session_id\n       or v_choice.event_id is distinct from v_event.id or v_choice.partner_slug is distinct from v_event.partner_slug\n       or v_choice.route_key is distinct from v_route.route_key or v_choice.packet_family_id is distinct from v_route.packet_family_id then\n      return query select ''denied''::text,''funding_binding_mismatch''::text; return;\n    end if;\n    return query select v_choice.funding_mode,v_choice.reason; return;\n  end if;\n  -- Reuse delivered Applicant A and other already-consumed packets read-only.\n  if exists(select 1 from public.consumer_packet_artifact_provenance p where p.briefcase_item_id=v_item.id\n      and p.consumer_auth_user_id=v_item.user_id and p.entitlement_source=''partner_sponsorship'') then\n    return query select ''sponsored''::text,''already_consumed''::text; return;\n  end if;\n  if v_session.claimed_slot_state is distinct from ''claimed'' then\n    return query select ''denied''::text,''sponsorship_inactive''::text; return;\n  end if;\n  -- Event and partner locks serialize all contenders, including different\n  -- events sharing the final partner slot. Count reserved OR consumed once.\n  select * into v_entitlement from public.partner_entitlement where partner_slug=v_event.partner_slug for update;\n  if not found then return query select ''denied''::text,''no_entitlement''::text; return; end if;\n  select count(*) into v_event_used from (\n    select p.briefcase_item_id from public.consumer_packet_artifact_provenance p\n      join public.clinic_cases c on c.matter_id=p.briefcase_item_id\n      where c.event_id=v_event.id and p.entitlement_source=''partner_sponsorship''\n    union\n    select f.briefcase_item_id from public.clinic_packet_funding f\n      where f.event_id=v_event.id and f.funding_mode=''sponsored''\n  ) used;\n  select count(*) into v_partner_reserved from public.clinic_packet_funding f\n    where f.partner_slug=v_event.partner_slug and f.funding_mode=''sponsored''\n      and not exists(select 1 from public.consumer_packet_artifact_provenance p\n        where p.briefcase_item_id=f.briefcase_item_id and p.entitlement_source=''partner_sponsorship'');\n  select * into v_packet_entitlement from public.partner_packet_entitlement e\n    where e.partner_id=v_scope.partner_id and e.effective_at<=now()\n      and (e.expires_at is null or e.expires_at>now()) order by e.effective_at desc limit 1 for update;\n  if not found then return query select ''denied''::text,''no_entitlement''::text; return; end if;\n  select count(*) into v_packet_used from (\n    select l.matter_id from public.packet_credit_ledger l where l.entitlement_id=v_packet_entitlement.id\n      and l.event_type in (''consumed'',''overage_consumed'')\n    union\n    select public.consumer_matter_id_for_briefcase_item(f.briefcase_item_id) from public.clinic_packet_funding f\n      where f.packet_entitlement_id=v_packet_entitlement.id and f.funding_mode=''sponsored''\n  ) used;\n  if v_event_used >= v_event.sponsorship_allocation then v_mode:=''dtc''; v_reason:=''event_cap_exhausted'';\n  elsif v_entitlement.screenings_used+v_partner_reserved >= v_entitlement.screenings_allowed\n     or v_packet_used >= v_packet_entitlement.packet_cap then\n    v_mode:=''dtc''; v_reason:=''partner_cap_exhausted'';\n  end if;\n  insert into public.clinic_packet_funding(briefcase_item_id,consumer_auth_user_id,source_session_id,event_id,\n    partner_slug,packet_entitlement_id,route_key,packet_family_id,initial_verification_hash,funding_mode,reason)\n    values(v_item.id,v_item.user_id,v_source.anonymous_session_id,v_event.id,v_event.partner_slug,\n      v_packet_entitlement.id,v_route.route_key,v_route.packet_family_id,p_expected_verification_hash,v_mode,v_reason);\n  return query select v_mode,v_reason;\nend;\n$function$\n","volatility":"v","securityDefiner":true}}'::jsonb then raise exception 'funding_forward_postcondition_failed'; end if; end $funding_gate$;

do $prerequisite_gate$ declare prereq_actual jsonb; begin select to_jsonb(source) into prereq_actual from (with required(name) as (select unnest(array['clinic_events','clinic_cases','consumer_briefcase_items','consumer_packet_verifications','consumer_pending_screening_results','consumer_packet_artifact_provenance','packet_credit_ledger','partner_entitlement','partner_packet_entitlement','partner_records','screening_sessions','sponsored_packet_render_routes','processed_stripe_events'])) select jsonb_object_agg(r.name,jsonb_build_object('present',c.oid is not null,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull) order by a.attname) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped))) as relations, (select coalesce(jsonb_agg(p.oid::regprocedure::text order by p.oid::regprocedure::text),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('consumer_matter_id_for_briefcase_item','sponsored_packet_render_authority')) as function_signatures from required r left join pg_class c on c.oid=to_regclass('public.'||r.name)) source; if prereq_actual is distinct from '{"relations":{"clinic_cases":{"rls":true,"kind":"r","owner":"postgres","columns":[{"name":"assisted_session_id","type":"uuid","notNull":false},{"name":"closed_at","type":"timestamp with time zone","notNull":false},{"name":"county_name","type":"text","notNull":false},{"name":"court_identity_verified","type":"boolean","notNull":true},{"name":"court_name","type":"text","notNull":false},{"name":"created_at","type":"timestamp with time zone","notNull":true},{"name":"event_id","type":"uuid","notNull":true},{"name":"follow_up_due_at","type":"timestamp with time zone","notNull":false},{"name":"follow_up_owner_staff_id","type":"uuid","notNull":false},{"name":"id","type":"uuid","no